    private void cycleStickerColumns() {
        try {
            int next = stickerColumns() >= 6 ? 3 : stickerColumns() + 1;
            profile.put("stickerColumns", next);
            saveProfile();
            refreshStickerGalleryControls();
            refreshStickerGalleryList();
        } catch (JSONException ignored) {
        }
    }

    private String stickerGroupMode() {
        String mode = profile == null ? "day" : profile.optString("stickerGroupMode", "day");
        if (!"week".equals(mode) && !"month".equals(mode)) {
            return "day";
        }
        return mode;
    }

    private String stickerGroupModeTitle() {
        String mode = stickerGroupMode();
        if ("week".equals(mode)) {
            return "周";
        }
        if ("month".equals(mode)) {
            return "月";
        }
        return "天";
    }

    private void cycleStickerGroupMode() {
        try {
            String mode = stickerGroupMode();
            String next = "day".equals(mode) ? "week" : ("week".equals(mode) ? "month" : "day");
            profile.put("stickerGroupMode", next);
            saveProfile();
            refreshStickerGalleryControls();
            refreshStickerGalleryList();
        } catch (JSONException ignored) {
        }
    }

    private void refreshStickerGalleryControls() {
        if (stickerGroupModePill != null) {
            stickerGroupModePill.setText(stickerGroupModeTitle());
        }
        if (stickerColumnsPill != null) {
            stickerColumnsPill.setText(stickerColumns() + "个");
        }
    }

    private void refreshStickerGalleryList() {
        if (stickerGalleryList == null) {
            return;
        }
        final LinearLayout target = stickerGalleryList;
        final int generation = ++stickerGalleryLoadGeneration;
        final String daysSnapshot = days == null ? "{}" : days.toString();
        final boolean includePhotos = photoCollectionEnabled();
        final boolean mergeStacks = galleryStackEnabled();
        final String groupMode = stickerGroupMode();
        target.removeAllViews();
        target.addView(emptyState("正在整理贴纸", "记录较多时会分批载入，不会阻塞页面切换。", "…"));
        stickerGalleryExecutor.execute(new Runnable() {
            @Override
            public void run() {
                List<StickerEntry> stickers = new ArrayList<StickerEntry>();
                try {
                    stickers = collectStickerEntries(new JSONObject(daysSnapshot), includePhotos, mergeStacks);
                } catch (JSONException ignored) {
                }
                final List<StickerGroup> groups = groupStickerEntries(stickers, groupMode);
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        if (!stickerGalleryLoadIsCurrent(generation, target)) {
                            return;
                        }
                        target.removeAllViews();
                        if (groups.isEmpty()) {
                            target.addView(emptyState("还没有贴纸", includePhotos
                                    ? "添加贴纸或普通图片后，会在这里集合。"
                                    : "从相册分享或上传贴纸后，会在这里集合。", "□"));
                            target.addView(space(dp(120)));
                            return;
                        }
                        appendStickerGalleryGroup(target, groups, 0, generation);
                    }
                });
            }
        });
    }

    private Drawable aiCardBackground() {
        if (nightDecoration()) {
            GradientDrawable d = new GradientDrawable(GradientDrawable.Orientation.TL_BR,
                    new int[]{Color.rgb(40, 42, 48), Color.rgb(24, 25, 30)});
            d.setCornerRadius(dp(24));
            d.setStroke(dp(1), Color.argb(82, 220, 226, 236));
            return d;
        }
        GradientDrawable d = new GradientDrawable(GradientDrawable.Orientation.TL_BR,
                new int[]{Color.WHITE, blendColor(accentSoft, Color.WHITE, 0.28f)});
        d.setCornerRadius(dp(24));
        d.setStroke(dp(1), Color.argb(120, Color.red(accentSoft), Color.green(accentSoft), Color.blue(accentSoft)));
        return d;
    }

    private void showAiAnalysisText(String text, boolean loading) {
        if (aiAnalysisResultView == null) {
            return;
        }
        aiAnalysisResultView.removeAllViews();
        String[] lines = text.split("\\r?\\n");
        for (String raw : lines) {
            String line = raw.trim();
            if (line.length() == 0) {
                continue;
            }
            TextView tv = label(line, 15, loading ? Color.rgb(130, 134, 142) : Color.rgb(62, 66, 74), false);
            tv.setLineSpacing(dp(2), 1.08f);
            tv.setPadding(0, dp(4), 0, dp(4));
            aiAnalysisResultView.addView(tv);
        }
    }

    private String aiAnalysisSignature(JSONObject day) {
        StringBuilder sb = new StringBuilder(homeDate());
        for (MealOption mealOption : visibleMealsForDate(homeDate())) {
            JSONObject meal = optObj(day, mealOption.key);
            JSONArray photos = meal.optJSONArray("photos");
            JSONArray stickers = meal.optJSONArray("stickers");
            sb.append("|").append(mealOption.key)
                    .append(":").append(meal.optBoolean("skipped", false) ? "skip" : "eat")
                    .append(":").append(meal.optString("text", "").trim())
                    .append(":p").append(photos == null ? 0 : photos.length())
                    .append(":s").append(stickers == null ? 0 : stickers.length());
        }
        return String.valueOf(sb.toString().hashCode());
    }

    private List<File> aiVisionFiles(JSONObject day) {
        List<File> files = new ArrayList<File>();
        if (!aiVisionEnabled() || !apiVisionSupported()) {
            return files;
        }
        for (MealOption mealOption : visibleMealsForDate(homeDate())) {
            JSONObject meal = optObj(day, mealOption.key);
            addAiVisionFiles(files, meal.optJSONArray("photos"), 2);
            addAiVisionFiles(files, meal.optJSONArray("stickers"), 2);
            if (files.size() >= 6) {
                break;
            }
        }
        return files;
    }

    private void addAiVisionFiles(List<File> files, JSONArray names, int maxPerMeal) {
        if (names == null || files.size() >= 6) {
            return;
        }
        int added = 0;
        for (int i = 0; i < names.length() && added < maxPerMeal && files.size() < 6; i++) {
            String name = names.optString(i, "");
            if (name.length() == 0) {
                continue;
            }
            File file = new File(getFilesDir(), name);
            if (file.exists()) {
                files.add(file);
                added++;
            }
        }
    }

    private String aiNutritionPrompt(String date, JSONObject day) {
        StringBuilder prompt = new StringBuilder();
        prompt.append("你是一蔬一饭的餐饮分析助手，是一个温柔、像朋友一样说话的营养师。");
        prompt.append("请根据一蔬一饭里的记录，估算今日总热量和每顿热量，并给简洁饮食建议。");
        prompt.append("回答最多3句话，总字数尽量不超过130个中文字符，不要长篇分点，不要像报告。");
        prompt.append("语气自然一点，可以偶尔带一个合适的表情或颜文字，例如(｡•̀ᴗ-)✧、(´▽`ʃ♡ƪ)、🍚，但不要每句都加。");
        prompt.append("如果某餐标记没吃，只说这餐没吃，不要估算这餐热量。");
        prompt.append("个人信息和饮食偏好只作为背景参考，不要刻意复述这些字段。");
        prompt.append("日期：").append(displayDate(date)).append("。");
        prompt.append("个人信息：").append(aiProfileSummary()).append("。");
        prompt.append("今日记录：").append(caloriePromptSummary(date, day)).append("。");
        if (aiRecordAccessEnabled()) {
            String recent = recentDietSummary(date, 7);
            if (recent.length() > 0) {
                prompt.append("最近几天记录：").append(recent).append("。");
            }
        }
        if (aiVisionEnabled()) {
            prompt.append("如果随请求附带图片或贴纸，请结合画面粗略识别食物；如果模型看不到图片，请直接说明只能按文字粗略估算。");
        }
        return prompt.toString();
    }

    private String aiProfileSummary() {
        int height = profile.optInt("aiHeightCm", 0);
        int weight = profile.optInt("aiWeightKg", 0);
        StringBuilder sb = new StringBuilder();
        String gender = profile.optString("aiGender", "");
        if (gender.length() > 0) {
            sb.append("性别").append(gender);
        }
        if (height > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append("身高").append(height).append("cm");
        }
        if (weight > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append("体重").append(weight).append("kg");
        }
        float bmi = bmiValue();
        if (bmi > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append("BMI约").append(String.format(Locale.CHINA, "%.1f", bmi));
        }
        String habit = profile.optString("aiMealHabit", "");
        if (habit.length() > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append("餐饮习惯").append(habit);
        }
        String methods = joinStringArray(normalizedDiningMethods(profile.optJSONArray("aiDiningMethods")), "、");
        if (methods.length() > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append("常用就餐方式").append(methods);
        }
        String spend = profile.optString("aiMealSpend", "");
        if (spend.length() > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append("平均每餐消费").append(spend);
        }
        return sb.length() == 0 ? "未填写" : sb.toString();
    }

    private String recentDietSummary(String date, int maxDays) {
        List<String> dates = recordedDates();
        Collections.reverse(dates);
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (String key : dates) {
            if (key.compareTo(date) >= 0) {
                continue;
            }
            String summary = caloriePromptSummary(key, ensureDay(key));
            if (summary.length() == 0) {
                continue;
            }
            if (sb.length() > 0) {
                sb.append("；");
            }
            sb.append(displayMonthDay(key)).append("：").append(summary);
            count++;
            if (count >= maxDays) {
                break;
            }
        }
        return sb.toString();
    }

    private String aiReadableRecordSummary(int maxDays) {
        List<String> dates = recordedDates();
        Collections.reverse(dates);
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (String key : dates) {
            JSONObject day = ensureDay(key);
            StringBuilder dayText = new StringBuilder();
            for (MealOption mealOption : visibleMealsForDate(key)) {
                JSONObject meal = optObj(day, mealOption.key);
                String text = meal.optString("text", "").trim();
                JSONArray photos = meal.optJSONArray("photos");
                JSONArray stickers = meal.optJSONArray("stickers");
                int mediaCount = (photos == null ? 0 : photos.length()) + (stickers == null ? 0 : stickers.length());
                String dining = mealDiningText(key, mealOption.key);
                if (dayText.length() > 0) {
                    dayText.append("，");
                }
                dayText.append(mealOption.title).append("=");
                if (meal.optBoolean("skipped", false)) {
                    dayText.append("标记没吃");
                } else if (text.length() > 0) {
                    dayText.append(text);
                } else if (mediaCount > 0) {
                    dayText.append("有图片/贴纸").append(mediaCount).append("张");
                } else {
                    dayText.append("未记录");
                }
                if (dining.length() > 0) {
                    dayText.append("，方式").append(dining);
                }
            }
            if (sb.length() > 0) {
                sb.append("；");
            }
            sb.append(displayMonthDay(key)).append("：").append(dayText);
            count++;
            if (count >= maxDays || sb.length() > 2600) {
                break;
            }
        }
        return sb.length() == 0 ? "暂无历史记录" : sb.toString();
    }

    private String aiRecordStatsSummary(int maxDays) {
        List<String> dates = recordedDates();
        Collections.reverse(dates);
        int daysSeen = 0;
        StringBuilder sb = new StringBuilder();
        for (MealOption mealOption : allMealOptions()) {
            int skipped = 0;
            int empty = 0;
            int eaten = 0;
            daysSeen = 0;
            for (String key : dates) {
                JSONObject meal = optObj(ensureDay(key), mealOption.key);
                JSONArray photos = meal.optJSONArray("photos");
                JSONArray stickers = meal.optJSONArray("stickers");
                boolean hasRecord = meal.optString("text", "").trim().length() > 0
                        || (photos != null && photos.length() > 0)
                        || (stickers != null && stickers.length() > 0);
                if (meal.optBoolean("skipped", false)) {
                    skipped++;
                } else if (hasRecord) {
                    eaten++;
                } else {
                    empty++;
                }
                daysSeen++;
                if (daysSeen >= maxDays) {
                    break;
                }
            }
            if (sb.length() > 0) {
                sb.append("；");
            }
            sb.append("最近").append(daysSeen).append("天").append(mealOption.title)
                    .append("：吃了").append(eaten)
                    .append("天，标记没吃").append(skipped)
                    .append("天，未记录").append(empty).append("天");
        }
        return sb.toString();
    }

    private String aiChatMemorySummary(int maxMessages) {
        List<String> dates = aiChatDates();
        if (dates.isEmpty()) {
            return "暂无历史聊天";
        }
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (String key : dates) {
            if (key.equals(homeDate())) {
                continue;
            }
            JSONArray chat = optObj(days, key).optJSONArray("aiChat");
            if (chat == null || chat.length() == 0) {
                continue;
            }
            for (int i = Math.max(0, chat.length() - 6); i < chat.length(); i++) {
                JSONObject item = chat.optJSONObject(i);
                if (item == null) {
                    continue;
                }
                String text = item.optString("text", "").trim();
                if (text.length() == 0) {
                    continue;
                }
                if (sb.length() > 0) {
                    sb.append("；");
                }
                sb.append(displayMonthDay(key)).append(item.optString("role", "assistant").equals("user") ? "用户：" : "助手：")
                        .append(text.length() > 70 ? text.substring(0, 70) : text);
                count++;
                if (count >= maxMessages || sb.length() > 1800) {
                    return sb.toString();
                }
            }
        }
        return sb.length() == 0 ? "暂无历史聊天" : sb.toString();
    }

    private void requestAiAnalysis(final String date, boolean force) {
        if (!apiEnabled()) {
            showGlassToast("请先在实验性功能里配置 API", Toast.LENGTH_LONG);
            configureApi();
            return;
        }
        final JSONObject day = ensureDay(date);
        final String signature = aiAnalysisSignature(day);
        if (!force && signature.equals(day.optString("aiAnalysisSignature", ""))
                && day.optString("aiAnalysisText", "").trim().length() > 0) {
            showAiAnalysisText(day.optString("aiAnalysisText", ""), false);
            return;
        }
        if (aiAnalyzeButtonView != null) {
            aiAnalyzeButtonView.setText("分析中...");
            aiAnalyzeButtonView.setEnabled(false);
        }
        showAiAnalysisText("餐饮分析正在认真看今天的饭饭...", true);
        final String endpoint = apiEndpoint();
        final String key = profile.optString("apiKey", "");
        final String model = apiModelName();
        final String prompt = aiNutritionPrompt(date, day);
        final List<File> visionFiles = aiVisionFiles(day);
        new Thread(new Runnable() {
            @Override
            public void run() {
                final String answer = visionFiles.isEmpty()
                        ? callChatApi(endpoint, key, model, prompt)
                        : callChatApiWithImages(endpoint, key, model, prompt, visionFiles);
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        if (aiAnalyzeButtonView != null) {
                            aiAnalyzeButtonView.setText("重新分析");
                            aiAnalyzeButtonView.setEnabled(true);
                        }
                        if (answer.length() == 0) {
                            showAiAnalysisText("刚刚没连上模型，等网络稳一点再试试。", false);
                            return;
                        }
                        try {
                            JSONObject target = ensureDay(date);
                            String compact = compactAiAnswer(answer, 3, 150);
                            target.put("aiAnalysisText", compact);
                            target.put("aiAnalysisSignature", signature);
                            saveDays();
                            showAiAnalysisText(compact, false);
                            return;
                        } catch (JSONException ignored) {
                        }
                        showAiAnalysisText(compactAiAnswer(answer, 3, 150), false);
                    }
                });
            }
        }).start();
    }

    private void askAiNutritionQuestion() {
        if (aiQuestionInput == null) {
            return;
        }
        final String question = aiQuestionInput.getText().toString().trim();
        if (question.length() == 0) {
            showGlassToast("先写一个想问的问题", Toast.LENGTH_SHORT);
            return;
        }
        if (!isNutritionQuestion(question)) {
            showGlassToast("这里只能回答饮食、营养和健康记录相关的问题", Toast.LENGTH_LONG);
            return;
        }
        if (!apiEnabled()) {
            configureApi();
            return;
        }
        final String date = homeDate();
        aiQuestionInput.setText("");
        hideKeyboard();
        if (aiQuestionInput != null) {
            aiQuestionInput.clearFocus();
        }
        appendAiChatMessage(date, "user", question);
        renderAiChatHistory(date);
        addTemporaryAiChatLoading();
        scrollAiAnalysisToBottom();
        final String endpoint = apiEndpoint();
        final String key = profile.optString("apiKey", "");
        final String model = apiModelName();
        final List<File> visionFiles = aiVisionFiles(ensureDay(date));
        final String recordContext = aiRecordAccessEnabled()
                ? "。用户已开启AI读取记录，下面是最近记录摘要：" + aiReadableRecordSummary(60)
                + "。记录统计：" + aiRecordStatsSummary(60)
                : "";
        final String memoryContext = aiChatMemoryEnabled()
                ? "。用户已开启聊天记忆，下面是最近聊天摘要：" + aiChatMemorySummary(18)
                : "";
        final String prompt = "你是用户的营养师朋友。只回答饮食、营养、热量、体重管理和健康记录相关内容。"
                + "回答像人类一样简洁，一句话一句话说，最多4句话，不要过多分点。"
                + "个人信息和饮食偏好只作为背景参考，不要刻意复述这些字段。"
                + "用户个人信息：" + aiProfileSummary()
                + "。今日记录：" + caloriePromptSummary(date, ensureDay(date))
                + recordContext
                + memoryContext
                + "。用户问题：" + question;
        new Thread(new Runnable() {
            @Override
            public void run() {
                final String answer = visionFiles.isEmpty()
                        ? callChatApi(endpoint, key, model, prompt)
                        : callChatApiWithImages(endpoint, key, model, prompt, visionFiles);
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        appendAiChatMessage(date, "assistant", answer.length() == 0 ? "刚刚没连上模型，等一下再问我。"
                                : compactAiAnswer(answer, 4, 180));
                        renderAiChatHistory(date);
                        scrollAiAnalysisToBottom();
                    }
                });
            }
        }).start();
    }

    private void renderAiChatHistory(String date) {
        if (aiChatListView == null) {
            return;
        }
        aiChatListView.removeAllViews();
        JSONArray chat = ensureDay(date).optJSONArray("aiChat");
        if (chat == null || chat.length() == 0) {
            return;
        }
        TextView title = label("聊天记录", 16, Color.rgb(46, 50, 58), true);
        title.setPadding(dp(2), dp(8), 0, dp(8));
        aiChatListView.addView(title);
        int start = Math.max(0, chat.length() - 30);
        for (int i = start; i < chat.length(); i++) {
            JSONObject item = chat.optJSONObject(i);
            if (item == null) {
                continue;
            }
            String role = item.optString("role", "assistant");
            String text = item.optString("text", "").trim();
            if (text.length() == 0) {
                continue;
            }
            aiChatListView.addView(aiChatBubble(role, text));
        }
    }

    private void addTemporaryAiChatLoading() {
        if (aiChatListView != null) {
            aiChatListView.addView(aiChatBubble("assistant", "我正在想，等我一下下..."));
        }
    }

    private View aiChatBubble(String role, String text) {
        LinearLayout row = row("user".equals(role) ? Gravity.RIGHT : Gravity.LEFT);
        row.setPadding(0, dp(5), 0, dp(5));
        boolean user = "user".equals(role);
        TextView bubble = label(text, 14, user ? themedTextColor(Color.rgb(64, 58, 42)) : themedTextColor(Color.rgb(62, 62, 60)), false);
        bubble.setLineSpacing(dp(2), 1.06f);
        bubble.setPadding(dp(15), dp(10), dp(15), dp(10));
        int fill = user
                ? (nightDecoration() ? Color.argb(220, 78, 70, 44) : Color.argb(224, 242, 226, 166))
                : (nightDecoration() ? Color.argb(226, 46, 47, 49) : Color.argb(232, 247, 247, 243));
        int stroke = user
                ? (nightDecoration() ? Color.argb(96, 244, 219, 126) : Color.argb(122, 226, 199, 108))
                : (nightDecoration() ? Color.argb(88, 255, 255, 255) : Color.argb(112, 214, 214, 208));
        bubble.setBackground(round(fill, dp(18), stroke, dp(1)));
        row.addView(bubble, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT,
                ViewGroup.LayoutParams.WRAP_CONTENT));
        bubble.setMaxWidth(Math.min(getResources().getDisplayMetrics().widthPixels - dp(108), dp(user ? 310 : 326)));
        return row;
    }

    private void appendAiChatMessage(String date, String role, String text) {
        if (text == null || text.trim().length() == 0) {
            return;
        }
        try {
            JSONObject day = ensureDay(date);
            JSONArray old = day.optJSONArray("aiChat");
            JSONArray next = new JSONArray();
            if (old != null) {
                int start = Math.max(0, old.length() - 39);
                for (int i = start; i < old.length(); i++) {
                    JSONObject item = old.optJSONObject(i);
                    if (item != null) {
                        next.put(item);
                    }
                }
            }
            JSONObject item = new JSONObject();
            item.put("role", role);
            item.put("text", text.trim());
            item.put("time", System.currentTimeMillis());
            next.put(item);
            day.put("aiChat", next);
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private void scrollAiAnalysisToBottom() {
        if (aiAnalysisScrollView == null) {
            return;
        }
        aiAnalysisScrollView.postDelayed(new Runnable() {
            @Override
            public void run() {
                aiAnalysisScrollView.fullScroll(View.FOCUS_DOWN);
            }
        }, 120);
    }

    private String compactAiAnswer(String answer, int maxSentences, int maxChars) {
        if (answer == null) {
            return "";
        }
        String text = answer.replace("\r", "\n")
                .replace("•", "")
                .replace("*", "")
                .trim();
        if (text.length() == 0) {
            return "";
        }
        text = text.replaceAll("\\n+", "。");
        StringBuilder out = new StringBuilder();
        int sentences = 0;
        StringBuilder current = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            current.append(c);
            if (c == '。' || c == '！' || c == '？' || c == '~' || c == '～') {
                String sentence = current.toString().trim();
                if (sentence.length() > 0) {
                    if (out.length() > 0) {
                        out.append("\n");
                    }
                    out.append(sentence);
                    sentences++;
                    if (sentences >= maxSentences || out.length() >= maxChars) {
                        break;
                    }
                }
                current.setLength(0);
            }
        }
        if (out.length() == 0 && current.length() > 0) {
            out.append(current.toString().trim());
        } else if (sentences < maxSentences && current.length() > 0 && out.length() < maxChars) {
            String rest = current.toString().trim();
            if (rest.length() > 0) {
                if (out.length() > 0) {
                    out.append("\n");
                }
                out.append(rest);
            }
        }
        if (out.length() > maxChars) {
            return out.substring(0, Math.max(0, maxChars - 1)).trim() + "…";
        }
        return out.toString().trim();
    }

    private boolean isNutritionQuestion(String question) {
        String lower = question.toLowerCase(Locale.US);
        String[] keys = {"吃", "餐", "饭", "热量", "卡路里", "营养", "蛋白", "脂肪", "碳水", "体重", "减肥", "增肌", "健康",
                "早餐", "午餐", "晚餐", "夜宵", "水果", "蔬菜", "肉", "糖", "饮食", "bmi", "calorie", "diet", "food", "weight"};
        for (String key : keys) {
            if (lower.contains(key.toLowerCase(Locale.US))) {
                return true;
            }
        }
        return false;
    }

    private float bmiValue() {
        int height = profile == null ? 0 : profile.optInt("aiHeightCm", 0);
        int weight = profile == null ? 0 : profile.optInt("aiWeightKg", 0);
        if (height <= 0 || weight <= 0) {
            return 0f;
        }
        float m = height / 100f;
        return weight / (m * m);
    }

    private String bmiTitle() {
        float bmi = bmiValue();
        if (bmi <= 0) {
            return "BMI 未填写";
        }
        String type;
        if (bmi < 18.5f) {
            type = "偏轻";
        } else if (bmi < 24f) {
            type = "正常";
        } else if (bmi < 28f) {
            type = "超重";
        } else {
            type = "偏高";
        }
        return "BMI " + String.format(Locale.CHINA, "%.1f", bmi) + " · " + type;
    }

