    private TextView profileChoiceValue(String value) {
        TextView view = label(value, 14,
                nightDecoration() ? Color.rgb(178, 182, 190) : Color.rgb(96, 100, 108), false);
        view.setGravity(Gravity.CENTER_VERTICAL | Gravity.RIGHT);
        view.setSingleLine(true);
        return view;
    }

    private View profileChoiceRow(String titleText, TextView valueView, View.OnClickListener listener) {
        LinearLayout row = row(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(2), dp(12), dp(2), 0);
        row.setClickable(true);
        attachPressAnimation(row);
        row.setOnClickListener(listener);
        TextView title = label(titleText, 14,
                nightDecoration() ? Color.rgb(166, 170, 178) : Color.rgb(98, 102, 110), true);
        row.addView(title, new LinearLayout.LayoutParams(dp(100), dp(44)));
        row.addView(valueView, new LinearLayout.LayoutParams(0, dp(44), 1));
        TextView arrow = label("›", 22, Color.rgb(150, 154, 162), true);
        arrow.setGravity(Gravity.CENTER);
        row.addView(arrow, new LinearLayout.LayoutParams(dp(22), dp(44)));
        return row;
    }

    private void chooseProfileSingleOption(String titleText, String[] names, final String[] values,
                                           final String profileKey, final TextView target) {
        String current = profile.optString(profileKey, "");
        int selected = 0;
        for (int i = 0; i < values.length; i++) {
            if (values[i].equals(current)) {
                selected = i;
                break;
            }
        }
        showChoiceDialog(titleText, names, selected, new ChoiceHandler() {
            @Override
            public void onChoice(int which) {
                if (which < 0 || which >= values.length) {
                    return;
                }
                try {
                    profile.put(profileKey, values[which]);
                    saveCloudProfileFields();
                    if (target != null) {
                        if ("aiGender".equals(profileKey)) {
                            target.setText(aiGenderTitle());
                        } else if ("aiMealHabit".equals(profileKey)) {
                            target.setText(aiMealHabitTitle());
                        } else if ("aiMealSpend".equals(profileKey)) {
                            target.setText(aiMealSpendTitle());
                        }
                    }
                    if (inProfileSettingsPage) {
                        renderProfileSettingsPage();
                    }
                    showGlassToast("已保存", Toast.LENGTH_SHORT);
                } catch (JSONException ignored) {
                }
            }
        });
    }

    private void chooseDiningMethods(final TextView target) {
        final AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(22), dp(20), dp(22), dp(18));
        box.setBackground(round(dialogSurfaceColor(), dp(26), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        box.addView(label("就餐方式", 22, Color.rgb(28, 28, 30), true));
        TextView tip = label("可以多选，AI 会作为背景参考。", 13, Color.rgb(120, 124, 132), false);
        tip.setPadding(0, dp(8), 0, dp(10));
        box.addView(tip);
        final JSONArray selected = normalizedDiningMethods(profile.optJSONArray("aiDiningMethods"));
        LinearLayout chips = new LinearLayout(this);
        chips.setOrientation(LinearLayout.VERTICAL);
        box.addView(chips);
        for (int i = 0; i < DINING_METHOD_OPTIONS.length; i++) {
            final String option = DINING_METHOD_OPTIONS[i];
            final TextView chip = label(option, 16,
                    stringArrayContains(selected, option) ? Color.WHITE : Color.rgb(62, 66, 74), true);
            chip.setGravity(Gravity.CENTER_VERTICAL);
            chip.setPadding(dp(14), 0, dp(14), 0);
            chip.setBackground(round(stringArrayContains(selected, option) ? accent : Color.rgb(246, 248, 250),
                    dp(17), stringArrayContains(selected, option) ? 0 : surfaceStrokeColor(), dp(1)));
            attachPressAnimation(chip);
            chip.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    toggleStringInArray(selected, option);
                    boolean on = stringArrayContains(selected, option);
                    chip.setTextColor(on ? Color.WHITE : Color.rgb(62, 66, 74));
                    chip.setBackground(round(on ? accent : Color.rgb(246, 248, 250),
                            dp(17), on ? 0 : surfaceStrokeColor(), dp(1)));
                }
            });
            LinearLayout.LayoutParams chipLp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(42));
            chipLp.topMargin = dp(6);
            chips.addView(chip, chipLp);
        }
        LinearLayout actions = row(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        actions.setPadding(0, dp(16), 0, 0);
        TextView cancel = dialogButton("取消", Color.rgb(245, 246, 248), Color.rgb(90, 90, 90));
        TextView save = dialogButton("保存", accent, Color.WHITE);
        cancel.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                dialog.dismiss();
            }
        });
        save.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                try {
                    profile.put("aiDiningMethods", normalizedDiningMethods(selected));
                    saveCloudProfileFields();
                    if (target != null) {
                        target.setText(aiDiningMethodsTitle());
                    }
                    dialog.dismiss();
                    if (inProfileSettingsPage) {
                        renderProfileSettingsPage();
                    }
                    showGlassToast("已保存", Toast.LENGTH_SHORT);
                } catch (JSONException ignored) {
                }
            }
        });
        LinearLayout.LayoutParams cancelLp = new LinearLayout.LayoutParams(dp(78), dp(42));
        cancelLp.rightMargin = dp(10);
        actions.addView(cancel, cancelLp);
        actions.addView(save, new LinearLayout.LayoutParams(dp(78), dp(42)));
        box.addView(actions);
        showRoundedDialog(dialog, box);
    }

    private String aiGenderTitle() {
        String gender = profile.optString("aiGender", "");
        return gender.length() == 0 ? "未填写" : gender;
    }

    private String aiMealHabitTitle() {
        String habit = profile.optString("aiMealHabit", "");
        return habit.length() == 0 ? "未填写" : habit;
    }

    private String aiMealSpendTitle() {
        String spend = profile.optString("aiMealSpend", "");
        return spend.length() == 0 ? "未填写" : spend;
    }

    private String aiDiningMethodsTitle() {
        JSONArray arr = normalizedDiningMethods(profile.optJSONArray("aiDiningMethods"));
        String joined = joinStringArray(arr, "、");
        return joined.length() == 0 ? "未填写" : joined;
    }

    private String profileHeightWeightTitle() {
        int height = profile.optInt("aiHeightCm", 0);
        int weight = profile.optInt("aiWeightKg", 0);
        if (height <= 0 && weight <= 0) {
            return "未填写";
        }
        StringBuilder sb = new StringBuilder();
        if (height > 0) {
            sb.append(height).append("cm");
        }
        if (weight > 0) {
            if (sb.length() > 0) sb.append("，");
            sb.append(weight).append("kg");
        }
        float bmi = bmiValue();
        if (bmi > 0) {
            sb.append("，BMI约").append(String.format(Locale.CHINA, "%.1f", bmi));
        }
        return sb.toString();
    }

    private boolean hasCloudIdentity() {
        return profile != null
                && profile.optString("userId", "").length() > 0
                && profile.optString("cloudToken", "").length() > 0;
    }

    private String wechatBindTitle() {
        if (profile == null || profile.optString("userId", "").length() == 0) {
            return "创建账号后可绑定";
        }
        return profile.optBoolean("cloudWechatBound", false)
                ? "已绑定，后续云服务会限制一个 ID 绑定一个微信"
                : "暂未开放，需接入微信授权后启用";
    }

