                try {
                    profile.put("aiHeightCm", parseIntSafe(height.getText().toString()));
                    profile.put("aiWeightKg", parseIntSafe(weight.getText().toString()));
                    saveCloudProfileFields();
                } catch (JSONException ignored) {
                }
                dialog.dismiss();
