    private JSONArray copyStringArray(JSONArray source) {
        JSONArray out = new JSONArray();
        if (source == null) {
            return out;
        }
        for (int i = 0; i < source.length(); i++) {
            String value = source.optString(i);
            if (value.length() > 0) {
                out.put(value);
            }
        }
        return out;
    }

    private JSONArray normalizedDiningMethods(JSONArray source) {
        JSONArray normalized = new JSONArray();
        for (String option : DINING_METHOD_OPTIONS) {
            if (containsDiningMethod(source, option)) {
                normalized.put(option);
            }
        }
        return normalized;
    }

    private boolean containsDiningMethod(JSONArray source, String option) {
        if (source == null || option == null) {
            return false;
        }
        for (int i = 0; i < source.length(); i++) {
            Object raw = source.opt(i);
            if (raw instanceof JSONArray && containsDiningMethod((JSONArray) raw, option)) {
                return true;
            }
            String value = source.optString(i, "").trim();
            if (option.equals(value)) {
                return true;
            }
            if (value.startsWith("[") && value.endsWith("]")) {
                try {
                    if (containsDiningMethod(new JSONArray(value), option)) {
                        return true;
                    }
                } catch (JSONException ignored) {
                }
            }
        }
        return false;
    }

    private boolean stringArrayContains(JSONArray arr, String value) {
        if (arr == null || value == null) {
            return false;
        }
        for (int i = 0; i < arr.length(); i++) {
            if (value.equals(arr.optString(i))) {
                return true;
            }
        }
        return false;
    }

    private void toggleStringInArray(JSONArray arr, String value) {
        JSONArray next = new JSONArray();
        boolean removed = false;
        for (int i = 0; i < arr.length(); i++) {
            String old = arr.optString(i);
            if (value.equals(old)) {
                removed = true;
            } else if (old.length() > 0) {
                next.put(old);
            }
        }
        if (!removed && value.length() > 0) {
            next.put(value);
        }
        while (arr.length() > 0) {
            arr.remove(0);
        }
        for (int i = 0; i < next.length(); i++) {
            arr.put(next.optString(i));
        }
    }

    private String joinStringArray(JSONArray arr, String separator) {
        if (arr == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length(); i++) {
            String value = arr.optString(i);
            if (value.length() == 0) {
                continue;
            }
            if (sb.length() > 0) {
                sb.append(separator);
            }
            sb.append(value);
        }
        return sb.toString();
    }

    private EditText numberInput(String hint) {
        EditText input = apiInput(hint);
        input.setInputType(InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_FLAG_DECIMAL);
        input.setImeOptions(EditorInfo.IME_ACTION_DONE);
        input.setFocusable(true);
        input.setFocusableInTouchMode(true);
        input.setCursorVisible(true);
        if (Build.VERSION.SDK_INT >= 21) {
            input.setShowSoftInputOnFocus(true);
        }
        input.setOnFocusChangeListener(new View.OnFocusChangeListener() {
            @Override
            public void onFocusChange(View v, boolean hasFocus) {
                if (hasFocus) {
                    forceShowKeyboard((EditText) v);
                }
            }
        });
        input.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                forceShowKeyboard((EditText) v);
            }
        });
        input.setOnTouchListener(new View.OnTouchListener() {
            @Override
            public boolean onTouch(View v, MotionEvent event) {
                if (event.getActionMasked() == MotionEvent.ACTION_UP) {
                    forceShowKeyboard((EditText) v);
                }
                return false;
            }
        });
        return input;
    }

