    private boolean stickerGalleryLoadIsCurrent(int generation, LinearLayout target) {
        return generation == stickerGalleryLoadGeneration && inStickerGalleryPage
                && target != null && target == stickerGalleryList && target.getParent() != null;
    }

    private void appendStickerGalleryGroup(final LinearLayout page, final List<StickerGroup> groups,
                                           final int groupIndex, final int generation) {
        if (!stickerGalleryLoadIsCurrent(generation, page)) {
            return;
        }
        if (groupIndex >= groups.size()) {
            page.addView(space(dp(120)));
            return;
        }
        StickerGroup group = groups.get(groupIndex);
        TextView groupLabel = label(group.label, 13,
                nightDecoration() ? Color.rgb(154, 158, 166) : Color.rgb(132, 136, 144), false);
        groupLabel.setPadding(0, dp(18), 0, dp(8));
        page.addView(groupLabel);

        int columns = stickerColumns();
        int gap = dp(8);
        int side = Math.max(dp(42), (getResources().getDisplayMetrics().widthPixels
                - dp(56) - gap * (columns - 1)) / columns);
        WrapFlowLayout grid = new WrapFlowLayout(this);
        grid.setClipChildren(false);
        grid.setClipToPadding(false);
        grid.setItemGap(gap);
        grid.setLineGap(gap);
        LinearLayout.LayoutParams gridLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        gridLp.bottomMargin = dp(8);
        page.addView(grid, gridLp);
        appendStickerGalleryItems(page, groups, groupIndex, grid, side, 0, generation);
    }

    private void appendStickerGalleryItems(final LinearLayout page, final List<StickerGroup> groups,
                                            final int groupIndex, final WrapFlowLayout grid,
                                            final int side, final int start, final int generation) {
        if (!stickerGalleryLoadIsCurrent(generation, page)) {
            return;
        }
        List<StickerEntry> items = groups.get(groupIndex).items;
        int end = Math.min(items.size(), start + 12);
        for (int i = start; i < end; i++) {
            View item = stickerGalleryThumb(items.get(i), side);
            grid.addView(item, new ViewGroup.MarginLayoutParams(side, side));
        }
        final int next = end;
        page.post(new Runnable() {
            @Override
            public void run() {
                if (next < groups.get(groupIndex).items.size()) {
                    appendStickerGalleryItems(page, groups, groupIndex, grid, side, next, generation);
                } else {
                    appendStickerGalleryGroup(page, groups, groupIndex + 1, generation);
                }
            }
        });
    }

    private View stickerGalleryThumb(final StickerEntry entry, int size) {
        if (entry.stackCount > 1 && entry.stackFiles != null && entry.stackFiles.size() > 1) {
            View stack = mediaStackView(entry.date, entry.mealKey, new ArrayList<String>(entry.stackFiles),
                    "stickers", "贴纸", true, size);
            installStandaloneMediaLongPress(stack);
            return stack;
        }
        FrameLayout frame = new FrameLayout(this);
        frame.setClickable(true);
        frame.setClipChildren(false);
        frame.setClipToPadding(false);
        frame.setPadding(dp(1), dp(1), dp(1), dp(1));
        RoundedImageView image = new RoundedImageView(this);
        image.setRadius(stickerImageRadius(size));
        image.setScaleType(ImageView.ScaleType.FIT_CENTER);
        image.setBackground(stickerFrameBackground());
        int pad = stickerFramePadding();
        image.setPadding(pad, pad, pad, pad);
        loadMediaThumbnail(image, entry.fileName, size);
        frame.addView(image, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        if (entry.stackCount > 1) {
            TextView badge = label("×" + entry.stackCount, 12, Color.WHITE, true);
            badge.setGravity(Gravity.CENTER);
            badge.setBackground(round(adjustAlpha(blendColor(accent, Color.WHITE, 0.18f), 184),
                    dp(10), Color.argb(118, 255, 255, 255), dp(1)));
            FrameLayout.LayoutParams badgeLp = new FrameLayout.LayoutParams(dp(30), dp(20));
            badgeLp.gravity = Gravity.RIGHT | Gravity.BOTTOM;
            badgeLp.rightMargin = dp(1);
            badgeLp.bottomMargin = dp(1);
            frame.addView(badge, badgeLp);
        }
        attachPressAnimation(frame);
        frame.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                showPhotoViewer(entry.date, entry.mealKey, entry.fileName);
            }
        });
        return frame;
    }
    private List<StickerEntry> collectStickerEntries(JSONObject sourceDays, boolean includePhotos,
                                                     boolean mergeStacks) {
        List<StickerEntry> result = new ArrayList<StickerEntry>();
        List<String> dates = new ArrayList<String>();
        JSONArray names = sourceDays.names();
        if (names != null) {
            for (int i = 0; i < names.length(); i++) {
                String date = names.optString(i);
                if (date.length() > 0) {
                    dates.add(date);
                }
            }
        }
        Collections.sort(dates, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return b.compareTo(a);
            }
        });
        File filesRoot = getFilesDir();
        for (String date : dates) {
            JSONObject day = sourceDays.optJSONObject(date);
            if (day == null) {
                continue;
            }
            for (int mealIndex = 0; mealIndex < AVAILABLE_MEAL_KEYS.length; mealIndex++) {
                String mealKey = AVAILABLE_MEAL_KEYS[mealIndex];
                String mealTitle = AVAILABLE_MEAL_TITLES[mealIndex];
                JSONObject mealObj = day.optJSONObject(mealKey);
                if (mealObj == null) {
                    continue;
                }
                JSONArray stickers = mealObj.optJSONArray("stickers");
                if (stickers != null) {
                    Set<String> skipStacked = new HashSet<String>();
                    for (int i = 0; i < stickers.length(); i++) {
                        String fileName = stickers.optString(i);
                        if (fileName.length() == 0 || skipStacked.contains(fileName)
                                || !new File(filesRoot, fileName).isFile()) {
                            continue;
                        }
                        List<String> group = mergeStacks
                                ? mediaStackGroup(mealObj, "stickers", stickers, fileName)
                                : new ArrayList<String>();
                        if (group.isEmpty()) {
                            group.add(fileName);
                        }
                        List<String> existingGroup = new ArrayList<String>();
                        for (String grouped : group) {
                            if (new File(filesRoot, grouped).isFile()) {
                                existingGroup.add(grouped);
                            }
                        }
                        group = existingGroup;
                        if (group.isEmpty()) {
                            continue;
                        }
                        String displayName = group.get(group.size() - 1);
                        skipStacked.addAll(group);
                        StickerEntry se = new StickerEntry(date, mealKey, mealTitle, displayName, group.size());
                        se.stackFiles = new ArrayList<String>(group);
                        result.add(se);
                    }
                }
                if (includePhotos) {
                    JSONArray photos = mealObj.optJSONArray("photos");
                    if (photos != null) {
                        for (int i = 0; i < photos.length(); i++) {
                            String fileName = photos.optString(i);
                            if (fileName.length() > 0 && new File(filesRoot, fileName).isFile()) {
                                result.add(new StickerEntry(date, mealKey, mealTitle, fileName));
                            }
                        }
                    }
                }
            }
        }
        return result;
    }

    private List<StickerGroup> groupStickerEntries(List<StickerEntry> entries, String mode) {
        List<StickerGroup> groups = new ArrayList<StickerGroup>();
        for (StickerEntry entry : entries) {
            String key = stickerGroupKey(entry.date, mode);
            String label = stickerGroupLabel(entry.date, mode);
            StickerGroup group = null;
            for (StickerGroup existing : groups) {
                if (existing.key.equals(key)) {
                    group = existing;
                    break;
                }
            }
            if (group == null) {
                group = new StickerGroup(key, label);
                groups.add(group);
            }
            group.items.add(entry);
        }
        return groups;
    }

    private List<String> mediaStackGroup(JSONObject meal, String arrayKey, JSONArray arr, String fileName) {
        List<String> group = new ArrayList<String>();
        if (meal == null || arr == null || fileName == null || fileName.length() == 0) {
            return group;
        }
        List<String> ordered = new ArrayList<String>();
        for (int i = 0; i < arr.length(); i++) {
            String name = arr.optString(i);
            if (name.length() > 0) {
                ordered.add(name);
            }
        }
        if (!ordered.contains(fileName)) {
            return group;
        }
        JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
        if (stacks == null || stacks.length() == 0) {
            group.add(fileName);
            return group;
        }
        group.add(fileName);
        boolean changed = true;
        while (changed) {
            changed = false;
            for (String candidate : ordered) {
                if (group.contains(candidate)) {
                    continue;
                }
                String target = stacks.optString(candidate, "");
                if (group.contains(target)) {
                    group.add(candidate);
                    changed = true;
                }
            }
        }
        Collections.sort(group, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return ordered.indexOf(a) - ordered.indexOf(b);
            }
        });
        return group;
    }

    private String stickerGroupKey(String date, String mode) {
        Calendar cal = calendarFromKey(date);
        if ("month".equals(mode)) {
            return String.format(Locale.CHINA, "%04d-%02d", cal.get(Calendar.YEAR), cal.get(Calendar.MONTH) + 1);
        }
        if ("week".equals(mode)) {
            cal.setFirstDayOfWeek(Calendar.MONDAY);
            return String.format(Locale.CHINA, "%04d-W%02d", cal.get(Calendar.YEAR), cal.get(Calendar.WEEK_OF_YEAR));
        }
        return date;
    }

    private String stickerGroupLabel(String date, String mode) {
        Calendar cal = calendarFromKey(date);
        boolean showYear = cal.get(Calendar.YEAR) != Calendar.getInstance().get(Calendar.YEAR);
        if ("month".equals(mode)) {
            return showYear
                    ? String.format(Locale.CHINA, "%04d年%d月", cal.get(Calendar.YEAR), cal.get(Calendar.MONTH) + 1)
                    : String.format(Locale.CHINA, "%d月", cal.get(Calendar.MONTH) + 1);
        }
        if ("week".equals(mode)) {
            cal.setFirstDayOfWeek(Calendar.MONDAY);
            return showYear
                    ? String.format(Locale.CHINA, "%04d年%d月第%d周", cal.get(Calendar.YEAR),
                    cal.get(Calendar.MONTH) + 1, cal.get(Calendar.WEEK_OF_MONTH))
                    : String.format(Locale.CHINA, "%d月第%d周", cal.get(Calendar.MONTH) + 1,
                    cal.get(Calendar.WEEK_OF_MONTH));
        }
        String[] weekdays = {"周日", "周一", "周二", "周三", "周四", "周五", "周六"};
        String base = String.format(Locale.CHINA, "%d月%d日 %s",
                cal.get(Calendar.MONTH) + 1, cal.get(Calendar.DAY_OF_MONTH),
                weekdays[cal.get(Calendar.DAY_OF_WEEK) - 1]);
        return showYear ? String.format(Locale.CHINA, "%04d年%s", cal.get(Calendar.YEAR), base) : base;
    }

