            skippedMark.setPadding(dp(8), 0, 0, 0);
            LinearLayout.LayoutParams markLp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
