    private void setSpecialMealMood(String date, String mealKey, String emoji, String mood) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        try {
            meal.put("emoji", emoji);
            meal.put("snackMood", mood);
            meal.put("moodTime", nowTime());
            meal.put("skipped", false);
            saveDays();
        } catch (JSONException ignored) {
        }
        showGlassToast("happy".equals(mood) ? mealTitle(mealKey) + "开心一下" : mealTitle(mealKey) + "有点小负担", Toast.LENGTH_SHORT);
        renderCurrent();
    }

    private void focusFirstEmptyMeal() {
        String date = homeDate();
        JSONObject day = ensureDay(date);
        List<MealOption> meals = visibleMealsForDate(date);
        for (int i = 0; i < meals.size(); i++) {
            MealOption option = meals.get(i);
            JSONObject meal = optObj(day, option.key);
            JSONArray photos = meal.optJSONArray("photos");
            if (meal.optString("text", "").trim().length() == 0
                    && (photos == null || photos.length() == 0)
                    && !meal.optBoolean("skipped", false)) {
                showGlassToast("去写" + option.title + "吧", Toast.LENGTH_SHORT);
                return;
            }
        }
        showGlassToast("今天的饭饭已经很完整啦", Toast.LENGTH_SHORT);
    }

    private void chooseMealForPhoto() {
        final String date = homeDate();
        final List<MealOption> meals = visibleMealsForDate(date);
        if (meals.isEmpty()) {
            showGlassToast("还没有可记录的餐别", Toast.LENGTH_SHORT);
            return;
        }
        String[] names = new String[meals.size()];
        for (int i = 0; i < meals.size(); i++) {
            names[i] = "给" + meals.get(i).title + "添加图片/贴纸";
        }
        showChoiceDialog("添加图片/贴纸", names, 0, new ChoiceHandler() {
            @Override
            public void onChoice(int which) {
                if (which >= 0 && which < meals.size()) {
                    chooseMealPhotoSource(date, meals.get(which).key);
                }
            }
        });
    }

    private void renderBooks() {
        FrameLayout host = new FrameLayout(this);
        disableForceDark(host);
        content.addView(host, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        ScrollView scroll = pageScroll();
        LinearLayout page = basePage();
        scroll.addView(page);
        host.addView(scroll, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        LinearLayout top = row(Gravity.CENTER_VERTICAL);
        TextView title = label("足迹", 34, Color.rgb(28, 28, 30), true);
        title.setClickable(true);
        attachPressAnimation(title);
        title.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (footprintCalendarMerged() && !calendarHidden()) {
                    showFootprintsCalendar(true);
                }
            }
        });
        top.addView(title, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        top.addView(new Space(this), new LinearLayout.LayoutParams(0, 1, 1));
        installStickyHeader(host, scroll, page, top);

        TextView subtitle = label("每天都会变成一本小本子，打开就能看见那天的三餐足迹。", 14,
                Color.rgb(116, 122, 130), false);
        subtitle.setPadding(0, dp(8), 0, dp(20));
        page.addView(subtitle);

        List<String> dates = recordedDates();
        if (dates.isEmpty()) {
            page.addView(emptyState("还没有吃饭本子", "今天写一餐，第一个本子就会出现。", "😀"));
            page.addView(space(dp(120)));
            animateIn(page);
            return;
        }

        if (footprintExpanded()) {
            addBookGrid(page, dates);
            page.addView(space(dp(120)));
            animateIn(page);
            return;
        }

        HorizontalScrollView rowScroll = new BookScrollView(this);
        rowScroll.setHorizontalScrollBarEnabled(false);
        rowScroll.setClipToPadding(false);
        rowScroll.setOverScrollMode(View.OVER_SCROLL_NEVER);
        rowScroll.setPadding(dp(2), 0, dp(12), 0);
        LinearLayout books = new LinearLayout(this);
        books.setOrientation(LinearLayout.HORIZONTAL);
        books.setPadding(0, 0, 0, 0);
        rowScroll.addView(books);
        page.addView(rowScroll);

        int[] colors = {
                accent,
                Color.rgb(166, 39, 184),
                Color.rgb(255, 99, 64),
                Color.rgb(255, 234, 44),
                Color.rgb(91, 166, 229)
        };

        for (int i = 0; i < dates.size(); i++) {
            final String date = dates.get(i);
            View book = bookCard(date, colors[i % colors.length]);
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(dp(132), ViewGroup.LayoutParams.WRAP_CONTENT);
            lp.rightMargin = dp(14);
            books.addView(book, lp);
        }
        setupBookCarousel(rowScroll, books);

        TextView recent = label("最近足迹", 22, Color.rgb(40, 40, 40), true);
        recent.setPadding(0, dp(26), 0, dp(12));
        page.addView(recent);
        for (int i = 0; i < Math.min(8, dates.size()); i++) {
            final String date = dates.get(i);
            page.addView(recordRow(date));
        }
        page.addView(space(dp(120)));
    }

    private void addBookGrid(LinearLayout page, List<String> dates) {
        addBookGrid(page, dates, false);
    }

    private void addBookGrid(LinearLayout page, List<String> dates, boolean fromFavorites) {
        int columns = footprintColumns();
        int gapDp = footprintGap();
        int gap = dp(gapDp);
        int available = getResources().getDisplayMetrics().widthPixels - dp(spaceByLayout(44, 40, 36));
        int side = Math.max(dp(48), (available - gap * (columns - 1)) / columns);
        int[] colors = {
                accent,
                Color.rgb(166, 39, 184),
                Color.rgb(255, 99, 64),
                Color.rgb(255, 234, 44),
                Color.rgb(91, 166, 229)
        };
        LinearLayout rowBox = null;
        String currentYear = "";
        String currentMonth = "";
        int sectionIndex = 0;
        for (int i = 0; i < dates.size(); i++) {
            String date = dates.get(i);
            if (footprintDateSectionsEnabled()) {
                Calendar calendar = calendarFromKey(date);
                String year = String.valueOf(calendar.get(Calendar.YEAR));
                String month = String.valueOf(calendar.get(Calendar.MONTH) + 1);
                if (!year.equals(currentYear)) {
                    boolean crossedYear = currentYear.length() > 0;
                    currentYear = year;
                    currentMonth = "";
                    if (crossedYear) {
                        TextView yearTitle = label(year + "年", 19, Color.rgb(142, 146, 154), false);
                        yearTitle.setPadding(dp(2), dp(20), 0, dp(7));
                        page.addView(yearTitle);
                    }
                }
                if (!month.equals(currentMonth)) {
                    currentMonth = month;
                    TextView monthTitle = label(month + "月", 17, accent, true);
                    monthTitle.setPadding(dp(3), dp(4), 0, dp(10));
                    page.addView(monthTitle);
                    sectionIndex = 0;
                    rowBox = null;
                }
            }
            if (sectionIndex % columns == 0) {
                rowBox = row(Gravity.TOP);
                LinearLayout.LayoutParams rowLp = new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
                rowLp.bottomMargin = dp(gapDp + spaceByLayout(12, 8, 5));
                page.addView(rowBox, rowLp);
            }
            View book = bookGridCard(date, colors[i % colors.length], side, columns, fromFavorites);
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(side, ViewGroup.LayoutParams.WRAP_CONTENT);
            if (sectionIndex % columns < columns - 1) {
                lp.rightMargin = gap;
            }
            rowBox.addView(book, lp);
            sectionIndex++;
        }
    }

    private void setupBookCarousel(final HorizontalScrollView rowScroll, final LinearLayout books) {
        attachBookEdgeElastic(rowScroll, books);
        final Runnable depth = new Runnable() {
            @Override
            public void run() {
                updateBookCarouselDepth(rowScroll, books);
            }
        };
        rowScroll.getViewTreeObserver().addOnGlobalLayoutListener(new android.view.ViewTreeObserver.OnGlobalLayoutListener() {
            @Override
            public void onGlobalLayout() {
                rowScroll.getViewTreeObserver().removeOnGlobalLayoutListener(this);
                depth.run();
            }
        });
        if (Build.VERSION.SDK_INT >= 23) {
            rowScroll.setOnScrollChangeListener(new View.OnScrollChangeListener() {
                @Override
                public void onScrollChange(View v, int scrollX, int scrollY, int oldScrollX, int oldScrollY) {
                    depth.run();
                }
            });
        }
        rowScroll.postDelayed(depth, 260);
    }

    private void showFootprintsCalendar(final boolean calendar) {
        if (calendar && calendarHidden()) {
            return;
        }
        if (!footprintCalendarMerged() && currentTab == 1 && calendar) {
            return;
        }
        final int target = calendar ? 2 : 1;
        if (currentTab == target) {
            return;
        }
        currentTab = target;
        playTabFeedback();
        updateNav(true);
        updateFab();
        smoothContentSwap(new Runnable() {
            @Override
            public void run() {
                renderCurrent();
            }
        }, 0f);
    }

    private void attachBookEdgeElastic(final HorizontalScrollView rowScroll, final LinearLayout books) {
        if (rowScroll instanceof BookScrollView) {
            ((BookScrollView) rowScroll).setElasticTarget(books);
            return;
        }
        final float[] downX = new float[1];
        final float[] lastX = new float[1];
        final float[] pullX = new float[1];
        rowScroll.setOnTouchListener(new View.OnTouchListener() {
            @Override
            public boolean onTouch(View v, MotionEvent event) {
                if (event.getAction() == MotionEvent.ACTION_DOWN) {
                    downX[0] = event.getX();
                    lastX[0] = event.getX();
                    pullX[0] = books.getTranslationX();
                    books.animate().cancel();
                } else if (event.getAction() == MotionEvent.ACTION_MOVE) {
                    float x = event.getX();
                    float delta = x - lastX[0];
                    float totalDrag = x - downX[0];
                    lastX[0] = x;
                    int maxScroll = Math.max(0, books.getWidth()
                            + rowScroll.getPaddingLeft() + rowScroll.getPaddingRight()
                            - rowScroll.getWidth());
                    boolean pullingLeftEdge = rowScroll.getScrollX() <= dp(1) && totalDrag > 0 && delta > 0;
                    boolean pullingRightEdge = rowScroll.getScrollX() >= maxScroll - dp(1) && totalDrag < 0 && delta < 0;
                    if (pullingLeftEdge || pullingRightEdge) {
                        pullX[0] += delta * 0.34f;
                        float limit = dp(38);
                        if (pullX[0] > limit) {
                            pullX[0] = limit + (pullX[0] - limit) * 0.18f;
                        } else if (pullX[0] < -limit) {
                            pullX[0] = -limit + (pullX[0] + limit) * 0.18f;
                        }
                        books.setTranslationX(Math.max(-dp(46), Math.min(dp(46), pullX[0])));
                    } else if (Math.abs(books.getTranslationX()) > 0.1f && rowScroll.getScrollX() > dp(1)
                            && rowScroll.getScrollX() < maxScroll - dp(1)) {
                        pullX[0] = 0f;
                        books.setTranslationX(0f);
                    }
                } else if (event.getAction() == MotionEvent.ACTION_UP
                        || event.getAction() == MotionEvent.ACTION_CANCEL) {
                    pullX[0] = 0f;
                    books.animate()
                            .translationX(0f)
                            .setDuration(300)
                            .setInterpolator(new android.view.animation.DecelerateInterpolator(1.85f))
                            .start();
                }
                return false;
            }
        });
    }

    private void updateBookCarouselDepth(HorizontalScrollView rowScroll, LinearLayout books) {
        float center = rowScroll.getScrollX() + rowScroll.getWidth() * 0.48f;
        float range = Math.max(dp(150), rowScroll.getWidth() * 0.48f);
        for (int i = 0; i < books.getChildCount(); i++) {
            View child = books.getChildAt(i);
            float childCenter = child.getLeft() + child.getWidth() / 2f;
            float distance = Math.min(1f, Math.abs(childCenter - center) / range);
            float focus = 1f - distance;
            child.setScaleX(0.94f + 0.06f * focus);
            child.setScaleY(0.94f + 0.06f * focus);
            child.setAlpha(0.9f + 0.1f * focus);
            child.setTranslationY(dp(5) * distance);
        }
    }

    private void snapBookCarousel(final HorizontalScrollView rowScroll, LinearLayout books) {
        if (books.getChildCount() == 0) {
            return;
        }
        float center = rowScroll.getScrollX() + rowScroll.getWidth() * 0.46f;
        int nearest = 0;
        float nearestDistance = Float.MAX_VALUE;
        for (int i = 0; i < books.getChildCount(); i++) {
            View child = books.getChildAt(i);
            float childCenter = child.getLeft() + child.getWidth() / 2f;
            float distance = Math.abs(childCenter - center);
            if (distance < nearestDistance) {
                nearestDistance = distance;
                nearest = i;
            }
        }
        View target = books.getChildAt(nearest);
        int scrollX = Math.max(0, (int) (target.getLeft() + target.getWidth() / 2f - rowScroll.getWidth() * 0.46f));
        rowScroll.smoothScrollTo(scrollX, 0);
    }

