    private void addBookCalorieBadge(FrameLayout cover, String date, boolean compactBadge) {
        if ((!footprintShowCaloriesEnabled() && !footprintShowSpendingEnabled()) || cover == null) {
            return;
        }
        JSONObject day = days == null ? null : days.optJSONObject(date);
        int calories = dayTotalCalories(day);
        int costCents = dayTotalCostCents(day);
        StringBuilder text = new StringBuilder();
        if (footprintShowCaloriesEnabled()) {
            text.append(calories > 0 ? calories + " kcal" : "-- kcal");
        }
        if (footprintShowSpendingEnabled()) {
            if (text.length() > 0) {
                text.append("\n");
            }
            text.append(costCents > 0 ? "¥" + formatCostCents(costCents) : "¥--");
        }
        TextView badge = label(text.toString(), compactBadge ? 9 : 11,
                themedTextColor(Color.rgb(72, 68, 64)), true);
        badge.setGravity(Gravity.CENTER);
        badge.setLineSpacing(0f, 0.94f);
        badge.setPadding(dp(compactBadge ? 5 : 8), 0, dp(compactBadge ? 5 : 8), 0);
        badge.setBackground(round(nightDecoration() ? Color.argb(144, 36, 38, 43)
                        : Color.argb(154, 255, 255, 255), dp(12),
                nightDecoration() ? Color.argb(52, 255, 255, 255) : Color.argb(72, 255, 255, 255), dp(1)));
        badge.setElevation(dp(3));
        boolean twoLines = footprintShowCaloriesEnabled() && footprintShowSpendingEnabled();
        FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT,
                dp(twoLines ? (compactBadge ? 34 : 40) : (compactBadge ? 22 : 26)), Gravity.CENTER);
        cover.addView(badge, lp);
    }

    private int dayTotalCalories(JSONObject day) {
        if (day == null) {
            return 0;
        }
        if (day.optBoolean("manualCaloriesOverride", false)) {
            int total = day.optInt("manualCaloriesTotal", 0);
            if (total > 0) {
                return total;
            }
            for (MealOption option : allMealOptions()) {
                JSONObject meal = day.optJSONObject(option.key);
                if (meal != null && !meal.optBoolean("skipped", false)) {
                    total += Math.max(0, meal.optInt("manualCalories", 0));
                }
            }
            return total;
        }
        return Math.max(0, day.optInt("calories", 0));
    }

    private int dayTotalCostCents(JSONObject day) {
        if (day == null) {
            return 0;
        }
        int total = 0;
        for (MealOption option : allMealOptions()) {
            JSONObject meal = day.optJSONObject(option.key);
            if (meal != null && !meal.optBoolean("skipped", false)) {
                total += Math.max(0, meal.optInt("mealCostCents", 0));
            }
        }
        return total;
    }

    private String formatCostCents(int cents) {
        if (cents <= 0) {
            return "0";
        }
        if (cents % 100 == 0) {
            return String.valueOf(cents / 100);
        }
        return String.format(Locale.CHINA, "%.2f", cents / 100f);
    }

    private int parseCostCents(String value) {
        try {
            String normalized = value == null ? "" : value.trim().replace(',', '.');
            if (normalized.length() == 0) {
                return 0;
            }
            return Math.max(0, Math.min(99999900,
                    Math.round(Float.parseFloat(normalized) * 100f)));
        } catch (Exception ignored) {
            return 0;
        }
    }

    private void showManualMealStatsDialog(final String date) {
        final JSONObject day = ensureDay(date);
        final List<MealOption> meals = new ArrayList<MealOption>();
        for (MealOption option : visibleMealsForDate(date)) {
            JSONObject meal = optObj(day, option.key);
            if (!meal.optBoolean("skipped", false)) {
                meals.add(option);
            }
        }
        if (meals.isEmpty()) {
            showSimpleInfoDialog("没有可填写的餐次", "当天的餐次都标记为没有吃饭，暂时不需要填写热量和消费。");
            return;
        }

        final AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(22), dp(20), dp(22), dp(18));
        box.setBackground(round(dialogSurfaceColor(), dp(26), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        LinearLayout titleRow = row(Gravity.CENTER_VERTICAL);
        titleRow.addView(label("记录热量与消费", 22, Color.rgb(28, 28, 30), true),
                new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        final FavoriteStarView favorite = new FavoriteStarView(this);
        favorite.setFavorite(day.optBoolean("favorite", false));
        favorite.setContentDescription(favorite.isFavorite() ? "取消收藏这一天" : "收藏这一天");
        favorite.setClickable(true);
        attachPressAnimation(favorite);
        favorite.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                boolean next = !favorite.isFavorite();
                try {
                    day.put("favorite", next);
                    saveDays();
                    favorite.setFavorite(next);
                    favorite.animate().cancel();
                    favorite.setScaleX(0.88f);
                    favorite.setScaleY(0.88f);
                    favorite.animate()
                            .scaleX(1f)
                            .scaleY(1f)
                            .setDuration(220)
                            .setInterpolator(new android.view.animation.OvershootInterpolator(1.7f))
                            .start();
                    favorite.setContentDescription(next ? "取消收藏这一天" : "收藏这一天");
                    showGlassToast(next ? "已收藏这一天" : "已取消收藏", Toast.LENGTH_SHORT);
                } catch (JSONException ignored) {
                }
            }
        });
        titleRow.addView(favorite, new LinearLayout.LayoutParams(dp(44), dp(44)));
        box.addView(titleRow);
        TextView subtitle = label(displayDate(date) + " · 手动热量会替代当天的 AI 估算", 14,
                Color.rgb(104, 108, 116), false);
        subtitle.setPadding(0, dp(7), 0, dp(10));
        box.addView(subtitle);

        final List<EditText> calorieInputs = new ArrayList<EditText>();
        final List<EditText> costInputs = new ArrayList<EditText>();
        for (MealOption option : meals) {
            JSONObject meal = optObj(day, option.key);
            TextView mealTitle = label(option.title, 16, Color.rgb(48, 50, 54), true);
            mealTitle.setPadding(dp(2), dp(8), 0, dp(2));
            box.addView(mealTitle);

            LinearLayout inputRow = row(Gravity.CENTER_VERTICAL);
            final EditText calorie = numberInput("热量 kcal");
            calorie.setInputType(InputType.TYPE_CLASS_NUMBER);
            setNumberText(calorie, meal.optInt("manualCalories", 0));
            calorie.setBackground(round(nightDecoration() ? Color.argb(122, 35, 37, 42)
                            : Color.argb(118, 255, 255, 255), dp(14), adjustAlpha(accent, 52), dp(1)));
            final EditText cost = numberInput("消费 元");
            int storedCost = meal.optInt("mealCostCents", 0);
            cost.setText(storedCost > 0 ? formatCostCents(storedCost) : "");
            cost.setBackground(round(nightDecoration() ? Color.argb(122, 35, 37, 42)
                            : Color.argb(118, 255, 255, 255), dp(14), adjustAlpha(accent, 52), dp(1)));
            calorieInputs.add(calorie);
            costInputs.add(cost);
            LinearLayout.LayoutParams calorieLp = new LinearLayout.LayoutParams(0, dp(46), 1);
            LinearLayout.LayoutParams costLp = new LinearLayout.LayoutParams(0, dp(46), 1);
            costLp.leftMargin = dp(10);
            inputRow.addView(calorie, calorieLp);
            inputRow.addView(cost, costLp);
            box.addView(inputRow, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        }

        LinearLayout actions = row(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        actions.setPadding(0, dp(16), 0, 0);
        TextView cancel = dialogButton("取消", Color.argb(110, 238, 241, 244),
                themedTextColor(Color.rgb(86, 88, 94)));
        TextView save = dialogButton("保存", adjustAlpha(accent, 224), Color.WHITE);
        cancel.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                dialog.dismiss();
            }
        });
        save.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                int totalCalories = 0;
                boolean hasManualCalories = false;
                try {
                    for (int i = 0; i < meals.size(); i++) {
                        JSONObject meal = optObj(day, meals.get(i).key);
                        int calories = Math.max(0, parseIntSafe(calorieInputs.get(i).getText().toString()));
                        int costCents = parseCostCents(costInputs.get(i).getText().toString());
                        if (calories > 0) {
                            meal.put("manualCalories", calories);
                            totalCalories += calories;
                            hasManualCalories = true;
                        } else {
                            meal.remove("manualCalories");
                        }
                        if (costCents > 0) {
                            meal.put("mealCostCents", costCents);
                        } else {
                            meal.remove("mealCostCents");
                        }
                    }
                    if (hasManualCalories) {
                        day.put("manualCaloriesOverride", true);
                        day.put("manualCaloriesTotal", totalCalories);
                        day.remove("calories");
                        day.remove("calorieSignature");
                        day.remove("caloriePending");
                    } else {
                        day.remove("manualCaloriesOverride");
                        day.remove("manualCaloriesTotal");
                    }
                    saveDays();
                    dialog.dismiss();
                    rerenderPreservingScroll(new Runnable() {
                        @Override
                        public void run() {
                            if (inBookDetail && date.equals(bookDetailDate)) {
                                renderBookDetail(date, false);
                            } else {
                                renderCurrent();
                            }
                        }
                    });
                    showGlassToast("热量与消费已保存", Toast.LENGTH_SHORT);
                } catch (JSONException ignored) {
                }
            }
        });
        LinearLayout.LayoutParams cancelLp = new LinearLayout.LayoutParams(dp(78), dp(42));
        cancelLp.rightMargin = dp(10);
        actions.addView(cancel, cancelLp);
        actions.addView(save, new LinearLayout.LayoutParams(dp(78), dp(42)));
        box.addView(actions);

        ScrollView scroll = new ScrollView(this);
        scroll.setFillViewport(false);
        scroll.addView(box, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        showRoundedDialog(dialog, scroll);
        Window window = dialog.getWindow();
        if (window != null && meals.size() > 3) {
            window.setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.88f),
                    (int) (getResources().getDisplayMetrics().heightPixels * 0.76f));
        }
    }

    private int[] bookPalette(String date, int fallback) {
        int[][] palettes = {
                {Color.rgb(93, 193, 122), Color.rgb(67, 174, 112), Color.rgb(255, 244, 143), Color.rgb(92, 225, 186)},
                {Color.rgb(255, 213, 61), Color.rgb(237, 182, 38), Color.rgb(255, 132, 91), Color.rgb(255, 246, 167)},
                {Color.rgb(255, 111, 92), Color.rgb(229, 79, 69), Color.rgb(255, 226, 145), Color.rgb(255, 157, 176)},
                {Color.rgb(83, 166, 225), Color.rgb(62, 137, 209), Color.rgb(190, 239, 255), Color.rgb(116, 221, 213)},
                {Color.rgb(173, 105, 218), Color.rgb(142, 82, 196), Color.rgb(255, 217, 118), Color.rgb(218, 187, 255)},
                {Color.rgb(255, 150, 72), Color.rgb(231, 105, 56), Color.rgb(255, 235, 145), Color.rgb(255, 190, 132)},
                {Color.rgb(80, 205, 176), Color.rgb(54, 172, 156), Color.rgb(252, 255, 167), Color.rgb(151, 236, 213)}
        };
        Calendar cal = calendarFromKey(date);
        int day = cal.get(Calendar.DAY_OF_WEEK);
        int idx = day == Calendar.SUNDAY ? 6 : day - Calendar.MONDAY;
        int[] selected = palettes[Math.max(0, Math.min(palettes.length - 1, idx))];
        if (nightDecoration()) {
            return new int[]{
                    Color.rgb(174, 179, 188),
                    Color.rgb(82, 86, 96),
                    Color.rgb(235, 238, 244),
                    Color.rgb(126, 132, 144)
            };
        }
        return selected.length > 0 ? selected : new int[]{fallback, fallback, Color.WHITE, accentSoft};
    }

