    private View buildBookDetailPage(final String date, boolean animatePage) {
        LinearLayout page = new LinearLayout(this);
        disableForceDark(page);
        page.setOrientation(LinearLayout.VERTICAL);
        page.setClipToPadding(true);
        int horizontal = dp(spaceByLayout(22, 20, 18));
        page.setPadding(horizontal, dp(spaceByLayout(112, 106, 102)), horizontal, dp(18));

        JSONObject day = ensureDay(date);
        addNotebookDetail(page, date, day);
        if (animatePage) {
            animateIn(page);
        }
        return page;
    }

    private String adjacentBookDate(String date, int offset) {
        List<String> dates = recordedDates();
        int index = dates.indexOf(date);
        if (index < 0) {
            return null;
        }
        int nextIndex = index + offset;
        if (nextIndex < 0 || nextIndex >= dates.size()) {
            return null;
        }
        return dates.get(nextIndex);
    }

    private void openAdjacentBookDetail(String date, final int offset) {
        final String nextDate = adjacentBookDate(date, offset);
        if (nextDate == null) {
            showGlassToast("没有相邻本子了", Toast.LENGTH_SHORT);
            return;
        }
        playPageSwipeFeedback();
        if (bookDetailSwipeFrame != null) {
            bookDetailSwipeFrame.slideToDate(nextDate, offset);
            return;
        }
        if (content == null || content.getChildCount() == 0) {
            renderBookDetail(nextDate, false);
            return;
        }
        renderBookDetail(nextDate, false);
    }

    private void addNotebookDetail(LinearLayout page, String date, JSONObject day) {
        FrameLayout paper = new FrameLayout(this);
        disableForceDark(paper);
        paper.setBackground(new NotebookPageDrawable());
        paper.setTag(TAG_BOOK_NOTEBOOK_PAGE);
        paper.setElevation(dp(3));

        ScrollView paperScroll = pageScroll();
        paperScroll.setFillViewport(true);
        paperScroll.setVerticalFadingEdgeEnabled(true);
        paperScroll.setFadingEdgeLength(dp(22));

        LinearLayout notebook = new LinearLayout(this);
        notebook.setOrientation(LinearLayout.VERTICAL);
        notebook.setPadding(dp(28), dp(26), dp(24), dp(30));
        paperScroll.addView(notebook, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        paper.addView(paperScroll, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        LinearLayout.LayoutParams paperLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(spaceByLayout(540, 520, 500)));
        paperLp.topMargin = dp(18);
        page.addView(paper, paperLp);

        TextView dateText = label(displayNotebookDate(date), 23, Color.rgb(96, 80, 63), true);
        styleBookText(dateText, true, 1);
        dateText.setPadding(dp(8), 0, 0, dp(16));
        notebook.addView(dateText);

        if ("split".equals(bookStoryLayout())) {
            TextView count = label(notebookMealCountLine(day), 19, Color.rgb(72, 66, 58), true);
            styleBookText(count, true, 2);
            count.setPadding(dp(8), 0, dp(6), dp(12));
            notebook.addView(count);

            List<String> lines = notebookStoryLines(date, day);
            for (String line : lines) {
                TextView lineView = label(line, 18, Color.rgb(72, 66, 58), false);
                styleBookText(lineView, false, 2);
                lineView.setLineSpacing(dp(5), 1.04f);
                lineView.setPadding(dp(8), 0, dp(6), dp(10));
                notebook.addView(lineView);
            }
        } else {
            TextView story = label(notebookDayStory(date, day), 19, Color.rgb(72, 66, 58), false);
            styleBookText(story, false, 2);
            story.setLineSpacing(dp(8), 1.04f);
            story.setPadding(dp(8), 0, dp(6), dp(18));
            notebook.addView(story);
        }

        TextView times = label(notebookTimeLine(day), 14, Color.rgb(150, 137, 119), false);
        styleBookText(times, false, 0);
        times.setPadding(dp(8), dp(4), dp(6), dp(8));
        notebook.addView(times);

        TextView photoHint = label(notebookPhotoLine(day), 13, Color.rgb(158, 148, 132), false);
        if (photoHint.getText().toString().length() > 0) {
            styleBookText(photoHint, false, 0);
            photoHint.setPadding(dp(8), dp(6), dp(6), 0);
            notebook.addView(photoHint);
        }
        addNotebookStickerBoard(notebook, day);
        TextView calorie = label(calorieLine(day), 12, Color.rgb(166, 154, 138), false);
        if (calorie.getText().toString().length() > 0) {
            styleBookText(calorie, false, 0);
            calorie.setPadding(dp(8), dp(6), dp(6), 0);
            calorie.setClickable(true);
            attachPressAnimation(calorie);
            calorie.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    JSONObject target = ensureDay(date);
                    if (target.optBoolean("manualCaloriesOverride", false)) {
                        showManualMealStatsDialog(date);
                        return;
                    }
                    target.remove("calories");
                    target.remove("calorieSignature");
                    target.remove("caloriePending");
                    saveDays();
                    showGlassToast("正在重新估算热量...", Toast.LENGTH_SHORT);
                    requestCalorieEstimate(date, target, true);
                    renderBookDetail(date, false);
                }
            });
            notebook.addView(calorie);
        }
        requestCalorieEstimateIfNeeded(date, day);
    }

    private View notebookMealRow(String date, JSONObject day, MealOption mealOption, boolean last) {
        JSONObject meal = optObj(day, mealOption.key);
        String text = meal.optString("text", "").trim();
        boolean skipped = meal.optBoolean("skipped", false);
        JSONArray photos = meal.optJSONArray("photos");
        int photoCount = photos == null ? 0 : photos.length();
        if (skipped) {
            text = skippedReminder(date, mealOption.key, mealOption.title);
        } else if (text.length() == 0 && photoCount > 0) {
            text = "留下了 " + photoCount + " 张图片";
        } else if (text.length() == 0) {
            text = "还没有记录";
        }
        String time = displayShortTime(meal.optString("time", ""));
        if (time.length() == 0 && (skipped || text.trim().length() > 0 || photoCount > 0)) {
            time = displayShortTime(meal.optString("skipTime", ""));
        }

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.VERTICAL);
        row.setPadding(dp(10), dp(4), dp(8), last ? dp(0) : dp(18));
        LinearLayout.LayoutParams rowLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        row.setLayoutParams(rowLp);

        LinearLayout top = row(Gravity.CENTER_VERTICAL);
        TextView question = label(mealQuestion(mealOption), 18, Color.rgb(86, 74, 64), true);
        styleBookText(question, true, 1);
        top.addView(question, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        TextView timeView = label(time, 13, Color.rgb(142, 132, 120), false);
        styleBookText(timeView, false, 0);
        top.addView(timeView);
        row.addView(top);

        TextView body = label(text, 17, Color.rgb(76, 72, 70), false);
        styleBookText(body, false, 2);
        body.setPadding(0, dp(6), 0, 0);
        body.setLineSpacing(dp(2), 1.08f);
        row.addView(body);
        if (photoCount > 0) {
            TextView photoHint = label("photo×" + photoCount, 12, Color.rgb(158, 150, 138), false);
            styleBookText(photoHint, false, 0);
            photoHint.setPadding(0, dp(4), 0, 0);
            row.addView(photoHint);
        }
        return row;
    }

    private String notebookMealCountLine(JSONObject day) {
        int eaten = notebookEatenCount(day);
        if (eaten <= 0) {
            return "今天还没有写下吃了什么";
        }
        return "今天吃了" + chineseMealCount(eaten) + "餐";
    }

    private int notebookEatenCount(JSONObject day) {
        int eaten = 0;
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            JSONArray photos = meal.optJSONArray("photos");
            JSONArray stickers = meal.optJSONArray("stickers");
            if (!meal.optBoolean("skipped", false)
                    && (meal.optString("text", "").trim().length() > 0
                    || (photos != null && photos.length() > 0)
                    || (stickers != null && stickers.length() > 0))) {
                eaten++;
            }
        }
        return eaten;
    }

    private List<String> notebookStoryLines(String date, JSONObject day) {
        List<String> lines = new ArrayList<String>();
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            if (meal.optBoolean("skipped", false)) {
                continue;
            }
            String text = meal.optString("text", "").trim();
            JSONArray photos = meal.optJSONArray("photos");
            JSONArray stickers = meal.optJSONArray("stickers");
            int photoCount = photos == null ? 0 : photos.length();
            int stickerCount = stickers == null ? 0 : stickers.length();
            if (text.length() == 0 && photoCount == 0 && stickerCount == 0) {
                continue;
            }
            StringBuilder line = new StringBuilder();
            line.append(mealPeriodName(mealOption.key)).append("吃了");
            if (text.length() > 0) {
                line.append(text);
            } else if (stickerCount > 0) {
                line.append(stickerCount).append("张贴纸");
            } else {
                line.append(photoCount).append("张图片");
            }
            lines.add(line.toString());
        }
        if (lines.isEmpty()) {
            lines.add("等一口好味道落进本子里。");
        }
        return lines;
    }

    private void addNotebookStickerBoard(LinearLayout notebook, JSONObject day) {
        List<NotebookMedia> media = dayNotebookMedia(day);
        if (media.isEmpty()) {
            return;
        }
        TextView title = label("今日记录", 14, Color.rgb(150, 137, 119), false);
        styleBookText(title, false, 0);
        title.setPadding(dp(8), dp(16), dp(6), dp(6));
        notebook.addView(title);

        FrameLayout board = new FrameLayout(this);
        board.setClipChildren(false);
        board.setClipToPadding(false);
        boolean straight = "straight".equals(bookStickerLayout());
        int max = Math.min(media.size(), 12);
        int available = getResources().getDisplayMetrics().widthPixels - dp(156);
        int columns = 4;
        int size = Math.max(dp(52), Math.min(dp(64), (available - dp(6) * (columns - 1)) / columns));
        int columnGap = dp(8);
        int columnStep = size + columnGap;
        int rows = Math.max(1, (max + columns - 1) / columns);
        int boardHeight = dp(18) + rows * (size + dp(straight ? 10 : 14));
        LinearLayout.LayoutParams boardLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, boardHeight);
        notebook.addView(board, boardLp);

        for (int i = 0; i < max; i++) {
            NotebookMedia item = media.get(i);
            File file = new File(getFilesDir(), item.fileName);
            if (!file.exists()) {
                continue;
            }
            ImageView image = new ImageView(this);
            disableForceDark(image);
            image.setScaleType(ImageView.ScaleType.FIT_CENTER);
            image.setBackground(notebookStickerFrameBackground());
            int pad = Math.max(0, stickerFramePadding() - dp(1));
            image.setPadding(pad, pad, pad, pad);
            if (!straight) {
                image.setRotation(new float[]{-9f, 5f, -4f, 8f, -7f, 4f, -3f, 7f}[i % 8]);
            }
            FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(size, size);
            int row = i / columns;
            int column = i % columns;
            lp.leftMargin = dp(8) + column * columnStep;
            lp.topMargin = dp(8) + row * (size + dp(straight ? 10 : 14)) + (straight ? 0 : dp((column % 2) * 5));
            board.addView(image, lp);
            loadMediaThumbnail(image, item.fileName, size);
        }
    }

    private List<NotebookMedia> dayNotebookMedia(JSONObject day) {
        List<NotebookMedia> items = new ArrayList<NotebookMedia>();
        boolean includePhotos = bookPhotoBoardEnabled();
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            if (meal.optBoolean("skipped", false)) {
                continue;
            }
            addNotebookMedia(items, meal.optJSONArray("stickers"), true);
            if (includePhotos) {
                addNotebookMedia(items, meal.optJSONArray("photos"), false);
            }
        }
        return items;
    }

    private void addNotebookMedia(List<NotebookMedia> items, JSONArray array, boolean sticker) {
        if (array == null) {
            return;
        }
        for (int i = 0; i < array.length(); i++) {
            String name = safeBackupFileName(array.optString(i));
            if (name.length() > 0) {
                items.add(new NotebookMedia(name, sticker));
            }
        }
    }

    private List<String> dayStickerNames(JSONObject day) {
        List<String> names = new ArrayList<String>();
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            if (meal.optBoolean("skipped", false)) {
                continue;
            }
            JSONArray stickers = meal.optJSONArray("stickers");
            if (stickers == null) {
                continue;
            }
            for (int i = 0; i < stickers.length(); i++) {
                String name = safeBackupFileName(stickers.optString(i));
                if (name.length() > 0) {
                    names.add(name);
                }
            }
        }
        return names;
    }

    private String notebookDayStory(String date, JSONObject day) {
        List<String> pieces = new ArrayList<String>();
        int eaten = 0;
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            if (meal.optBoolean("skipped", false)) {
                continue;
            }
            String text = meal.optString("text", "").trim();
            JSONArray photos = meal.optJSONArray("photos");
            JSONArray stickers = meal.optJSONArray("stickers");
            int photoCount = photos == null ? 0 : photos.length();
            int stickerCount = stickers == null ? 0 : stickers.length();
            if (text.length() == 0 && photoCount == 0 && stickerCount == 0) {
                continue;
            }
            eaten++;
            String value = text.length() > 0 ? text : (stickerCount > 0 ? "留下了" + stickerCount + "张贴纸" : "留下了" + photoCount + "张图片");
            pieces.add(mealPeriodName(mealOption.key) + "吃了" + value);
        }
        if (pieces.isEmpty()) {
            return "今天还没有写下吃了什么，等一口好味道落进本子里。";
        }
        StringBuilder story = new StringBuilder();
        story.append("今天吃了").append(chineseMealCount(eaten)).append("餐，");
        for (int i = 0; i < pieces.size(); i++) {
            if (i > 0) {
                story.append("，");
            }
            story.append(pieces.get(i));
        }
        story.append("。");
        return story.toString();
    }

    private String chineseMealCount(int count) {
        String[] names = {"零", "一", "二", "三", "四", "五", "六", "七", "八", "九"};
        if (count >= 0 && count < names.length) {
            return names[count];
        }
        return String.valueOf(count);
    }

    private String notebookTimeLine(JSONObject day) {
        List<String> pieces = new ArrayList<String>();
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            if (meal.optBoolean("skipped", false)) {
                continue;
            }
            String time = displayShortTime(meal.optString("time", ""));
            if (time.length() > 0) {
                pieces.add(mealPeriodName(mealOption.key) + " " + time);
            }
        }
        if (pieces.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder("时间：");
        for (int i = 0; i < pieces.size(); i++) {
            if (i > 0) {
                sb.append(" · ");
            }
            sb.append(pieces.get(i));
        }
        return sb.toString();
    }

    private String notebookPhotoLine(JSONObject day) {
        return notebookMediaLine(day);
    }

    private String notebookMediaLine(JSONObject day) {
        List<String> pieces = new ArrayList<String>();
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            if (meal.optBoolean("skipped", false)) {
                continue;
            }
            JSONArray photos = meal.optJSONArray("photos");
            JSONArray stickers = meal.optJSONArray("stickers");
            int photoCount = photos == null ? 0 : photos.length();
            int stickerCount = stickers == null ? 0 : stickers.length();
            if (photoCount > 0 || stickerCount > 0) {
                StringBuilder item = new StringBuilder(mealPeriodName(mealOption.key));
                if (photoCount > 0) {
                    item.append(" photo×").append(photoCount);
                }
                if (stickerCount > 0) {
                    item.append(photoCount > 0 ? " " : " ").append("sticker×").append(stickerCount);
                }
                pieces.add(item.toString());
            }
        }
        if (pieces.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pieces.size(); i++) {
            if (i > 0) {
                sb.append(" · ");
            }
            sb.append(pieces.get(i));
        }
        return sb.toString();
    }

    private String calorieLine(JSONObject day) {
        if (day != null && day.optBoolean("manualCaloriesOverride", false)) {
            int manual = dayTotalCalories(day);
            return manual > 0 ? "今日摄入热量 " + manual + " kcal（手动记录）" : "";
        }
        if (!calorieRecognitionEnabled()) {
            return "";
        }
        int calories = day.optInt("calories", 0);
        if (calories > 0) {
            return "今日摄入热量约 " + calories + " kcal（AI 估算）";
        }
        return apiEnabled() ? "今日摄入热量正在等待 AI 估算..." : "";
    }

    private void requestCalorieEstimateIfNeeded(final String date, final JSONObject day) {
        requestCalorieEstimate(date, day, false);
    }

    private void requestCalorieEstimate(final String date, final JSONObject day, boolean force) {
        if (day != null && day.optBoolean("manualCaloriesOverride", false)) {
            return;
        }
        final String summary = caloriePromptSummary(date, day);
        final String signature = String.valueOf(summary.hashCode());
        if (!calorieRecognitionEnabled() || !apiEnabled() || day.optBoolean("caloriePending", false)) {
            return;
        }
        if (!force && day.optInt("calories", 0) > 0
                && signature.equals(day.optString("calorieSignature", ""))) {
            return;
        }
        if (summary.trim().length() == 0) {
            return;
        }
        try {
            day.put("caloriePending", true);
            saveDays();
        } catch (JSONException ignored) {
        }
        final String endpoint = apiEndpoint();
        final String key = profile.optString("apiKey", "");
        final String model = apiModelName();
        new Thread(new Runnable() {
            @Override
            public void run() {
                String prompt = "请根据下面这一天的饮食记录，粗略估算总摄入热量。只返回一个整数数字，不要单位，不要解释。记录：" + summary;
                String text = callChatApi(endpoint, key, model, prompt);
                final int calories = parseFirstPositiveInt(text);
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        JSONObject target = ensureDay(date);
                        try {
                            target.remove("caloriePending");
                            if (calories > 0) {
                                target.put("calories", calories);
                                target.put("calorieSignature", signature);
                                saveDays();
                                if (inBookDetail && date.equals(bookDetailDate)) {
                                    renderBookDetail(date, false);
                                }
                            } else {
                                saveDays();
                            }
                        } catch (JSONException ignored) {
                        }
                    }
                });
            }
        }).start();
    }

    private String caloriePromptSummary(String date, JSONObject day) {
        StringBuilder sb = new StringBuilder();
        for (MealOption mealOption : visibleMealsForDay(day)) {
            JSONObject meal = optObj(day, mealOption.key);
            String dining = date.length() > 0 ? mealDiningText(date, mealOption.key)
                    : joinStringList(mealDiningMethodsRaw(day, mealOption.key), "、");
            String text = meal.optString("text", "").trim();
            JSONArray photos = meal.optJSONArray("photos");
            JSONArray stickers = meal.optJSONArray("stickers");
            int photoCount = photos == null ? 0 : photos.length();
            int stickerCount = stickers == null ? 0 : stickers.length();
            if (meal.optBoolean("skipped", false)) {
                if (sb.length() > 0) {
                    sb.append("；");
                }
                sb.append(mealOption.title);
                if (dining.length() > 0) {
                    sb.append("（").append(dining).append("）");
                }
                sb.append("：没吃");
                continue;
            }
            if (text.length() == 0 && photoCount == 0 && stickerCount == 0 && dining.length() == 0) {
                continue;
            }
            if (sb.length() > 0) {
                sb.append("；");
            }
            sb.append(mealOption.title);
            if (dining.length() > 0) {
                sb.append("（").append(dining).append("）");
            }
            sb.append("：");
            if (text.length() > 0) {
                sb.append(text);
            } else if (photoCount > 0 || stickerCount > 0) {
                sb.append("有图片或贴纸记录");
            } else {
                sb.append("已标记就餐方式");
            }
            if (photoCount > 0 || stickerCount > 0) {
                sb.append("（有图片").append(photoCount).append("张，贴纸").append(stickerCount).append("张）");
            }
        }
        return sb.toString();
    }

    private int parseFirstPositiveInt(String text) {
        if (text == null) {
            return 0;
        }
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c >= '0' && c <= '9') {
                digits.append(c);
            } else if (digits.length() > 0) {
                break;
            }
        }
        if (digits.length() == 0) {
            return 0;
        }
        try {
            return Math.max(0, Math.min(99999, Integer.parseInt(digits.toString())));
        } catch (Exception e) {
            return 0;
        }
    }

    private String mealPeriodName(String key) {
        if ("breakfast".equals(key)) {
            return "早上";
        }
        if ("lunch".equals(key)) {
            return "中午";
        }
        if ("dinner".equals(key)) {
            return "晚上";
        }
        if ("afternoon_tea".equals(key)) {
            return "下午茶";
        }
        if ("snack".equals(key)) {
            return "夜宵";
        }
        return mealTitle(key);
    }

    private String mealQuestion(MealOption meal) {
        if ("breakfast".equals(meal.key)) {
            return "早餐吃了什么？";
        }
        if ("lunch".equals(meal.key)) {
            return "中午吃了什么？";
        }
        if ("dinner".equals(meal.key)) {
            return "晚上吃了什么？";
        }
        return meal.title + "吃了什么？";
    }

    private String displayShortTime(String time) {
        if (time == null) {
            return "";
        }
        String value = time.trim();
        if (value.length() >= 16 && value.charAt(13) == ':') {
            return value.substring(11, 16);
        }
        int space = value.lastIndexOf(' ');
        if (space >= 0 && space + 1 < value.length()) {
            return value.substring(space + 1);
        }
        return value;
    }

    private Typeface bookDetailTypeface(boolean bold) {
        String style = bookFontStyle();
        int weight = bold ? Typeface.BOLD : Typeface.NORMAL;
        Typeface typeface = isDownloadableBookFont(style) ? downloadedBookTypeface(style) : null;
        if (typeface != null) {
            return Typeface.create(typeface, weight);
        }
        if (isDownloadableBookFont(style)) {
            return Typeface.create(Typeface.DEFAULT, weight);
        }
        if ("slim".equals(style)) {
            return Typeface.create("sans-serif-condensed", weight);
        }
        if (!"default".equals(style)) {
            return Typeface.create("casual", weight);
        }
        return Typeface.create(Typeface.DEFAULT, weight);
    }

    private boolean isDownloadableBookFont(String style) {
        return "xiaolai".equals(style) || "yozai".equals(style) || "wenkai".equals(style)
                || "marker".equals(style) || "zcool".equals(style);
    }

    private String downloadableBookFontFileName(String style) {
        if ("xiaolai".equals(style)) {
            return "Xiaolai-Regular.ttf";
        }
        if ("yozai".equals(style)) {
            return "Yozai-Regular.ttf";
        }
        if ("wenkai".equals(style)) {
            return "LXGWWenKaiLite-Regular.ttf";
        }
        if ("marker".equals(style)) {
            return "LXGWMarkerGothic-Regular.ttf";
        }
        if ("zcool".equals(style)) {
            return "ZCOOLKuaiLe-Regular.ttf";
        }
        return "";
    }

    private File downloadedBookFontFile(String style) {
        String name = downloadableBookFontFileName(style);
        if (name.length() == 0) {
            return null;
        }
        return new File(new File(getFilesDir(), "downloaded_fonts"), name);
    }

    private Typeface downloadedBookTypeface(String style) {
        if (downloadedTypefaceCache.containsKey(style)) {
            return downloadedTypefaceCache.get(style);
        }
        File file = downloadedBookFontFile(style);
        if (file == null || !file.isFile() || file.length() < 65536L) {
            return null;
        }
        try {
            Typeface typeface = Typeface.createFromFile(file);
            downloadedTypefaceCache.put(style, typeface);
            return typeface;
        } catch (RuntimeException ignored) {
            file.delete();
            return null;
        }
    }

    private boolean downloadedBookFontReady(String style) {
        return !isDownloadableBookFont(style) || downloadedBookTypeface(style) != null;
    }

    private void cleanupRetiredDownloadedFonts() {
        File directory = new File(getFilesDir(), "downloaded_fonts");
        String[] retiredNames = {"MaShanZheng-Regular.ttf", "ZCOOLQingKeHuangYou-Regular.ttf"};
        for (String name : retiredNames) {
            File retired = new File(directory, name);
            if (retired.isFile()) {
                retired.delete();
            }
        }
        String selected = profile == null ? "" : profile.optString("bookFont", "");
        if ("mashan".equals(selected) || "qingke".equals(selected)) {
            try {
                profile.put("bookFont", "default");
                saveProfile();
            } catch (JSONException ignored) {
            }
        }
        downloadedTypefaceCache.remove("mashan");
        downloadedTypefaceCache.remove("qingke");
    }

    private void downloadBookFont(final String style, final String displayName, final Runnable onSuccess) {
        final String fileName = downloadableBookFontFileName(style);
        if (fileName.length() == 0) {
            return;
        }

        final AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(22), dp(22), dp(22), dp(20));
        box.setBackground(round(dialogSurfaceColor(), dp(26), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        TextView title = label("下载 " + displayName, 22, Color.rgb(28, 28, 30), true);
        final TextView message = label("正在连接字体库，请稍等…", 14, Color.rgb(112, 116, 124), false);
        message.setPadding(0, dp(8), 0, dp(14));
        final ProgressBar progress = new ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
        progress.setMax(100);
        progress.setProgress(0);
        progress.setProgressTintList(ColorStateList.valueOf(accent));
        progress.setProgressBackgroundTintList(ColorStateList.valueOf(
                nightDecoration() ? Color.rgb(62, 64, 70) : Color.rgb(226, 230, 236)));
        final TextView percent = label("0%", 13, accent, true);
        percent.setGravity(Gravity.RIGHT);
        percent.setPadding(0, dp(8), 0, 0);
        box.addView(title);
        box.addView(message);
        box.addView(progress, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(18)));
        box.addView(percent);
        dialog.setCancelable(false);
        showRoundedDialog(dialog, box);

        new Thread(new Runnable() {
            @Override
            public void run() {
                HttpURLConnection connection = null;
                File temporary = null;
                try {
                    String rawUrl = fetchOpenListRawUrl(OPENLIST_FONT_ROOT + "/" + fileName);
                    URL url = new URL(rawUrl);
                    connection = (HttpURLConnection) url.openConnection();
                    connection.setConnectTimeout(12000);
                    connection.setReadTimeout(120000);
                    connection.setUseCaches(false);
                    connection.setRequestProperty("Accept", "application/octet-stream");
                    int code = connection.getResponseCode();
                    if (code < 200 || code >= 300) {
                        throw new Exception("字体下载失败（" + code + "）");
                    }
                    final long total = connection.getContentLengthLong();
                    runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            progress.setIndeterminate(total <= 0L);
                            message.setText("正在下载字体，请保持网络连接…");
                        }
                    });

                    File target = downloadedBookFontFile(style);
                    if (target == null) {
                        throw new Exception("字体保存路径不可用");
                    }
                    File directory = target.getParentFile();
                    if (directory == null || (!directory.exists() && !directory.mkdirs())) {
                        throw new Exception("无法创建字体目录");
                    }
                    temporary = new File(directory, fileName + ".download");
                    if (temporary.exists()) {
                        temporary.delete();
                    }
                    InputStream input = connection.getInputStream();
                    FileOutputStream output = new FileOutputStream(temporary);
                    try {
                        byte[] buffer = new byte[32768];
                        long received = 0L;
                        int lastProgress = -1;
                        int count;
                        while ((count = input.read(buffer)) >= 0) {
                            if (count == 0) {
                                continue;
                            }
                            output.write(buffer, 0, count);
                            received += count;
                            if (total > 0L) {
                                int value = (int) Math.min(99L, received * 100L / total);
                                if (value != lastProgress) {
                                    lastProgress = value;
                                    final int shown = value;
                                    runOnUiThread(new Runnable() {
                                        @Override
                                        public void run() {
                                            progress.setProgress(shown);
                                            percent.setText(shown + "%");
                                        }
                                    });
                                }
                            }
                        }
                        output.flush();
                    } finally {
                        output.close();
                        input.close();
                    }
                    if (temporary.length() < 65536L) {
                        throw new Exception("字体文件不完整");
                    }
                    Typeface checked = Typeface.createFromFile(temporary);
                    if (checked == null) {
                        throw new Exception("字体文件无法识别");
                    }
                    if (target.exists() && !target.delete()) {
                        throw new Exception("旧字体文件无法替换");
                    }
                    if (!temporary.renameTo(target)) {
                        throw new Exception("字体文件保存失败");
                    }
                    temporary = null;
                    final Typeface downloaded = checked;
                    runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            downloadedTypefaceCache.put(style, downloaded);
                            progress.setIndeterminate(false);
                            progress.setProgress(100);
                            percent.setText("100%");
                            message.setText("下载完成，已经可以使用");
                            message.postDelayed(new Runnable() {
                                @Override
                                public void run() {
                                    dialog.dismiss();
                                    if (onSuccess != null) {
                                        onSuccess.run();
                                    }
                                }
                            }, 420L);
                        }
                    });
                } catch (final Exception error) {
                    if (temporary != null && temporary.exists()) {
                        temporary.delete();
                    }
                    runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            progress.setIndeterminate(false);
                            message.setText(error.getMessage() == null ? "字体下载失败，请稍后重试" : error.getMessage());
                            percent.setText("下载失败");
                            message.postDelayed(new Runnable() {
                                @Override
                                public void run() {
                                    dialog.dismiss();
                                }
                            }, 1400L);
                        }
                    });
                } finally {
                    if (connection != null) {
                        connection.disconnect();
                    }
                }
            }
        }).start();
    }

    private void styleBookText(TextView view, boolean bold, int role) {
        String style = bookFontStyle();
        view.setTypeface(bookDetailTypeface(bold));
        view.getPaint().setTextSkewX(0f);
        view.setTextScaleX(1f);
        view.getPaint().setFakeBoldText(false);
        view.setShadowLayer(0f, 0f, 0f, Color.TRANSPARENT);
        if (Build.VERSION.SDK_INT >= 21) {
            view.setLetterSpacing(0f);
        }
        if ("yozai".equals(style)) {
            view.getPaint().setTextSkewX(-0.03f);
            view.setTextScaleX(role == 1 ? 1.02f : 1.0f);
            view.getPaint().setFakeBoldText(bold && role != 0);
            view.setShadowLayer(dp(0.5f), 0f, dp(0.35f), Color.argb(52, 88, 76, 62));
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(role == 1 ? 0.014f : 0.004f);
            }
        } else if ("xiaolai".equals(style)) {
            view.getPaint().setTextSkewX(0f);
            view.setTextScaleX(role == 1 ? 1.03f : 1.0f);
            view.getPaint().setFakeBoldText(bold && role == 1);
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(role == 1 ? 0.016f : 0.004f);
            }
        } else if ("wenkai".equals(style)) {
            view.getPaint().setFakeBoldText(bold && role == 1);
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(0.01f);
            }
        } else if ("marker".equals(style)) {
            view.setTextScaleX(role == 1 ? 1.02f : 1.0f);
            view.getPaint().setFakeBoldText(bold || role == 1);
            view.setShadowLayer(dp(0.35f), 0f, dp(0.25f), Color.argb(38, 82, 70, 58));
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(role == 1 ? 0.012f : 0.003f);
            }
        } else if ("zcool".equals(style)) {
            view.setTextScaleX(role == 1 ? 1.02f : 1.0f);
            view.getPaint().setFakeBoldText(bold || role == 1);
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(role == 1 ? 0.014f : 0.004f);
            }
        } else if ("slim".equals(style)) {
            view.setTextScaleX(0.76f);
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(0.08f);
            }
        }
        if (role == 2 && ("yozai".equals(style)
                || "xiaolai".equals(style) || "wenkai".equals(style) || "marker".equals(style)
                || "zcool".equals(style))) {
            view.setTextSize(view.getTextSize() / getResources().getDisplayMetrics().scaledDensity + 1f);
        } else if (role == 1 && "slim".equals(style)) {
            view.setTextSize(view.getTextSize() / getResources().getDisplayMetrics().scaledDensity - 1f);
        }
    }

