    private String callChatApi(String endpoint, String key, String model, String prompt) {
        return callChatApiInternal(endpoint, key, model, prompt, null);
    }

    private String callChatApiWithImages(String endpoint, String key, String model, String prompt, List<File> images) {
        return callChatApiInternal(endpoint, key, model, prompt, images);
    }

    private String callChatApiInternal(String endpoint, String key, String model, String prompt, List<File> images) {
        HttpURLConnection conn = null;
        try {
            URL url = new URL(endpoint);
            conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setConnectTimeout(12000);
            conn.setReadTimeout(18000);
            conn.setUseCaches(false);
            conn.setDoOutput(true);
            conn.setRequestProperty("Content-Type", "application/json; charset=UTF-8");
            conn.setRequestProperty("Authorization", "Bearer " + key);
            JSONObject body = new JSONObject();
            body.put("model", model);
            body.put("temperature", "thinking".equals(apiModelMode()) ? 0.15 : 0.35);
            JSONArray messages = new JSONArray();
            JSONObject user = new JSONObject();
            user.put("role", "user");
            if (images != null && !images.isEmpty()) {
                JSONArray content = new JSONArray();
                JSONObject textPart = new JSONObject();
                textPart.put("type", "text");
                textPart.put("text", prompt);
                content.put(textPart);
                for (int i = 0; i < images.size(); i++) {
                    JSONObject part = imageContentPart(images.get(i));
                    if (part != null) {
                        content.put(part);
                    }
                }
                user.put("content", content);
            } else {
                user.put("content", prompt);
            }
            messages.put(user);
            body.put("messages", messages);
            OutputStream out = conn.getOutputStream();
            try {
                out.write(body.toString().getBytes("UTF-8"));
            } finally {
                out.close();
            }
            int code = conn.getResponseCode();
            InputStream in = code >= 200 && code < 300 ? conn.getInputStream() : conn.getErrorStream();
            String text = in == null ? "" : readAll(in);
            if (in != null) {
                in.close();
            }
            if (code < 200 || code >= 300) {
                return "";
            }
            JSONObject result = new JSONObject(text);
            JSONArray choices = result.optJSONArray("choices");
            if (choices == null || choices.length() == 0) {
                return "";
            }
            JSONObject choice = choices.optJSONObject(0);
            JSONObject message = choice == null ? null : choice.optJSONObject("message");
            return message == null ? "" : message.optString("content", "").trim();
        } catch (Exception e) {
            return "";
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    private JSONObject imageContentPart(File file) {
        try {
            String dataUri = imageDataUri(file);
            if (dataUri.length() == 0) {
                return null;
            }
            JSONObject url = new JSONObject();
            url.put("url", dataUri);
            JSONObject part = new JSONObject();
            part.put("type", "image_url");
            part.put("image_url", url);
            return part;
        } catch (Exception e) {
            return null;
        }
    }

    private String imageDataUri(File file) {
        if (file == null || !file.exists()) {
            return "";
        }
        Bitmap bitmap = decodeFileSampled(file, 720);
        if (bitmap == null) {
            return "";
        }
        Bitmap scaled = scaleInside(bitmap, 640);
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try {
            String mime;
            if (file.getName().toLowerCase(Locale.US).endsWith(".png")) {
                scaled.compress(Bitmap.CompressFormat.PNG, 100, baos);
                mime = "image/png";
            } else {
                scaled.compress(Bitmap.CompressFormat.JPEG, 74, baos);
                mime = "image/jpeg";
            }
            return "data:" + mime + ";base64," + Base64.encodeToString(baos.toByteArray(), Base64.NO_WRAP);
        } finally {
            recycleBitmapUnless(scaled, bitmap);
            recycleBitmapUnless(bitmap, null);
        }
    }

