    private void updateVibrationLevelChips(TextView[] chips, int selectedLevel) {
        if (chips == null) {
            return;
        }
        for (int i = 0; i < chips.length; i++) {
            TextView chip = chips[i];
            if (chip == null) {
                continue;
            }
            boolean selected = i + 1 == selectedLevel;
            chip.setTextColor(selected ? Color.WHITE : Color.rgb(100, 104, 112));
            chip.setBackgroundColor(Color.TRANSPARENT);
        }
    }

    private int vibrationIndicatorColor() {
        return nightDecoration()
                ? adjustAlpha(blendColor(accent, Color.WHITE, 0.18f), 216)
                : adjustAlpha(blendColor(accent, Color.WHITE, 0.18f), 218);
    }

    private void updateVibrationIndicator(FrameLayout host, View indicator, int selectedLevel, boolean animated) {
        if (host == null || indicator == null) {
            return;
        }
        int innerWidth = host.getWidth() - host.getPaddingLeft() - host.getPaddingRight();
        int innerHeight = host.getHeight() - host.getPaddingTop() - host.getPaddingBottom();
        if (innerWidth <= 0 || innerHeight <= 0) {
            return;
        }
        int slot = innerWidth / 3;
        int inset = dp(6);
        FrameLayout.LayoutParams lp = (FrameLayout.LayoutParams) indicator.getLayoutParams();
        lp.width = Math.max(1, slot - inset * 2);
        lp.height = Math.max(1, innerHeight - dp(6));
        lp.leftMargin = host.getPaddingLeft() + inset;
        lp.topMargin = host.getPaddingTop() + (innerHeight - lp.height) / 2;
        indicator.setLayoutParams(lp);
        float target = (Math.max(1, Math.min(3, selectedLevel)) - 1) * slot;
        indicator.animate().cancel();
        if (animated) {
            indicator.animate().translationX(target).setDuration(280)
                    .setInterpolator(new android.view.animation.DecelerateInterpolator(1.75f)).start();
        } else {
            indicator.setTranslationX(target);
        }
    }

