    private String[] fontSizeNames() {
        return new String[]{"超级小", "很小", "比较小", "适中", "比较大", "很大", "特别大"};
    }

    private int[] fontSizeValues() {
        return new int[]{80, 86, 93, 100, 108, 116, 126};
    }

    private int closestFontLevel() {
        int current = profile.optInt("font", 100);
        int[] values = fontSizeValues();
        int best = 3;
        int bestDiff = Math.abs(current - values[best]);
        for (int i = 0; i < values.length; i++) {
            int diff = Math.abs(current - values[i]);
            if (diff < bestDiff) {
                best = i;
                bestDiff = diff;
            }
        }
        return best;
    }

    private String fontSizeTitle() {
        return fontSizeNames()[closestFontLevel()];
    }

