    private void updateLayoutPreview(LinearLayout preview, int level) {
        preview.removeAllViews();
        int gap = Math.max(4, Math.round(5 + level / 14f));
        int[] widths = {74, 58, 88};
        for (int i = 0; i < widths.length; i++) {
            View line = new View(this);
            line.setBackground(round(blendColor(accentSoft, accent, 0.20f + i * 0.08f), dp(6), 0, 0));
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(dp(widths[i]), dp(8));
            lp.bottomMargin = i == widths.length - 1 ? 0 : dp(gap);
            preview.addView(line, lp);
        }
    }

