    private void chooseFootprintGap() {
        final AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(22), dp(20), dp(22), dp(18));
        box.setBackground(round(dialogSurfaceColor(), dp(26), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));

        TextView title = label("本子间距", 22, Color.rgb(28, 28, 30), true);
        title.setPadding(0, 0, 0, dp(10));
        box.addView(title);

        final TextView value = label("当前间距 " + footprintGap() + " dp", 17,
                themedTextColor(Color.rgb(54, 58, 64)), true);
        value.setGravity(Gravity.CENTER);
        value.setPadding(0, dp(8), 0, dp(8));
        value.setBackground(round(adjustAlpha(accentSoft, 168), dp(15), adjustAlpha(accent, 72), dp(1)));
        box.addView(value, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT));

        final SeekBar seek = new SeekBar(this);
        seek.setMax(24);
        seek.setProgress(footprintGap() - 4);
        styleThickSeekBar(seek);
        LinearLayout.LayoutParams seekLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(54));
        seekLp.topMargin = dp(6);
        box.addView(seek, seekLp);

        final LinearLayout preview = row(Gravity.CENTER);
        preview.setPadding(dp(12), dp(14), dp(12), dp(14));
        preview.setBackground(round(nightDecoration() ? Color.argb(132, 42, 44, 50)
                        : Color.argb(118, 246, 249, 250), dp(18), surfaceStrokeColor(), dp(1)));
        final View leftBook = new View(this);
        leftBook.setBackground(new BookCoverDrawable("2026-07-10", bookPalette("2026-07-10", accent), bookCoverStyle()));
        final View rightBook = new View(this);
        rightBook.setBackground(new BookCoverDrawable("2026-07-09", bookPalette("2026-07-09", accent), bookCoverStyle()));
        preview.addView(leftBook, new LinearLayout.LayoutParams(dp(72), dp(92)));
        final LinearLayout.LayoutParams rightLp = new LinearLayout.LayoutParams(dp(72), dp(92));
        rightLp.leftMargin = dp(footprintGap());
        preview.addView(rightBook, rightLp);
        box.addView(preview, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(120)));

        seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override
            public void onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                int gap = Math.max(4, Math.min(28, progress + 4));
                value.setText("当前间距 " + gap + " dp");
                rightLp.leftMargin = dp(gap);
                rightBook.setLayoutParams(rightLp);
                preview.requestLayout();
            }

            @Override
            public void onStartTrackingTouch(SeekBar seekBar) {
            }

            @Override
            public void onStopTrackingTouch(SeekBar seekBar) {
            }
        });

        LinearLayout actions = row(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        actions.setPadding(0, dp(14), 0, 0);
        TextView cancel = dialogButton("取消", Color.argb(112, 240, 242, 245),
                themedTextColor(Color.rgb(90, 90, 90)));
        TextView save = dialogButton("保存", adjustAlpha(accent, 224), Color.WHITE);
        cancel.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                dialog.dismiss();
            }
        });
        save.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                try {
                    profile.put("footprintGap", Math.max(4, Math.min(28, seek.getProgress() + 4)));
                    saveProfile();
                    dialog.dismiss();
                    rerenderPreservingScroll(new Runnable() {
                        @Override
                        public void run() {
                            renderInterfaceLayoutPage();
                        }
                    });
                } catch (JSONException ignored) {
                }
            }
        });
        LinearLayout.LayoutParams cancelLp = new LinearLayout.LayoutParams(dp(78), dp(42));
        cancelLp.rightMargin = dp(10);
        actions.addView(cancel, cancelLp);
        actions.addView(save, new LinearLayout.LayoutParams(dp(78), dp(42)));
        box.addView(actions);
        showRoundedDialog(dialog, box);
    }

