    private void saveImportedMealSticker(String date, String mealKey, Bitmap sticker) {
        saveImportedMealSticker(date, mealKey, sticker, true);
    }

    private boolean saveImportedMealSticker(String date, String mealKey, Bitmap sticker, boolean showToast) {
        Bitmap prepared = null;
        Bitmap scaled = null;
        try {
            prepared = prepareImportedSticker(sticker);
            if (prepared == null) {
                return false;
            }
            scaled = scaleInside(prepared, 720);
            return saveMealSticker(date, mealKey, scaled, showToast);
        } catch (OutOfMemoryError error) {
            releaseThumbnailMemory();
            Log.e(LOG_TAG, "Out of memory importing meal sticker", error);
            return false;
        } finally {
            recycleBitmapUnless(scaled, sticker);
            if (prepared != scaled) {
                recycleBitmapUnless(prepared, sticker);
            }
        }
    }

    private Bitmap prepareImportedSticker(Bitmap sticker) {
        if (sticker == null) {
            return null;
        }
        Bitmap argb = sticker.getConfig() == Bitmap.Config.ARGB_8888
                ? sticker.copy(Bitmap.Config.ARGB_8888, true)
                : sticker.copy(Bitmap.Config.ARGB_8888, true);
        if (argb == null) {
            return sticker;
        }
        Bitmap cleared = hasTransparentPixels(argb) ? argb : removeEdgeBackground(argb);
        if (cleared != argb) {
            recycleBitmapUnless(argb, sticker);
        }
        Bitmap trimmed = trimTransparentSticker(cleared);
        if (trimmed != null && trimmed != cleared) {
            recycleBitmapUnless(cleared, sticker);
        }
        return trimmed == null ? cleared : trimmed;
    }

    private boolean hasTransparentPixels(Bitmap bitmap) {
        if (bitmap == null) {
            return false;
        }
        int w = bitmap.getWidth();
        int h = bitmap.getHeight();
        int[] row = new int[w];
        for (int y = 0; y < h; y += Math.max(1, h / 64)) {
            bitmap.getPixels(row, 0, w, 0, y, w, 1);
            for (int x = 0; x < w; x += Math.max(1, w / 64)) {
                if (Color.alpha(row[x]) < 245) {
                    return true;
                }
            }
        }
        return false;
    }

    private Bitmap removeEdgeBackground(Bitmap src) {
        int w = src.getWidth();
        int h = src.getHeight();
        if (w < 4 || h < 4) {
            return src;
        }
        int[] pixels = new int[w * h];
        src.getPixels(pixels, 0, w, 0, 0, w, h);
        int bg = averageCornerColor(pixels, w, h);
        int c1 = pixels[0];
        int c2 = pixels[w - 1];
        int c3 = pixels[(h - 1) * w];
        int c4 = pixels[h * w - 1];
        if (colorDistance(c1, bg) > 72 || colorDistance(c2, bg) > 72
                || colorDistance(c3, bg) > 72 || colorDistance(c4, bg) > 72) {
            return src;
        }
        int luminance = (Color.red(bg) * 30 + Color.green(bg) * 59 + Color.blue(bg) * 11) / 100;
        int threshold = luminance < 60 ? 68 : (luminance > 205 ? 54 : 46);
        boolean[] visited = new boolean[w * h];
        int[] queue = new int[w * h];
        int head = 0;
        int tail = 0;
        for (int x = 0; x < w; x++) {
            tail = enqueueBackgroundPixel(pixels, visited, queue, tail, x, bg, threshold);
            tail = enqueueBackgroundPixel(pixels, visited, queue, tail, (h - 1) * w + x, bg, threshold);
        }
        for (int y = 1; y < h - 1; y++) {
            tail = enqueueBackgroundPixel(pixels, visited, queue, tail, y * w, bg, threshold);
            tail = enqueueBackgroundPixel(pixels, visited, queue, tail, y * w + w - 1, bg, threshold);
        }
        while (head < tail) {
            int index = queue[head++];
            pixels[index] = Color.argb(0, Color.red(pixels[index]), Color.green(pixels[index]), Color.blue(pixels[index]));
            int x = index % w;
            int y = index / w;
            if (x > 0) {
                tail = enqueueBackgroundPixel(pixels, visited, queue, tail, index - 1, bg, threshold);
            }
            if (x < w - 1) {
                tail = enqueueBackgroundPixel(pixels, visited, queue, tail, index + 1, bg, threshold);
            }
            if (y > 0) {
                tail = enqueueBackgroundPixel(pixels, visited, queue, tail, index - w, bg, threshold);
            }
            if (y < h - 1) {
                tail = enqueueBackgroundPixel(pixels, visited, queue, tail, index + w, bg, threshold);
            }
        }
        Bitmap out = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        out.setPixels(pixels, 0, w, 0, 0, w, h);
        return out;
    }

    private int enqueueBackgroundPixel(int[] pixels, boolean[] visited, int[] queue, int tail,
                                       int index, int bg, int threshold) {
        if (index < 0 || index >= pixels.length || visited[index]) {
            return tail;
        }
        int color = pixels[index];
        if (Color.alpha(color) < 30 || colorDistance(color, bg) <= threshold) {
            visited[index] = true;
            queue[tail++] = index;
        }
        return tail;
    }

    private int averageCornerColor(int[] pixels, int w, int h) {
        int patch = Math.max(2, Math.min(8, Math.min(w, h) / 12));
        long a = 0;
        long r = 0;
        long g = 0;
        long b = 0;
        int count = 0;
        for (int y = 0; y < patch; y++) {
            for (int x = 0; x < patch; x++) {
                int[] indices = new int[]{
                        y * w + x,
                        y * w + (w - 1 - x),
                        (h - 1 - y) * w + x,
                        (h - 1 - y) * w + (w - 1 - x)
                };
                for (int i = 0; i < indices.length; i++) {
                    int color = pixels[indices[i]];
                    a += Color.alpha(color);
                    r += Color.red(color);
                    g += Color.green(color);
                    b += Color.blue(color);
                    count++;
                }
            }
        }
        return Color.argb((int) (a / count), (int) (r / count), (int) (g / count), (int) (b / count));
    }

    private int colorDistance(int left, int right) {
        int dr = Color.red(left) - Color.red(right);
        int dg = Color.green(left) - Color.green(right);
        int db = Color.blue(left) - Color.blue(right);
        return Math.abs(dr) + Math.abs(dg) + Math.abs(db);
    }

    private void savePng(Bitmap bitmap, File out) throws Exception {
        FileOutputStream fos = new FileOutputStream(out);
        try {
            if (!bitmap.compress(Bitmap.CompressFormat.PNG, 100, fos)) {
                throw new Exception("PNG encode failed");
            }
            fos.flush();
        } finally {
            fos.close();
        }
    }

    private Bitmap scaleInside(Bitmap src, int maxSide) {
        int w = src.getWidth();
        int h = src.getHeight();
        float scale = Math.min(1f, maxSide / (float) Math.max(w, h));
        if (scale >= 1f) {
            return src;
        }
        return Bitmap.createScaledBitmap(src, Math.max(1, (int) (w * scale)),
                Math.max(1, (int) (h * scale)), true);
    }

    private void createAiStickerFromViewer(final String date, final String mealKey,
                                           final Bitmap source, final float bitmapX, final float bitmapY) {
        if (source == null) {
            showGlassToast("图片读取失败", Toast.LENGTH_SHORT);
            return;
        }
        if (!ensureSamNativeLoaded()) {
            showGlassToast("AI贴纸模块没有准备好", Toast.LENGTH_SHORT);
            return;
        }
        requestAiStickerCandidate(source, bitmapX, bitmapY, 0, new AiStickerHandler() {
            @Override
            public void onSticker(Bitmap sticker, String error) {
                if (sticker == null) {
                    showGlassToast(error == null ? "AI没有识别到合适的贴纸" : "AI贴纸生成失败", Toast.LENGTH_SHORT);
                    return;
                }
                showAiStickerPreview(date, mealKey, source, bitmapX, bitmapY, 0, sticker);
            }
        });
    }

    private void requestAiStickerCandidate(final Bitmap source, final float bitmapX, final float bitmapY,
                                           final int candidateIndex, final AiStickerHandler handler) {
        final View loading = showAiCutoutLoading();
        new Thread(new Runnable() {
            @Override
            public void run() {
                Bitmap input = null;
                Bitmap output = null;
                String error = null;
                try {
                    File embed = ensureAssetFile(SAM_EMBED_ASSET, SAM_EMBED_FILE);
                    File segment = ensureAssetFile(SAM_SEGMENT_ASSET, SAM_SEGMENT_FILE);
                    input = source.getConfig() == Bitmap.Config.ARGB_8888
                            ? source.copy(Bitmap.Config.ARGB_8888, false)
                            : source.copy(Bitmap.Config.ARGB_8888, false);
                    if (input == null) {
                        throw new Exception("input copy failed");
                    }
                    output = Bitmap.createBitmap(input.getWidth(), input.getHeight(), Bitmap.Config.ARGB_8888);
                    boolean ok = nativeSamSticker(input, output, bitmapX, bitmapY, candidateIndex,
                            embed.getAbsolutePath(), segment.getAbsolutePath());
                    if (!ok) {
                        throw new Exception("ai inference failed");
                    }
                    if (!hasVisibleAlpha(output)) {
                        throw new Exception("empty mask");
                    }
                } catch (Exception e) {
                    error = e.getMessage();
                }
                final Bitmap finalSticker = error == null ? output : null;
                final String finalError = error;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        closeAiCutoutLoading(loading);
                        handler.onSticker(finalSticker, finalError);
                    }
                });
            }
        }).start();
    }

    private void showAiStickerPreview(final String date, final String mealKey, final Bitmap source,
                                      final float bitmapX, final float bitmapY,
                                      final int startCandidate, Bitmap sticker) {
        closeAiStickerPreview();
        final FrameLayout overlay = new FrameLayout(this);
        aiPreviewOverlay = overlay;
        overlay.setClickable(true);
        overlay.setAlpha(0f);
        overlay.setBackgroundColor(photoViewerBackgroundColor());

        final AiStickerPreviewView preview = new AiStickerPreviewView(this);
        preview.setBitmaps(source, sticker);
        overlay.addView(preview, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        TextView title = label("挖出贴纸", 20, photoViewerTextColor(), true);
        title.setPadding(dp(20), dp(54), dp(20), 0);
        overlay.addView(title);
        TextView hint = label("灰色是未选中部分，清晰区域会保存为贴纸", 13,
                "white".equals(profile.optString("photoBg", "black")) ? Color.rgb(110, 114, 122) : Color.rgb(215, 218, 224), false);
        hint.setPadding(dp(20), dp(86), dp(20), 0);
        hint.setLineSpacing(dp(2), 1.05f);
        overlay.addView(hint);

        LinearLayout actions = row(Gravity.CENTER);
        actions.setPadding(dp(18), dp(14), dp(18), dp(18));
        actions.setBackground(round(photoViewerPillColor(), dp(28), 0, 0));
        final TextView cancel = dialogButton("取消", Color.rgb(245, 246, 248), Color.rgb(90, 90, 90));
        final TextView next = dialogButton("换一个", accentSoft, accent);
        final TextView save = dialogButton("保存贴纸", accent, Color.WHITE);
        final Bitmap[] currentSticker = new Bitmap[]{sticker};
        final int[] candidate = new int[]{startCandidate};
        final boolean[] busy = new boolean[]{false};

        cancel.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                closeAiStickerPreview();
            }
        });
        next.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (busy[0]) {
                    return;
                }
                busy[0] = true;
                next.setAlpha(0.55f);
                candidate[0] = (candidate[0] + 1) % AI_STICKER_CANDIDATE_COUNT;
                requestAiStickerCandidate(source, bitmapX, bitmapY, candidate[0], new AiStickerHandler() {
                    @Override
                    public void onSticker(Bitmap sticker, String error) {
                        busy[0] = false;
                        next.setAlpha(1f);
                        if (sticker == null) {
                            showGlassToast("这个候选也没识别好", Toast.LENGTH_SHORT);
                            return;
                        }
                        currentSticker[0] = sticker;
                        preview.setSticker(sticker);
                    }
                });
            }
        });
        save.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Bitmap trimmed = trimTransparentSticker(currentSticker[0]);
                if (trimmed == null) {
                    showGlassToast("这张贴纸为空，换一个试试", Toast.LENGTH_SHORT);
                    return;
                }
                saveMealSticker(date, mealKey, scaleInside(trimmed, 720));
                closeAiStickerPreview();
                closePhotoViewer();
                root.postDelayed(new Runnable() {
                    @Override
                    public void run() {
                        if (inBookDetail) {
                            renderBookDetail(date);
                        } else {
                            renderCurrent();
                        }
                    }
                }, 180);
            }
        });

        LinearLayout.LayoutParams cancelLp = new LinearLayout.LayoutParams(dp(86), dp(46));
        cancelLp.rightMargin = dp(10);
        LinearLayout.LayoutParams nextLp = new LinearLayout.LayoutParams(dp(96), dp(46));
        nextLp.rightMargin = dp(10);
        actions.addView(cancel, cancelLp);
        actions.addView(next, nextLp);
        actions.addView(save, new LinearLayout.LayoutParams(dp(112), dp(46)));
        FrameLayout.LayoutParams actionsLp = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        actionsLp.gravity = Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL;
        actionsLp.bottomMargin = dp(34);
        overlay.addView(actions, actionsLp);

        content.addView(overlay, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        overlay.animate().alpha(1f).setDuration(170).start();
    }

    private void closeAiStickerPreview() {
        final View overlay = aiPreviewOverlay;
        if (overlay == null) {
            return;
        }
        aiPreviewOverlay = null;
        if (overlay.getParent() == null) {
            return;
        }
        overlay.animate().alpha(0f).setDuration(150).withEndAction(new Runnable() {
            @Override
            public void run() {
                ViewParent parent = overlay.getParent();
                if (parent instanceof ViewGroup) {
                    ((ViewGroup) parent).removeView(overlay);
                }
            }
        }).start();
    }

    private View showAiCutoutLoading() {
        final FrameLayout overlay = new FrameLayout(this);
        overlay.setClickable(true);
        overlay.setBackgroundColor(Color.argb(80, 0, 0, 0));
        LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(LinearLayout.VERTICAL);
        panel.setGravity(Gravity.CENTER);
        panel.setPadding(dp(20), dp(16), dp(20), dp(16));
        panel.setBackground(round(dialogSurfaceColor(), dp(22), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        TextView title = label("AI正在挖出贴纸", 17, themedTextColor(Color.rgb(28, 28, 30)), true);
        title.setGravity(Gravity.CENTER);
        panel.addView(title);
        TextView tip = label("第一次会准备模型，稍等一下下", 13, themedTextColor(Color.rgb(118, 122, 130)), false);
        tip.setGravity(Gravity.CENTER);
        tip.setPadding(0, dp(6), 0, 0);
        panel.addView(tip);
        FrameLayout.LayoutParams panelLp = new FrameLayout.LayoutParams(
                (int) (getResources().getDisplayMetrics().widthPixels * 0.72f),
                ViewGroup.LayoutParams.WRAP_CONTENT);
        panelLp.gravity = Gravity.CENTER;
        overlay.addView(panel, panelLp);
        content.addView(overlay, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        overlay.setAlpha(0f);
        overlay.animate().alpha(1f).setDuration(150).start();
        return overlay;
    }

    private void closeAiCutoutLoading(final View loading) {
        if (loading == null || loading.getParent() == null) {
            return;
        }
        loading.animate().alpha(0f).setDuration(130).withEndAction(new Runnable() {
            @Override
            public void run() {
                ViewParent parent = loading.getParent();
                if (parent instanceof ViewGroup) {
                    ((ViewGroup) parent).removeView(loading);
                }
            }
        }).start();
    }

    private boolean ensureSamNativeLoaded() {
        if (samNativeLoaded) {
            return true;
        }
        if (samNativeTried) {
            return false;
        }
        samNativeTried = true;
        try {
            System.loadLibrary("c++_shared");
            System.loadLibrary("MNN");
            System.loadLibrary("MNN_Express");
            System.loadLibrary("MNNOpenCV");
            System.loadLibrary("eatsam");
            samNativeLoaded = true;
            return true;
        } catch (Throwable ignored) {
            return false;
        }
    }

    private File ensureAssetFile(String assetName, String fileName) throws Exception {
        File out = new File(getFilesDir(), fileName);
        if (out.exists() && out.length() > 1024) {
            return out;
        }
        InputStream in = getAssets().open(assetName);
        FileOutputStream fos = new FileOutputStream(out);
        byte[] buffer = new byte[1024 * 256];
        int read;
        try {
            while ((read = in.read(buffer)) != -1) {
                fos.write(buffer, 0, read);
            }
            fos.flush();
        } finally {
            try {
                in.close();
            } catch (Exception ignored) {
            }
            try {
                fos.close();
            } catch (Exception ignored) {
            }
        }
        return out;
    }

    private Bitmap trimTransparentSticker(Bitmap src) {
        if (src == null) {
            return null;
        }
        int w = src.getWidth();
        int h = src.getHeight();
        int[] pixels = new int[w * h];
        src.getPixels(pixels, 0, w, 0, 0, w, h);
        int left = w;
        int top = h;
        int right = -1;
        int bottom = -1;
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (Color.alpha(pixels[y * w + x]) > 8) {
                    if (x < left) left = x;
                    if (x > right) right = x;
                    if (y < top) top = y;
                    if (y > bottom) bottom = y;
                }
            }
        }
        if (right < left || bottom < top) {
            return null;
        }
        int pad = dp(8);
        left = Math.max(0, left - pad);
        top = Math.max(0, top - pad);
        right = Math.min(w - 1, right + pad);
        bottom = Math.min(h - 1, bottom + pad);
        return Bitmap.createBitmap(src, left, top, right - left + 1, bottom - top + 1);
    }

    private boolean hasVisibleAlpha(Bitmap src) {
        if (src == null) {
            return false;
        }
        int w = src.getWidth();
        int h = src.getHeight();
        int[] row = new int[w];
        for (int y = 0; y < h; y++) {
            src.getPixels(row, 0, w, 0, y, w, 1);
            for (int x = 0; x < w; x++) {
                if (Color.alpha(row[x]) > 8) {
                    return true;
                }
            }
        }
        return false;
    }

    private TextView mediaEditControl(String symbol) {
        TextView control = label(symbol, 14, Color.WHITE, true);
        control.setTypeface(Typeface.DEFAULT_BOLD);
        control.setGravity(Gravity.CENTER);
        control.setVisibility(View.GONE);
        control.setBackground(round(Color.argb(232, 48, 50, 54), dp(10),
                Color.argb(236, 255, 255, 255), dp(1)));
        attachPressAnimation(control);
        return control;
    }

    private View mediaThumbView(final String date, final String mealKey, final String fileName,
                                final String arrayKey, final String title, boolean sticker, int size) {
        final FrameLayout frame = mediaImageFrame(fileName, sticker, size);
        frame.setClickable(true);

        final TextView rotate = mediaEditControl("↺");
        FrameLayout.LayoutParams rotateLp = new FrameLayout.LayoutParams(dp(20), dp(20));
        rotateLp.gravity = Gravity.LEFT | Gravity.TOP;
        rotateLp.topMargin = -dp(1);
        rotateLp.leftMargin = -dp(1);
        frame.addView(rotate, rotateLp);

        final TextView close = mediaEditControl("×");
        FrameLayout.LayoutParams closeLp = new FrameLayout.LayoutParams(dp(20), dp(20));
        closeLp.gravity = Gravity.RIGHT | Gravity.TOP;
        closeLp.topMargin = -dp(1);
        closeLp.rightMargin = -dp(1);
        frame.addView(close, closeLp);

        final PhotoAction action = new PhotoAction(date, mealKey, fileName, arrayKey, title, close, rotate);
        action.itemView = frame;
        frame.setTag(action);
        frame.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.editing) {
                    return;
                }
                showPhotoViewer(date, mealKey, fileName);
            }
        });
        close.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                confirmDeleteMedia(action);
            }
        });
        rotate.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                rotateMealMediaLeft(action);
            }
        });
        return frame;
    }

    private void installStandaloneMediaLongPress(final View item) {
        if (item == null || !(item.getTag() instanceof PhotoAction)) {
            return;
        }
        item.setLongClickable(true);
        item.setOnLongClickListener(new View.OnLongClickListener() {
            @Override
            public boolean onLongClick(View v) {
                if (!(v.getTag() instanceof PhotoAction)) {
                    return false;
                }
                exitMediaEditMode(false);
                editingMediaItems.clear();
                PhotoAction action = (PhotoAction) v.getTag();
                if (action.usesExpandedChildren()) {
                    playMediaEditFeedback();
                    for (View child : action.stackChildViews) {
                        if (child != null && child.getTag() instanceof PhotoAction) {
                            editingMediaItems.add(child);
                            ((PhotoAction) child.getTag()).enterEdit(child, false);
                        }
                    }
                } else {
                    editingMediaItems.add(v);
                    action.enterEdit(v);
                }
                return true;
            }
        });
    }

    private FrameLayout mediaImageFrame(String fileName, boolean sticker, int size) {
        FrameLayout frame = new FrameLayout(this);
        frame.setClipChildren(false);
        frame.setClipToPadding(false);
        frame.setPadding(dp(1), dp(1), dp(1), dp(1));
        RoundedImageView image = new RoundedImageView(this);
        image.setRadius(sticker ? stickerImageRadius(size) : dp(spaceByLayout(12, 10, 8)));
        image.setScaleType(sticker ? ImageView.ScaleType.FIT_CENTER : ImageView.ScaleType.CENTER_CROP);
        if (sticker) {
            image.setBackground(stickerFrameBackground());
            int pad = stickerFramePadding();
            image.setPadding(pad, pad, pad, pad);
        }
        loadMediaThumbnail(image, fileName, size);
        frame.addView(image, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        return frame;
    }

    private View mediaStackView(final String date, final String mealKey, final List<String> group,
                                final String arrayKey, final String title, final boolean sticker, final int size) {
        final FrameLayout stack = new FrameLayout(this);
        stack.setClipChildren(false);
        stack.setClipToPadding(false);
        stack.setClickable(true);
        final int count = group.size();
        final String topName = group.get(count - 1);
        final boolean[] expanded = new boolean[]{false};
        final List<View> popped = new ArrayList<View>();

        for (int i = count - 2; i >= 0; i--) {
            final String childName = group.get(i);
            View child = mediaThumbView(date, mealKey, childName, arrayKey, title, sticker, size);
            child.setVisibility(View.INVISIBLE);
            child.setAlpha(0f);
            child.setScaleX(0.86f);
            child.setScaleY(0.86f);
            child.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    PhotoAction childAction = v.getTag() instanceof PhotoAction
                            ? (PhotoAction) v.getTag() : null;
                    if (childAction != null && childAction.editing) {
                        return;
                    }
                    showPhotoViewer(date, mealKey, childName);
                }
            });
            popped.add(child);
            stack.addView(child, new FrameLayout.LayoutParams(size, size));
        }

        View top = mediaThumbView(date, mealKey, topName, arrayKey, title, sticker, size);
        top.setOnClickListener(null);
        top.setClickable(false);
        stack.addView(top, new FrameLayout.LayoutParams(size, size));

        final TextView badge = label("×" + count, 13, Color.WHITE, true);
        badge.setGravity(Gravity.CENTER);
        badge.setBackground(round(Color.argb(232, Color.red(accent), Color.green(accent), Color.blue(accent)),
                dp(11), Color.WHITE, dp(1)));
        badge.setClickable(true);
        attachPressAnimation(badge);
        FrameLayout.LayoutParams badgeLp = new FrameLayout.LayoutParams(dp(32), dp(22));
        badgeLp.gravity = Gravity.RIGHT | Gravity.BOTTOM;
        badgeLp.rightMargin = -dp(1);
        badgeLp.bottomMargin = -dp(1);
        stack.addView(badge, badgeLp);

        final TextView rotate = mediaEditControl("↺");
        FrameLayout.LayoutParams rotateLp = new FrameLayout.LayoutParams(dp(20), dp(20));
        rotateLp.gravity = Gravity.LEFT | Gravity.TOP;
        rotateLp.topMargin = -dp(1);
        rotateLp.leftMargin = -dp(1);
        stack.addView(rotate, rotateLp);

        final TextView close = mediaEditControl("×");
        FrameLayout.LayoutParams closeLp = new FrameLayout.LayoutParams(dp(20), dp(20));
        closeLp.gravity = Gravity.RIGHT | Gravity.TOP;
        closeLp.topMargin = -dp(1);
        closeLp.rightMargin = -dp(1);
        stack.addView(close, closeLp);

        final PhotoAction action = new PhotoAction(date, mealKey, topName, arrayKey, title, close, rotate);
        action.itemView = stack;
        action.stackNames = new ArrayList<String>(group);
        action.stackChildViews = new ArrayList<View>(popped);
        action.stackChildViews.add(top);
        action.stackExpandedState = expanded;
        stack.setTag(action);

        View.OnClickListener toggle = new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.editing) {
                    return;
                }
                toggleMediaStack(stack, popped, badge, size, count, expanded);
            }
        };
        badge.setOnClickListener(toggle);
        stack.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.editing) {
                    return;
                }
                if (!expanded[0]) {
                    toggleMediaStack(stack, popped, badge, size, count, expanded);
                } else {
                    showPhotoViewer(date, mealKey, topName);
                }
            }
        });
        close.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.unstackGroup()) {
                    showGlassToast("已取消叠放", Toast.LENGTH_SHORT);
                }
            }
        });
        rotate.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                rotateMealMediaLeft(action);
            }
        });
        return stack;
    }

    private void toggleMediaStack(final FrameLayout stack, final List<View> popped, final TextView badge,
                                  final int size, final int count, final boolean[] expanded) {
        final boolean expand = !expanded[0];
        expanded[0] = expand;
        int gap = dp(spaceByLayout(8, 6, 5));
        int startWidth = stack.getWidth() > 0 ? stack.getWidth() : size;
        int endWidth = expand ? size * count + gap * (count - 1) : size;
        ValueAnimator animator = ValueAnimator.ofInt(startWidth, endWidth);
        animator.setDuration(expand ? 280 : 230);
        animator.setInterpolator(new android.view.animation.DecelerateInterpolator(1.55f));
        animator.addUpdateListener(new ValueAnimator.AnimatorUpdateListener() {
            @Override
            public void onAnimationUpdate(ValueAnimator animation) {
                ViewGroup.LayoutParams lp = stack.getLayoutParams();
                lp.width = (Integer) animation.getAnimatedValue();
                stack.setLayoutParams(lp);
            }
        });
        animator.start();

        for (int i = 0; i < popped.size(); i++) {
            final View child = popped.get(i);
            child.animate().cancel();
            if (expand) {
                child.setVisibility(View.VISIBLE);
                child.setAlpha(0f);
                child.setTranslationX(0f);
                child.setScaleX(0.86f);
                child.setScaleY(0.86f);
                child.animate()
                        .alpha(1f)
                        .translationX((i + 1) * (size + gap))
                        .scaleX(1f)
                        .scaleY(1f)
                        .setStartDelay(i * 24L)
                        .setDuration(280)
                        .setInterpolator(new android.view.animation.DecelerateInterpolator(1.45f))
                        .start();
            } else {
                child.animate()
                        .alpha(0f)
                        .translationX(0f)
                        .scaleX(0.86f)
                        .scaleY(0.86f)
                        .setStartDelay((popped.size() - i - 1) * 18L)
                        .setDuration(220)
                        .withEndAction(new Runnable() {
                            @Override
                            public void run() {
                                child.setVisibility(View.INVISIBLE);
                            }
                        })
                        .start();
            }
        }
        badge.setText(expand ? "↙" : "×" + count);
        badge.animate().cancel();
        badge.setScaleX(0.88f);
        badge.setScaleY(0.88f);
        badge.animate().scaleX(1f).scaleY(1f).setDuration(180).start();
    }

    private String mediaStackKey(String arrayKey) {
        return "photos".equals(arrayKey) ? "photoStacks" : "stickerStacks";
    }

    private boolean isMediaStackedAfter(JSONObject meal, String arrayKey, String fileName, String previousName) {
        if (previousName == null || previousName.length() == 0) {
            return false;
        }
        JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
        return stacks != null && previousName.equals(stacks.optString(fileName, ""));
    }

    private boolean isMediaStacked(JSONObject meal, String arrayKey, String fileName) {
        JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
        if (stacks == null || fileName == null) {
            return false;
        }
        if (stacks.has(fileName)) {
            return true;
        }
        JSONArray names = stacks.names();
        if (names != null) {
            for (int i = 0; i < names.length(); i++) {
                if (fileName.equals(stacks.optString(names.optString(i)))) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean stackMealMedia(String date, String mealKey, String arrayKey, String fileName,
                                   String targetName) {
        if (fileName == null || targetName == null || fileName.equals(targetName)) {
            return false;
        }
        JSONObject meal = optObj(ensureDay(date), mealKey);
        JSONArray old = meal.optJSONArray(arrayKey);
        if (old == null) {
            return false;
        }
        List<String> names = new ArrayList<String>();
        for (int i = 0; i < old.length(); i++) {
            String name = old.optString(i);
            if (name.length() > 0) {
                names.add(name);
            }
        }
        int sourceIndex = names.indexOf(fileName);
        int targetIndex = names.indexOf(targetName);
        if (sourceIndex < 0 || targetIndex < 0) {
            return false;
        }
        clearMediaStackRefs(meal, arrayKey, fileName);
        names.remove(sourceIndex);
        if (sourceIndex < targetIndex) {
            targetIndex--;
        }
        names.add(targetIndex + 1, fileName);
        JSONArray next = new JSONArray();
        for (String name : names) {
            next.put(name);
        }
        try {
            meal.put(arrayKey, next);
            JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
            if (stacks == null) {
                stacks = new JSONObject();
                meal.put(mediaStackKey(arrayKey), stacks);
            }
            stacks.put(fileName, targetName);
            saveDays();
        } catch (JSONException ignored) {
            return false;
        }
        scheduleMediaRender(date);
        return true;
    }

    private boolean reorderMealMedia(String date, String mealKey, String arrayKey, String fileName,
                                     String targetName, boolean insertAfter) {
        if (fileName == null || targetName == null || fileName.equals(targetName)) {
            return false;
        }
        JSONObject meal = optObj(ensureDay(date), mealKey);
        JSONArray old = meal.optJSONArray(arrayKey);
        if (old == null) {
            return false;
        }
        List<String> names = new ArrayList<String>();
        for (int i = 0; i < old.length(); i++) {
            String name = old.optString(i);
            if (name.length() > 0) {
                names.add(name);
            }
        }
        List<String> original = new ArrayList<String>(names);
        int sourceIndex = names.indexOf(fileName);
        if (sourceIndex < 0 || !names.remove(fileName)) {
            return false;
        }
        int targetIndex = names.indexOf(targetName);
        if (targetIndex < 0) {
            return false;
        }
        int insertIndex = targetIndex + (insertAfter ? 1 : 0);
        names.add(Math.max(0, Math.min(insertIndex, names.size())), fileName);
        if (names.equals(original)) {
            return false;
        }
        clearMediaStackRefs(meal, arrayKey, fileName);
        JSONArray next = new JSONArray();
        for (String name : names) {
            next.put(name);
        }
        try {
            meal.put(arrayKey, next);
            saveDays();
        } catch (JSONException ignored) {
            return false;
        }
        scheduleMediaRender(date);
        return true;
    }

    private void scheduleMediaRender(final String date) {
        root.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (inBookDetail) {
                    renderBookDetail(date);
                } else {
                    renderCurrent();
                }
            }
        }, 70);
    }

    private boolean unstackMealMedia(String date, String mealKey, String arrayKey, String fileName) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        clearMediaStackRefs(meal, arrayKey, fileName);
        saveDays();
        scheduleMediaRender(date);
        return true;
    }

    private boolean unstackMediaGroup(String date, String mealKey, String arrayKey, List<String> names) {
        if (names == null || names.size() <= 1) {
            return false;
        }
        JSONObject meal = optObj(ensureDay(date), mealKey);
        for (String name : names) {
            clearMediaStackRefs(meal, arrayKey, name);
        }
        saveDays();
        scheduleMediaRender(date);
        return true;
    }

    private void applyStackLayout(View item, LinearLayout.LayoutParams lp, int size, int stackDepth) {
        int depth = Math.max(1, Math.min(3, stackDepth));
        lp.leftMargin = -Math.max(0, size - dp(3 + depth * 2));
        lp.rightMargin = 0;
        item.setPivotX(size * 0.50f);
        item.setPivotY(size);
        item.setRotation(depth % 2 == 0 ? -3.4f : 3.4f);
        item.setTranslationY(dp(depth > 1 ? 1 : 0));
        item.setElevation(dp(10 + depth));
    }

    private void clearMediaStackRefs(JSONObject meal, String arrayKey, String fileName) {
        JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
        if (stacks == null) {
            return;
        }
        stacks.remove(fileName);
        JSONArray names = stacks.names();
        if (names != null) {
            for (int i = 0; i < names.length(); i++) {
                String key = names.optString(i);
                if (fileName.equals(stacks.optString(key))) {
                    stacks.remove(key);
                }
            }
        }
        if (stacks.length() == 0) {
            meal.remove(mediaStackKey(arrayKey));
        }
    }

    private void clearAllMediaStacks() {
        JSONArray dateNames = days.names();
        if (dateNames == null) {
            return;
        }
        for (int i = 0; i < dateNames.length(); i++) {
            JSONObject day = days.optJSONObject(dateNames.optString(i));
            if (day == null) {
                continue;
            }
            for (MealOption mealOption : allMealOptions()) {
                JSONObject meal = day.optJSONObject(mealOption.key);
                if (meal != null) {
                    meal.remove("photoStacks");
                    meal.remove("stickerStacks");
                }
            }
        }
        saveDays();
    }

    private void addMediaGroupToRow(LinearLayout row, String date, String mealKey, List<String> group,
                                    String arrayKey, String title, boolean sticker, int size) {
        if (group == null || group.isEmpty()) {
            return;
        }
        View item = group.size() > 1
                ? mediaStackView(date, mealKey, new ArrayList<String>(group), arrayKey, title, sticker, size)
                : mediaThumbView(date, mealKey, group.get(0), arrayKey, title, sticker, size);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(size, size);
        lp.rightMargin = dp(spaceByLayout(8, 6, 5));
        row.addView(item, lp);
    }

    private View addMealPhotos(LinearLayout card, JSONObject meal, final String date, final String mealKey) {
        JSONArray photos = meal.optJSONArray("photos");
        if (photos == null || photos.length() == 0) {
            return null;
        }
        card.setClipChildren(false);
        card.setClipToPadding(false);
        PhotoStripScrollView scroller = new PhotoStripScrollView(this);
        scroller.setHorizontalScrollBarEnabled(false);
        scroller.setClipChildren(false);
        scroller.setClipToPadding(false);
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setClipChildren(false);
        row.setClipToPadding(false);
        row.setPadding(0, dp(spaceByLayout(8, 6, 4)), 0, 0);
        scroller.addView(row);
        String previousName = null;
        List<String> group = new ArrayList<String>();
        for (int i = 0; i < photos.length(); i++) {
            final String storedName = photos.optString(i);
            final File file = new File(getFilesDir(), storedName);
            if (!file.exists()) {
                continue;
            }
            int size = dp(spaceByLayout(76, 68, 60));
            if (!group.isEmpty() && isMediaStackedAfter(meal, "photos", storedName, previousName)) {
                group.add(storedName);
            } else {
                addMediaGroupToRow(row, date, mealKey, group, "photos", "图片", false, size);
                group.clear();
                group.add(storedName);
            }
            previousName = storedName;
        }
        addMediaGroupToRow(row, date, mealKey, group, "photos", "图片", false, dp(spaceByLayout(76, 68, 60)));
        card.addView(scroller, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        return scroller;
    }

