    private boolean sanitizeStoredHomeHints(JSONObject target) {
        JSONArray custom = target.optJSONArray("homeHints");
        if (custom == null) {
            return false;
        }
        JSONArray cleaned = new JSONArray();
        boolean changed = false;
        for (int i = 0; i < custom.length(); i++) {
            String original = stripHintTail(custom.optString(i)).trim();
            String value = sanitizeHomeHintText(original);
            if (!value.equals(original)) {
                changed = true;
            }
            if (value.length() > 0) {
                cleaned.put(value);
            } else {
                changed = true;
            }
        }
        if (!changed) {
            return false;
        }
        try {
            if (cleaned.length() == 0) {
                target.remove("homeHints");
            } else {
                target.put("homeHints", cleaned);
            }
        } catch (JSONException ignored) {
            return false;
        }
        return true;
    }

