    private String installId() {
        String id = prefs.getString(INSTALL_ID_KEY, "");
        if (id == null || id.length() == 0) {
            id = UUID.randomUUID().toString();
            prefs.edit().putString(INSTALL_ID_KEY, id).apply();
        }
        return id;
    }

    private void ensureCloudIdentity(final boolean showResult) {
        if (profile == null || cloudIdentityRequesting) {
            return;
        }
        String nickname = profile.optString("name", "").trim();
        if (nickname.length() == 0 || "给自己起个名字".equals(nickname)) {
            if (showResult) {
                showCreateAccountHint();
            }
            return;
        }
        String token = profile.optString("cloudToken", "");
        if (token.length() > 0 && !"cloud".equals(profile.optString("userIdSource", ""))) {
            try {
                profile.put("userIdSource", "cloud");
                saveProfile();
            } catch (JSONException ignored) {
            }
        }
        if (token.length() > 0) {
            syncCloudProfile(showResult);
            return;
        }
        cloudIdentityRequesting = true;
        new Thread(new Runnable() {
            @Override
            public void run() {
                final CloudResult result = allocateCloudIdentity();
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        cloudIdentityRequesting = false;
                        if (result.ok && result.user != null) {
                            applyCloudUser(result.user);
                            saveProfile();
                            syncCloudProfile(false);
                            if (showResult) {
                                showGlassToast("云端 ID 已同步：" + profileUserId(), Toast.LENGTH_SHORT);
                            }
                            if (inProfileSettingsPage) {
                                renderProfileSettingsPage();
                            } else {
                                renderCurrentProfileHeaderIfNeeded();
                            }
                        } else {
                            try {
                                profile.put("cloudSyncStatus", "failed");
                                profile.put("cloudSyncMessage", result.message.length() == 0 ? "云端暂时连接失败" : result.message);
                                saveProfile();
                            } catch (JSONException ignored) {
                            }
                            if (showResult) {
                                showGlassToast("云端暂时连接失败，本地资料已保留", Toast.LENGTH_LONG);
                            }
                            if (inProfileSettingsPage) {
                                renderProfileSettingsPage();
                            }
                        }
                    }
                });
            }
        }).start();
    }

    private void syncCloudProfile(final boolean showResult) {
        if (profile == null) {
            return;
        }
        if (profile.optString("cloudToken", "").length() == 0) {
            ensureCloudIdentity(showResult);
            return;
        }
        if (cloudProfileSyncing) {
            cloudProfileSyncAgain = true;
            return;
        }
        cloudProfileSyncing = true;
        cloudProfileSyncAgain = false;
        new Thread(new Runnable() {
            @Override
            public void run() {
                CloudResult result = postCloudProfile();
                final CloudResult finalResult = result;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        cloudProfileSyncing = false;
                        if (finalResult.ok && finalResult.user != null) {
                            applyCloudUser(finalResult.user);
                            try {
                                profile.put("cloudSyncStatus", "synced");
                                profile.put("cloudSyncMessage", "");
                                saveProfile();
                            } catch (JSONException ignored) {
                            }
                            if (showResult) {
                                showGlassToast("云端资料已同步", Toast.LENGTH_SHORT);
                            }
                        } else {
                            if (isCloudAuthExpired(finalResult)) {
                                handleCloudSessionExpired();
                                cloudProfileSyncAgain = false;
                                return;
                            }
                            try {
                                profile.put("cloudSyncStatus", "failed");
                                profile.put("cloudSyncMessage", finalResult.message.length() == 0 ? "云端同步失败" : finalResult.message);
                                saveProfile();
                            } catch (JSONException ignored) {
                            }
                            if (showResult) {
                                showGlassToast(isCloudAuthExpired(finalResult) ? "登录已过期，请重新登录后同步" : "云端同步失败，本地修改已保存", Toast.LENGTH_LONG);
                            }
                        }
                        if (inProfileSettingsPage) {
                            renderProfileSettingsPage();
                        } else {
                            renderCurrentProfileHeaderIfNeeded();
                        }
                        if (cloudProfileSyncAgain) {
                            syncCloudProfile(false);
                        }
                    }
                });
            }
        }).start();
    }

    private boolean isCloudAuthExpired(CloudResult result) {
        return result != null && isCloudAuthExpiredMessage(result.message);
    }

    private boolean isCloudAuthExpiredMessage(String message) {
        return message != null && (message.contains("未登录") || message.contains("登录已过期"));
    }

    private CloudResult allocateCloudIdentity() {
        try {
            JSONObject body = new JSONObject();
            body.put("installId", installId());
            body.put("nickname", profile.optString("name", "给自己起个名字"));
            return parseCloudResponse(postJson(CLOUD_API_BASE + "/api/users/allocate-id", body, ""));
        } catch (Exception e) {
            return CloudResult.fail("无法连接云端");
        }
    }

    private CloudResult postCloudProfile() {
        try {
            JSONObject body = new JSONObject();
            body.put("id", parseIntSafe(profile.optString("userId", "")));
            body.put("token", profile.optString("cloudToken", ""));
            body.put("nickname", profile.optString("name", "给自己起个名字"));
            body.put("avatarUrl", profile.optString("cloudAvatarUrl", ""));
            body.put("signature", profile.optString("signature", ""));
            body.put("gender", profile.optString("aiGender", ""));
            body.put("heightCm", profile.optInt("aiHeightCm", 0));
            body.put("weightKg", profile.optInt("aiWeightKg", 0));
            body.put("mealHabit", profile.optString("aiMealHabit", ""));
            body.put("diningMethods", normalizedDiningMethods(profile.optJSONArray("aiDiningMethods")));
            body.put("mealSpend", profile.optString("aiMealSpend", ""));
            return parseCloudResponse(postJson(CLOUD_API_BASE + "/api/users/profile", body,
                    profile.optString("cloudToken", "")));
        } catch (Exception e) {
            return CloudResult.fail("云端同步失败");
        }
    }

    private JSONObject postJson(String target, JSONObject body, String token) throws Exception {
        return postJson(target, body, token, 8000, 10000);
    }

    private JSONObject postJson(String target, JSONObject body, String token, int connectTimeoutMs, int readTimeoutMs) throws Exception {
        HttpURLConnection conn = null;
        try {
            URL url = new URL(target);
            conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setConnectTimeout(connectTimeoutMs);
            conn.setReadTimeout(readTimeoutMs);
            conn.setUseCaches(false);
            conn.setDoOutput(true);
            conn.setRequestProperty("Content-Type", "application/json; charset=UTF-8");
            if (token != null && token.length() > 0) {
                conn.setRequestProperty("Authorization", "Bearer " + token);
            }
            OutputStream out = conn.getOutputStream();
            try {
                out.write(body.toString().getBytes("UTF-8"));
            } finally {
                out.close();
            }
            int code = conn.getResponseCode();
            InputStream in = code >= 200 && code < 300 ? conn.getInputStream() : conn.getErrorStream();
            String text = in == null ? "" : readAll(in);
            if (in != null) {
                in.close();
            }
            if (text.length() == 0) {
                JSONObject empty = new JSONObject();
                empty.put("ok", code >= 200 && code < 300);
                return empty;
            }
            return new JSONObject(text);
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    private JSONObject uploadCloudBackupRaw(byte[] backup, String dataHash,
                                            String clientKnownHash) throws Exception {
        HttpURLConnection conn = null;
        try {
            conn = (HttpURLConnection) new URL(CLOUD_API_DATA_UPLOAD_RAW).openConnection();
            conn.setRequestMethod("POST");
            conn.setConnectTimeout(10000);
            conn.setReadTimeout(60000);
            conn.setUseCaches(false);
            conn.setDoOutput(true);
            conn.setFixedLengthStreamingMode(backup.length);
            conn.setRequestProperty("Content-Type", "application/octet-stream");
            conn.setRequestProperty("Authorization", "Bearer " + profile.optString("cloudToken", ""));
            conn.setRequestProperty("X-User-Id", profile.optString("userId", ""));
            conn.setRequestProperty("X-Data-Hash", dataHash == null ? "" : dataHash);
            conn.setRequestProperty("X-Client-Known-Data-Hash",
                    clientKnownHash == null ? "" : clientKnownHash);
            OutputStream out = conn.getOutputStream();
            try {
                int offset = 0;
                while (offset < backup.length) {
                    int count = Math.min(64 * 1024, backup.length - offset);
                    out.write(backup, offset, count);
                    offset += count;
                }
                out.flush();
            } finally {
                out.close();
            }
            int code = conn.getResponseCode();
            InputStream in = code >= 200 && code < 300 ? conn.getInputStream() : conn.getErrorStream();
            String text = in == null ? "" : readAll(in);
            closeQuietly(in);
            if (text.length() == 0) {
                if (code >= 200 && code < 300) {
                    return new JSONObject().put("ok", true);
                }
                return uploadCloudBackupLegacy(backup, dataHash, clientKnownHash);
            }
            JSONObject result = new JSONObject(text);
            if (!result.optBoolean("ok", false)
                    && isLegacyRawUploadFailure(code, result.optString("error", ""))) {
                return uploadCloudBackupLegacy(backup, dataHash, clientKnownHash);
            }
            return result;
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    private boolean isLegacyRawUploadFailure(int statusCode, String message) {
        String value = message == null ? "" : message.toLowerCase(Locale.US);
        return statusCode == HttpURLConnection.HTTP_NOT_FOUND
                || statusCode == HttpURLConnection.HTTP_BAD_METHOD
                || statusCode >= 500
                || value.contains("codec can't decode")
                || value.contains("unicodedecodeerror")
                || value.contains("invalid start byte");
    }

    private JSONObject uploadCloudBackupLegacy(byte[] backup, String dataHash,
                                               String clientKnownHash) throws Exception {
        JSONObject body = new JSONObject();
        body.put("id", parseIntSafe(profile.optString("userId", "")));
        body.put("token", profile.optString("cloudToken", ""));
        body.put("backupData", Base64.encodeToString(backup, Base64.NO_WRAP));
        body.put("dataHash", dataHash == null ? "" : dataHash);
        body.put("clientKnownDataHash", clientKnownHash == null ? "" : clientKnownHash);
        return postJson(CLOUD_API_BASE + "/api/users/data/upload", body,
                profile.optString("cloudToken", ""), 15000, 90000);
    }

    private JSONObject downloadCloudBackupRaw() throws Exception {
        HttpURLConnection conn = null;
        InputStream in = null;
        try {
            conn = (HttpURLConnection) new URL(CLOUD_API_DATA_DOWNLOAD_RAW).openConnection();
            conn.setRequestMethod("POST");
            conn.setConnectTimeout(10000);
            conn.setReadTimeout(90000);
            conn.setUseCaches(false);
            conn.setDoOutput(true);
            conn.setFixedLengthStreamingMode(0);
            conn.setRequestProperty("Content-Type", "application/octet-stream");
            conn.setRequestProperty("Authorization", "Bearer " + profile.optString("cloudToken", ""));
            conn.setRequestProperty("X-User-Id", profile.optString("userId", ""));
            OutputStream out = conn.getOutputStream();
            out.close();

            int code = conn.getResponseCode();
            String contentType = conn.getContentType();
            if (code == HttpURLConnection.HTTP_NO_CONTENT) {
                return new JSONObject().put("ok", true).put("hasData", false);
            }
            in = code >= 200 && code < 300 ? conn.getInputStream() : conn.getErrorStream();
            if (code >= 200 && code < 300
                    && contentType != null && contentType.toLowerCase(Locale.US).contains("application/octet-stream")) {
                restoreBackupFromStream(in, true);
                JSONObject result = new JSONObject();
                result.put("ok", true);
                result.put("hasData", true);
                result.put("dataHash", headerValue(conn, "X-Data-Hash"));
                result.put("dataUpdatedAt", headerValue(conn, "X-Data-Updated-At"));
                return result;
            }
            String text = in == null ? "" : readAll(in);
            if (text.length() == 0) {
                return new JSONObject().put("ok", false).put("error", "云端接口尚未更新");
            }
            return new JSONObject(text);
        } finally {
            closeQuietly(in);
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    private String headerValue(HttpURLConnection conn, String name) {
        String value = conn == null ? null : conn.getHeaderField(name);
        return value == null ? "" : value;
    }

    private CloudResult parseCloudResponse(JSONObject root) {
        if (root == null || !root.optBoolean("ok", false)) {
            return CloudResult.fail(root == null ? "云端返回异常" : root.optString("error", "云端返回异常"));
        }
        JSONObject user = root.optJSONObject("user");
        CloudResult result = new CloudResult();
        result.ok = true;
        result.user = user;
        result.message = root.optString("message", "");
        return result;
    }

    private CloudResult cloudCheckNickname(String nickname, int excludeId) {
        try {
            JSONObject body = new JSONObject();
            body.put("nickname", nickname);
            if (excludeId > 0) body.put("excludeId", excludeId);
            JSONObject root = postJson(CLOUD_API_CHECK_NICKNAME, body, profile.optString("cloudToken", ""));
            if (root == null || !root.optBoolean("ok", false)) {
                return CloudResult.fail(root == null ? "云端返回异常" : root.optString("error", "云端返回异常"));
            }
            if (!root.optBoolean("available", false)) {
                return CloudResult.fail(root.optString("message", "该用户名已被其他用户使用"));
            }
            CloudResult result = new CloudResult();
            result.ok = true;
            result.message = root.optString("message", "用户名可用");
            return result;
        } catch (Exception e) {
            return CloudResult.fail("无法连接云端");
        }
    }

