    private void showCloudSyncProgressDialog(String title, String message) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            final String t = title;
            final String m = message;
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    showCloudSyncProgressDialog(t, m);
                }
            });
            return;
        }
        dismissCloudSyncProgressDialog();
        cloudSyncDialog = new AlertDialog.Builder(this).create();
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(24), dp(22), dp(24), dp(22));
        box.setBackground(round(dialogSurfaceColor(), dp(28), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));

        cloudSyncTitleView = label(title, 22, Color.rgb(28, 28, 30), true);
        box.addView(cloudSyncTitleView);

        cloudSyncMessageView = label(message, 14,
                nightDecoration() ? Color.rgb(172, 176, 184) : Color.rgb(98, 102, 110), false);
        cloudSyncMessageView.setPadding(0, dp(8), 0, dp(16));
        cloudSyncMessageView.setLineSpacing(dp(2), 1.05f);
        box.addView(cloudSyncMessageView);

        LinearLayout progressRow = row(Gravity.CENTER_VERTICAL);
        cloudSyncProgressTrack = new FrameLayout(this);
        cloudSyncProgressTrack.setBackground(round(nightDecoration() ? Color.rgb(48, 50, 56) : Color.rgb(235, 239, 244),
                dp(999), 0, 0));
        cloudSyncProgressFill = new View(this);
        cloudSyncProgressFill.setBackground(round(accent, dp(999), 0, 0));
        ((FrameLayout) cloudSyncProgressTrack).addView(cloudSyncProgressFill,
                new FrameLayout.LayoutParams(0, dp(10)));
        progressRow.addView(cloudSyncProgressTrack, new LinearLayout.LayoutParams(0, dp(10), 1));
        cloudSyncPercentView = label("0%", 14, accent, true);
        cloudSyncPercentView.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        LinearLayout.LayoutParams percentLp = new LinearLayout.LayoutParams(dp(54), dp(26));
        percentLp.leftMargin = dp(12);
        progressRow.addView(cloudSyncPercentView, percentLp);
        box.addView(progressRow);

        showRoundedDialog(cloudSyncDialog, box);
        updateCloudSyncProgress(6, message);
    }

    private void updateCloudSyncProgress(final int percent, final String message) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    updateCloudSyncProgress(percent, message);
                }
            });
            return;
        }
        int value = Math.max(0, Math.min(100, percent));
        if (cloudSyncMessageView != null && message != null && message.length() > 0) {
            cloudSyncMessageView.setText(message);
        }
        if (cloudSyncPercentView != null) {
            cloudSyncPercentView.setText(value + "%");
        }
        if (cloudSyncProgressTrack != null && cloudSyncProgressFill != null) {
            int width = cloudSyncProgressTrack.getWidth();
            if (width <= 0) {
                width = Math.max(1, getResources().getDisplayMetrics().widthPixels - dp(160));
            }
            final int target = Math.round(width * (value / 100f));
            ViewGroup.LayoutParams lp = cloudSyncProgressFill.getLayoutParams();
            if (lp != null) {
                lp.width = target;
                cloudSyncProgressFill.setLayoutParams(lp);
            }
        }
    }

    private void finishCloudSyncProgress(final String message, final boolean success) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    finishCloudSyncProgress(message, success);
                }
            });
            return;
        }
        if (cloudSyncTitleView != null) {
            cloudSyncTitleView.setText(success ? "同步已完成" : "同步未完成");
        }
        updateCloudSyncProgress(success ? 100 : 100, message);
        final AlertDialog dialog = cloudSyncDialog;
        cloudSyncDialog = null;
        cloudSyncTitleView = null;
        cloudSyncMessageView = null;
        cloudSyncPercentView = null;
        cloudSyncProgressTrack = null;
        cloudSyncProgressFill = null;
        if (dialog != null && dialog.isShowing()) {
            glassToastHandler.postDelayed(new Runnable() {
                @Override
                public void run() {
                    try {
                        dialog.dismiss();
                    } catch (Exception ignored) {
                    }
                }
            }, success ? 1050L : 1500L);
        }
    }

    private void dismissCloudSyncProgressDialog() {
        if (cloudSyncDialog != null) {
            try {
                cloudSyncDialog.dismiss();
            } catch (Exception ignored) {
            }
        }
        cloudSyncDialog = null;
        cloudSyncTitleView = null;
        cloudSyncMessageView = null;
        cloudSyncPercentView = null;
        cloudSyncProgressTrack = null;
        cloudSyncProgressFill = null;
    }

    private void maybeAutoCloudSync(boolean force) {
        if (!autoCloudSyncEnabled() || !hasCloudIdentity() || cloudDataSyncing) {
            return;
        }
        long now = System.currentTimeMillis();
        long last = profile.optLong("lastAutoCloudSyncAt", 0);
        if (!force && now - last < 30L * 60L * 1000L) {
            return;
        }
        try {
            profile.put("lastAutoCloudSyncAt", now);
            saveProfile();
        } catch (JSONException ignored) {
        }
        syncCloudDataUpload(false);
    }

    private void syncCloudDataUpload(final boolean showResult) {
        if (!hasCloudIdentity()) {
            showSimpleInfoDialog("需要登录", "请先在个人信息里登录或创建账号，再同步云端数据。");
            return;
        }
        if (cloudDataSyncing) {
            showGlassToast("正在同步云端数据...", Toast.LENGTH_SHORT);
            return;
        }
        cloudDataSyncing = true;
        if (showResult) {
            showCloudSyncProgressDialog("同步到云端", "正在整理本机记录...");
        }
        new Thread(new Runnable() {
            @Override
            public void run() {
                String message = "云端同步失败";
                boolean ok = false;
                boolean authExpired = false;
                boolean skipped = false;
                boolean staleCloud = false;
                try {
                    if (showResult) updateCloudSyncProgress(18, "正在打包本机数据...");
                    byte[] backup = buildBackupBytes(true);
                    String backupHash = sha256Hex(backup);
                    String knownCloudHash = profile.optString("cloudDataHash", "");
                    if (backupHash.equals(knownCloudHash)) {
                        ok = true;
                        skipped = true;
                        message = "本机数据已经是最新，不需要重复上传";
                    } else {
                        if (showResult) updateCloudSyncProgress(58, "正在流式上传新增内容...");
                        JSONObject root = uploadCloudBackupRaw(backup, backupHash, knownCloudHash);
                        ok = root.optBoolean("ok", false);
                        message = ok ? root.optString("message", "数据已同步到云端")
                                : root.optString("error", "云端同步失败");
                        authExpired = !ok && isCloudAuthExpiredMessage(message);
                        staleCloud = !ok && message.contains("云端已有其他设备的新数据");
                        if (ok) {
                            try {
                                profile.put("cloudDataUpdatedAt", root.optString("dataUpdatedAt", ""));
                                profile.put("cloudDataHash", root.optString("dataHash", backupHash));
                                profile.put("lastCloudBackupHash", root.optString("dataHash", backupHash));
                                profile.put("cloudSyncStatus", "synced");
                                profile.put("cloudSyncMessage", "");
                                saveProfile();
                            } catch (JSONException ignored) {
                            }
                        }
                    }
                    if (skipped) {
                        try {
                            profile.put("lastCloudBackupHash", backupHash);
                            profile.put("cloudSyncStatus", "synced");
                            profile.put("cloudSyncMessage", "");
                            saveProfile();
                        } catch (JSONException ignored) {
                        }
                    }
                } catch (OutOfMemoryError error) {
                    releaseThumbnailMemory();
                    message = "本机数据较大，暂时无法整理，请清理无用图片后重试";
                } catch (Exception e) {
                    message = e.getMessage() != null && e.getMessage().contains("服务器")
                            ? e.getMessage() : "无法连接云端";
                }
                final boolean done = ok;
                final boolean expired = authExpired;
                final boolean conflict = staleCloud;
                final String toast = message;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        cloudDataSyncing = false;
                        if (expired) {
                            handleCloudSessionExpired();
                            return;
                        }
                        if (inCloudSyncPage) {
                            renderCloudSyncPage();
                        } else if (inDataSecurityPage) {
                            renderDataSecurityPage();
                        }
                        if (showResult) {
                            finishCloudSyncProgress(toast, done);
                        } else if (conflict) {
                            showGlassToast(toast, Toast.LENGTH_LONG);
                        } else if (!done) {
                            Log.w(LOG_TAG, "Background cloud sync failed: " + toast);
                        }
                    }
                });
            }
        }).start();
    }

