    private void syncCloudDataDownload(final boolean showResult) {
        if (!hasCloudIdentity()) {
            if (showResult) {
                showSimpleInfoDialog("需要登录", "请先在个人信息里登录或创建账号，再从云端同步数据。");
            }
            return;
        }
        if (cloudDataSyncing) {
            if (showResult) showGlassToast("正在同步云端数据...", Toast.LENGTH_SHORT);
            return;
        }
        cloudDataSyncing = true;
        if (showResult) {
            showCloudSyncProgressDialog("同步到本地", "正在读取云端数据...");
        }
        new Thread(new Runnable() {
            @Override
            public void run() {
                String message = "云端暂时没有可同步的数据";
                boolean ok = false;
                boolean hasData = false;
                boolean authExpired = false;
                try {
                    if (showResult) updateCloudSyncProgress(22, "正在连接云端...");
                    JSONObject root = downloadCloudBackupRaw();
                    if (!root.optBoolean("ok", false)) {
                        message = root.optString("error", "云端同步失败");
                        authExpired = isCloudAuthExpiredMessage(message);
                    } else if (!root.optBoolean("hasData", false)) {
                        message = "云端暂时没有可同步的数据";
                        ok = true;
                    } else {
                        if (showResult) updateCloudSyncProgress(78, "正在写入本机...");
                        try {
                            profile.put("cloudDataUpdatedAt", root.optString("dataUpdatedAt", ""));
                            profile.put("cloudDataHash", root.optString("dataHash", ""));
                            if (root.optString("dataHash", "").length() > 0) {
                                profile.put("lastCloudBackupHash", root.optString("dataHash", ""));
                            }
                            saveProfile();
                        } catch (JSONException ignored) {
                        }
                        ok = true;
                        hasData = true;
                        message = "云端数据已同步到本机";
                    }
                } catch (OutOfMemoryError error) {
                    releaseThumbnailMemory();
                    message = "云端数据较大，内存不足，请稍后重试";
                } catch (Exception e) {
                    message = e.getMessage() != null && e.getMessage().contains("服务器")
                            ? e.getMessage() : "云端同步失败，请稍后再试";
                }
                final boolean done = ok;
                final boolean downloaded = hasData;
                final boolean expired = authExpired;
                final String toast = message;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        cloudDataSyncing = false;
                        if (expired) {
                            handleCloudSessionExpired();
                            return;
                        }
                        if (downloaded) {
                            updateSystemBars();
                            refreshChrome();
                            updateNav(false);
                            renderCurrent();
                        } else if (inCloudSyncPage) {
                            renderCloudSyncPage();
                        } else if (inDataSecurityPage) {
                            renderDataSecurityPage();
                        }
                        if (showResult || !done) {
                            if (showResult) {
                                finishCloudSyncProgress(toast, done);
                            } else {
                                showGlassToast(toast, done ? Toast.LENGTH_SHORT : Toast.LENGTH_LONG);
                            }
                        }
                    }
                });
            }
        }).start();
    }

    private void cloudLogin(final String account, final String password, final Runnable onSuccess) {
        if (cloudLoginRequesting) return;
        cloudLoginRequesting = true;
        new Thread(new Runnable() {
            @Override
            public void run() {
                final CloudResult result = cloudLoginSync(account, password);
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        cloudLoginRequesting = false;
                        if (result.ok && result.user != null) {
                            applyCloudUser(result.user);
                            saveProfile();
                            closeActiveOverlay(false);
                            renderCurrent();
                            showGlassToast("登录成功，欢迎 " + result.user.optString("nickname", ""), Toast.LENGTH_SHORT);
                            syncCloudDataDownload(false);
                            if (onSuccess != null) onSuccess.run();
                        } else {
                            showGlassToast(result.message, Toast.LENGTH_LONG);
                        }
                    }
                });
            }
        }).start();
    }

    private CloudResult cloudLoginSync(String account, String password) {
        try {
            JSONObject body = new JSONObject();
            body.put("account", account);
            body.put("password", password);
            body.put("installId", installId());
            return parseCloudResponse(postJson(CLOUD_API_LOGIN, body, ""));
        } catch (Exception e) {
            return CloudResult.fail("无法连接云端");
        }
    }

    private void applyCloudUser(JSONObject user) {
        if (user == null || profile == null) {
            return;
        }
        try {
            int id = user.optInt("id", 0);
            if (id > 0) {
                profile.put("userId", String.valueOf(id));
                profile.put("userIdSource", "cloud");
            }
            String token = user.optString("token", "");
            if (token.length() > 0) {
                profile.put("cloudToken", token);
            }
            String nickname = user.optString("nickname", "");
            if (nickname.length() > 0) {
                profile.put("name", nickname);
            }
            profile.put("signature", user.optString("signature", profile.optString("signature", "")));
            profile.put("aiGender", user.optString("gender", profile.optString("aiGender", "")));
            profile.put("aiHeightCm", user.optInt("heightCm", profile.optInt("aiHeightCm", 0)));
            profile.put("aiWeightKg", user.optInt("weightKg", profile.optInt("aiWeightKg", 0)));
            profile.put("aiMealHabit", user.optString("mealHabit", profile.optString("aiMealHabit", "")));
            JSONArray diningMethods = user.optJSONArray("diningMethods");
            if (diningMethods != null) {
                profile.put("aiDiningMethods", normalizedDiningMethods(diningMethods));
            }
            profile.put("aiMealSpend", user.optString("mealSpend", profile.optString("aiMealSpend", "")));
            profile.put("cloudWechatBound", user.optBoolean("wechatBound", false));
            profile.put("cloudHasPassword", user.optBoolean("hasPassword", false));
            profile.put("cloudCreatedAt", user.optString("createdAt", profile.optString("cloudCreatedAt", "")));
            profile.put("cloudUpdatedAt", user.optString("updatedAt", ""));
            profile.put("cloudDataUpdatedAt", user.optString("cloudDataUpdatedAt", profile.optString("cloudDataUpdatedAt", "")));
            profile.put("cloudDataHash", user.optString("cloudDataHash", profile.optString("cloudDataHash", "")));
            profile.put("cloudSyncStatus", "synced");
            profile.put("cloudSyncMessage", "");
        } catch (JSONException ignored) {
        }
    }

