    private JSONObject ensureDay(String date) {
        JSONObject day = optObj(days, date);
        try {
            if (!days.has(date)) {
                days.put(date, day);
            }
            for (MealOption meal : allMealOptions()) {
                if (!day.has(meal.key)) {
                    day.put(meal.key, new JSONObject());
                }
            }
        } catch (JSONException ignored) {
        }
        return day;
    }

    private JSONObject optObj(JSONObject parent, String key) {
        JSONObject child = parent.optJSONObject(key);
        if (child == null) {
            child = new JSONObject();
            try {
                parent.put(key, child);
            } catch (JSONException ignored) {
            }
        }
        return child;
    }

    private void setMealText(String date, String mealKey, String text) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        try {
            if (text.trim().length() > 0) {
                meal.put("text", text);
                meal.remove("skipped");
            } else {
                meal.remove("text");
            }
            if (text.trim().length() > 0) {
                meal.put("time", nowTime());
            } else {
                meal.remove("time");
            }
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private boolean toggleMealSkipped(String date, String mealKey) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        try {
            if (meal.optBoolean("skipped", false)) {
                meal.remove("skipped");
                meal.remove("emoji");
                if (meal.optString("text", "").trim().length() == 0) {
                    meal.remove("time");
                }
                saveDays();
                return false;
            } else {
                meal.put("skipped", true);
                meal.put("emoji", "🍽");
                meal.remove("time");
                meal.remove("text");
                saveDays();
                return true;
            }
        } catch (JSONException ignored) {
        }
        return meal.optBoolean("skipped", false);
    }

    private String skippedReminder(String date, String mealKey, String title) {
        int count = consecutiveSkippedDays(date, mealKey);
        String message;
        if (count >= 4) {
            message = pickReminder(skipReminderList("many"), date, mealKey, title);
        } else if (count == 3) {
            message = pickReminder(skipReminderList("three"), date, mealKey, title);
        } else if (count == 2) {
            message = pickReminder(skipReminderList("two"), date, mealKey, title);
        } else {
            message = pickReminder(skipReminderList("one"), date, mealKey, title);
        }
        return softBreakReminder(message);
    }

    private String pickReminder(List<String> pool, String date, String mealKey, String title) {
        if (pool.isEmpty()) {
            return title + "缺席啦，下一次把它好好补回来(๑•̀ㅂ•́)و✧";
        }
        int seed = Math.abs((date + mealKey + title + hintSeed).hashCode());
        return formatReminderTemplate(pool.get(seed % pool.size()), title);
    }

    private String formatReminderTemplate(String template, String title) {
        if (template == null || template.length() == 0) {
            return title + "缺席啦，下一次把它好好补回来(๑•̀ㅂ•́)و✧";
        }
        if (template.indexOf("%s") >= 0) {
            try {
                return String.format(Locale.CHINA, template, title);
            } catch (Exception ignored) {
                return template.replace("%s", title);
            }
        }
        return template;
    }

    private String softBreakReminder(String message) {
        if (message.length() <= 18) {
            return message;
        }
        int comma = message.indexOf('，');
        if (comma > 5 && comma < message.length() - 4) {
            return message.substring(0, comma + 1) + "\n" + message.substring(comma + 1);
        }
        int bang = message.indexOf('！');
        if (bang > 5 && bang < message.length() - 4) {
            return message.substring(0, bang + 1) + "\n" + message.substring(bang + 1);
        }
        return message;
    }

    private int consecutiveSkippedDays(String date, String mealKey) {
        Calendar cursor = calendarFromKey(date);
        int count = 0;
        for (int i = 0; i < 30; i++) {
            if (!isMealSkipped(dateKey(cursor), mealKey)) {
                break;
            }
            count++;
            cursor.add(Calendar.DAY_OF_MONTH, -1);
        }
        return count;
    }

    private boolean isMealSkipped(String date, String mealKey) {
        JSONObject day = days.optJSONObject(date);
        if (day == null) {
            return false;
        }
        JSONObject meal = day.optJSONObject(mealKey);
        return meal != null && meal.optBoolean("skipped", false);
    }

    private void setMealSkipped(String date, String mealKey) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        try {
            meal.put("skipped", true);
            meal.put("emoji", "🍽");
            meal.remove("time");
            meal.remove("text");
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private void setMealEmoji(String date, String mealKey, String emoji) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        try {
            meal.put("emoji", emoji);
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private void setMood(String date, String emoji) {
        JSONObject day = ensureDay(date);
        try {
            JSONArray moods = moodsArray(day);
            JSONArray next = new JSONArray();
            for (int i = 0; i < moods.length(); i++) {
                String old = moods.optString(i);
                if (old.length() > 0 && !emoji.equals(old)) {
                    next.put(old);
                }
            }
            next.put(emoji);
            while (next.length() > 2) {
                JSONArray trimmed = new JSONArray();
                for (int i = 1; i < next.length(); i++) {
                    trimmed.put(next.optString(i));
                }
                next = trimmed;
            }
            day.put("moods", next);
            day.put("mood", next.optString(0, ""));
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private void removeMood(String date, int index) {
        JSONObject day = ensureDay(date);
        JSONArray moods = moodsArray(day);
        JSONArray next = new JSONArray();
        for (int i = 0; i < moods.length(); i++) {
            if (i != index && moods.optString(i).length() > 0) {
                next.put(moods.optString(i));
            }
        }
        try {
            if (next.length() > 0) {
                day.put("moods", next);
                day.put("mood", next.optString(0, ""));
            } else {
                day.remove("moods");
                day.remove("mood");
            }
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private TextView calendarDiningChip(String text, boolean selected) {
        TextView chip = label(text, 13, selected ? Color.WHITE : Color.rgb(92, 96, 104), true);
        chip.setGravity(Gravity.CENTER);
        chip.setSingleLine(true);
        styleCalendarDiningChip(chip, selected);
        attachPressAnimation(chip);
        return chip;
    }

    private void styleCalendarDiningChip(TextView chip, boolean selected) {
        chip.setTextColor(selected ? Color.WHITE : Color.rgb(92, 96, 104));
        chip.setBackground(round(selected ? accent : Color.rgb(246, 248, 250),
                dp(14), selected ? 0 : surfaceStrokeColor(), dp(1)));
    }

    private void toggleDayDiningMethod(String date, String method) {
        JSONObject day = ensureDay(date);
        JSONArray arr = copyStringArray(day.optJSONArray("diningMethods"));
        toggleStringInArray(arr, method);
        try {
            if (arr.length() > 0) {
                day.put("diningMethods", arr);
            } else {
                day.remove("diningMethods");
            }
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private void toggleMealDiningMethod(String date, String mealKey, String method) {
        JSONObject day = ensureDay(date);
        JSONObject byMeal = day.optJSONObject("mealDiningMethods");
        boolean hadStructured = byMeal != null && byMeal.length() > 0;
        if (byMeal == null) {
            byMeal = new JSONObject();
            try {
                day.put("mealDiningMethods", byMeal);
            } catch (JSONException ignored) {
            }
        }
        JSONArray arr = byMeal.optJSONArray(mealKey);
        if (arr == null && !hadStructured && mealKey.equals(defaultDiningMealKey(date))) {
            arr = day.optJSONArray("diningMethods");
        }
        arr = copyStringArray(arr);
        toggleStringInArray(arr, method);
        try {
            if (arr.length() > 0) {
                byMeal.put(mealKey, arr);
            } else {
                byMeal.remove(mealKey);
            }
            day.remove("diningMethods");
            if (byMeal.length() == 0) {
                day.remove("mealDiningMethods");
            }
            saveDays();
        } catch (JSONException ignored) {
        }
    }

    private List<String> dayDiningMethods(String date) {
        JSONObject day = optObj(days, date);
        JSONArray arr = day.optJSONArray("diningMethods");
        List<String> result = new ArrayList<String>();
        if (arr == null) {
            return result;
        }
        for (int i = 0; i < arr.length(); i++) {
            String value = arr.optString(i);
            if (value.length() > 0) {
                result.add(value);
            }
        }
        return result;
    }

    private List<String> mealDiningMethods(String date, String mealKey) {
        JSONObject day = optObj(days, date);
        List<String> result = mealDiningMethodsRaw(day, mealKey);
        if (!result.isEmpty()) {
            return result;
        }
        JSONObject byMeal = day.optJSONObject("mealDiningMethods");
        if ((byMeal == null || byMeal.length() == 0) && mealKey.equals(defaultDiningMealKey(date))) {
            return dayDiningMethods(date);
        }
        return result;
    }

    private List<String> mealDiningMethodsRaw(JSONObject day, String mealKey) {
        List<String> result = new ArrayList<String>();
        JSONObject byMeal = day.optJSONObject("mealDiningMethods");
        JSONArray arr = byMeal == null ? null : byMeal.optJSONArray(mealKey);
        if (arr == null) {
            return result;
        }
        for (int i = 0; i < arr.length(); i++) {
            String value = arr.optString(i);
            if (value.length() > 0) {
                result.add(value);
            }
        }
        return result;
    }

    private String mealDiningText(String date, String mealKey) {
        List<String> methods = mealDiningMethods(date, mealKey);
        return joinStringList(methods, "、");
    }

    private String joinStringList(List<String> values, String separator) {
        StringBuilder sb = new StringBuilder();
        if (values == null) {
            return "";
        }
        for (String method : values) {
            if (sb.length() > 0) {
                sb.append(separator);
            }
            sb.append(method);
        }
        return sb.toString();
    }

    private String dayDiningMethodsText(String date) {
        StringBuilder sb = new StringBuilder();
        for (MealOption meal : visibleMealsForDate(date)) {
            String methods = mealDiningText(date, meal.key);
            if (methods.length() == 0) {
                continue;
            }
            if (sb.length() > 0) {
                sb.append("  ");
            }
            sb.append(meal.title).append("：").append(methods);
        }
        return sb.toString();
    }

    private String firstDayDiningMethodText(String date) {
        for (MealOption meal : visibleMealsForDate(date)) {
            List<String> methods = mealDiningMethods(date, meal.key);
            if (!methods.isEmpty()) {
                return methods.get(0);
            }
        }
        return "";
    }

    private String defaultDiningMealKey(String date) {
        JSONObject day = optObj(days, date);
        List<MealOption> meals = visibleMealsForDate(date);
        for (MealOption meal : meals) {
            if (!mealDiningMethodsRaw(day, meal.key).isEmpty()) {
                return meal.key;
            }
        }
        for (MealOption meal : meals) {
            if (mealHasRecord(day, meal.key)) {
                return meal.key;
            }
        }
        return meals.isEmpty() ? "breakfast" : meals.get(0).key;
    }

    private boolean mealHasRecord(JSONObject day, String mealKey) {
        JSONObject meal = day.optJSONObject(mealKey);
        if (meal == null) {
            return false;
        }
        JSONArray photos = meal.optJSONArray("photos");
        JSONArray stickers = meal.optJSONArray("stickers");
        return meal.optString("text", "").trim().length() > 0
                || meal.optBoolean("skipped", false)
                || (photos != null && photos.length() > 0)
                || (stickers != null && stickers.length() > 0);
    }

    private JSONArray moodsArray(JSONObject day) {
        JSONArray moods = day.optJSONArray("moods");
        if (moods != null) {
            return moods;
        }
        moods = new JSONArray();
        String old = day.optString("mood", "");
        if (old.length() > 0) {
            moods.put(old);
        }
        return moods;
    }

    private String[] moodEmojis(String date) {
        JSONObject day = optObj(days, date);
        JSONArray moods = moodsArray(day);
        List<String> result = new ArrayList<String>();
        for (int i = 0; i < moods.length() && result.size() < 2; i++) {
            String mood = moods.optString(i);
            if (mood.length() > 0) {
                result.add(mood);
            }
        }
        return result.toArray(new String[result.size()]);
    }

    private String moodText(String date) {
        String[] moods = moodEmojis(date);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < moods.length; i++) {
            if (i > 0) {
                sb.append(" ");
            }
            sb.append(moods[i]);
        }
        return sb.toString();
    }

    private List<String> recordedDates() {
        List<String> dates = new ArrayList<String>();
        JSONArray names = days.names();
        if (names == null) {
            return dates;
        }
        for (int i = 0; i < names.length(); i++) {
            String date = names.optString(i);
            JSONObject day = days.optJSONObject(date);
            String mood = day == null ? "" : moodText(date);
            String dining = day == null ? "" : dayDiningMethodsText(date);
            if (mealCount(date) > 0 || mood.length() > 0 || dining.length() > 0) {
                dates.add(date);
            }
        }
        Collections.sort(dates, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return b.compareTo(a);
            }
        });
        return dates;
    }

    private int mealCount(String date) {
        JSONObject day = optObj(days, date);
        int count = 0;
        for (MealOption meal : allMealOptions()) {
            JSONObject mealObj = optObj(day, meal.key);
            JSONArray photos = mealObj.optJSONArray("photos");
            JSONArray stickers = mealObj.optJSONArray("stickers");
            if (mealObj.optString("text", "").trim().length() > 0
                    || (photos != null && photos.length() > 0)
                    || (stickers != null && stickers.length() > 0)
                    || mealObj.optBoolean("skipped", false)) {
                count++;
            }
        }
        return count;
    }

    private String daySummary(String date) {
        JSONObject day = optObj(days, date);
        List<String> parts = new ArrayList<String>();
        for (MealOption meal : allMealOptions()) {
            JSONObject mealObj = optObj(day, meal.key);
            String text = mealObj.optString("text", "").trim();
            JSONArray photos = mealObj.optJSONArray("photos");
            JSONArray stickers = mealObj.optJSONArray("stickers");
            String methods = mealDiningText(date, meal.key);
            String title = meal.title + (methods.length() > 0 ? " · " + methods : "");
            if (mealObj.optBoolean("skipped", false)) {
                continue;
            } else if (text.length() > 0 || (photos != null && photos.length() > 0)
                    || (stickers != null && stickers.length() > 0)) {
                parts.add(title + "：" + (text.length() > 0 ? text
                        : ((stickers != null && stickers.length() > 0) ? "有美食贴纸" : "有图片记录")));
            } else if (methods.length() > 0) {
                parts.add(title);
            }
        }
        if (parts.isEmpty()) {
            if (date.compareTo(dateKey(Calendar.getInstance())) > 0) {
                return "还木有到这一天";
            }
            return "什么都没有哦，是不是漏了什么？";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < parts.size(); i++) {
            if (i > 0) {
                sb.append("  ");
            }
            sb.append(parts.get(i));
        }
        return sb.toString();
    }

    private String dayEmoji(String date) {
        JSONObject day = optObj(days, date);
        String mood = moodText(date);
        if (mood.length() > 0) {
            return mood;
        }
        for (MealOption meal : allMealOptions()) {
            JSONObject mealObj = optObj(day, meal.key);
            if (mealObj.optBoolean("skipped", false)) {
                continue;
            }
            String emoji = mealObj.optString("emoji", "");
            if (emoji.length() > 0) {
                return emoji;
            }
        }
        return "😀";
    }

    private String primaryDayEmoji(String date) {
        String[] moods = moodEmojis(date);
        if (moods.length > 0) {
            return moods[0];
        }
        JSONObject day = optObj(days, date);
        for (MealOption meal : allMealOptions()) {
            JSONObject mealObj = optObj(day, meal.key);
            if (mealObj.optBoolean("skipped", false)) {
                continue;
            }
            String emoji = mealObj.optString("emoji", "");
            if (emoji.length() > 0) {
                return emoji;
            }
        }
        return "😀";
    }

    private String dateKey(Calendar cal) {
        return String.format(Locale.CHINA, "%04d-%02d-%02d",
                cal.get(Calendar.YEAR), cal.get(Calendar.MONTH) + 1, cal.get(Calendar.DAY_OF_MONTH));
    }

    private String nowTime() {
        return new SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.CHINA).format(new Date());
    }

    private String displayDate(String key) {
        try {
            Date date = new SimpleDateFormat("yyyy-MM-dd", Locale.CHINA).parse(key);
            return new SimpleDateFormat("yyyy年MM月dd日", Locale.CHINA).format(date);
        } catch (ParseException e) {
            return key;
        }
    }

    private String displayMonthDay(String key) {
        try {
            Calendar cal = calendarFromKey(key);
            return String.format(Locale.CHINA, "%d月%d日",
                    cal.get(Calendar.MONTH) + 1, cal.get(Calendar.DAY_OF_MONTH));
        } catch (Exception e) {
            return key;
        }
    }

    private String displayNotebookDate(String key) {
        try {
            Calendar cal = calendarFromKey(key);
            return String.format(Locale.CHINA, "%d 年 %d 月 %d 日",
                    cal.get(Calendar.YEAR), cal.get(Calendar.MONTH) + 1, cal.get(Calendar.DAY_OF_MONTH));
        } catch (Exception e) {
            return key;
        }
    }

    private String displayDateWithWeek(String key) {
        try {
            Date date = new SimpleDateFormat("yyyy-MM-dd", Locale.CHINA).parse(key);
            return new SimpleDateFormat("yyyy年MM月dd日 E", Locale.CHINA).format(date);
        } catch (ParseException e) {
            return key;
        }
    }

    private String formatHeaderDate(Calendar cal) {
        return new SimpleDateFormat("MM月dd日 E", Locale.CHINA).format(cal.getTime());
    }

    private String formatHeaderWeek(Calendar cal) {
        return new SimpleDateFormat("E", Locale.CHINA).format(cal.getTime());
    }

    private LinearLayout basePage() {
        LinearLayout page = new LinearLayout(this);
        disableForceDark(page);
        page.setOrientation(LinearLayout.VERTICAL);
        page.setClipToPadding(false);
        page.setPadding(dp(spaceByLayout(22, 20, 18)), dp(spaceByLayout(52, 48, 44)), dp(spaceByLayout(22, 20, 18)), 0);
        return page;
    }

    private ScrollView pageScroll() {
        ElasticScrollView scroll = new ElasticScrollView(this);
        disableForceDark(scroll);
        scroll.setFillViewport(false);
        scroll.setClipToPadding(false);
        scroll.setOverScrollMode(View.OVER_SCROLL_NEVER);
        if (Build.VERSION.SDK_INT >= 21) {
            scroll.setNestedScrollingEnabled(false);
        }
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setHorizontalScrollBarEnabled(false);
        return scroll;
    }

    private StickyGlassHeader installStickyHeader(FrameLayout host, ScrollView scroll,
                                                    LinearLayout page, View header) {
        if (host == null || scroll == null || page == null || header == null) {
            return null;
        }
        int height = dp(spaceByLayout(112, 106, 102));
        page.addView(space(dp(spaceByLayout(60, 56, 52))), 0);
        StickyGlassHeader glass = new StickyGlassHeader(this);
        activeStickyHeader = glass;
        glass.setSource(scroll, false);
        FrameLayout headerHost = new FrameLayout(this);
        headerHost.setPadding(dp(spaceByLayout(22, 20, 18)), dp(spaceByLayout(50, 47, 44)),
                dp(spaceByLayout(22, 20, 18)), dp(4));
        resetSystemTypefaceRecursive(header);
        headerHost.addView(header, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        glass.addView(headerHost, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        host.addView(glass, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, height, Gravity.TOP));
        glass.bringToFront();
        return glass;
    }

    private StickyGlassHeader installStickyHeader(FrameLayout host, View source,
                                                    View header, boolean continuous) {
        if (host == null || source == null || header == null) {
            return null;
        }
        int height = dp(spaceByLayout(112, 106, 102));
        StickyGlassHeader glass = new StickyGlassHeader(this);
        activeStickyHeader = glass;
        glass.setSource(source, continuous);
        FrameLayout headerHost = new FrameLayout(this);
        headerHost.setPadding(dp(spaceByLayout(22, 20, 18)), dp(spaceByLayout(50, 47, 44)),
                dp(spaceByLayout(22, 20, 18)), dp(4));
        resetSystemTypefaceRecursive(header);
        headerHost.addView(header, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        glass.addView(headerHost, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        host.addView(glass, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, height, Gravity.TOP));
        glass.bringToFront();
        return glass;
    }

    private StickyGlassHeader installStickyHeader(ScrollView scroll, LinearLayout page, View header) {
        if (scroll == null || page == null || header == null) {
            return null;
        }
        android.view.ViewParent parent = scroll.getParent();
        if (!(parent instanceof ViewGroup)) {
            page.addView(header);
            return null;
        }
        ViewGroup outer = (ViewGroup) parent;
        int index = outer.indexOfChild(scroll);
        ViewGroup.LayoutParams outerLp = scroll.getLayoutParams();
        outer.removeView(scroll);
        FrameLayout host = new FrameLayout(this);
        disableForceDark(host);
        if (outerLp == null) {
            outerLp = new ViewGroup.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);
        }
        outer.addView(host, Math.max(0, index), outerLp);
        host.addView(scroll, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        return installStickyHeader(host, scroll, page, header);
    }

    private int currentContentScrollY() {
        ScrollView scroll = currentPageScroll();
        return scroll == null ? 0 : scroll.getScrollY();
    }

    private void restoreScrollPosition(final ScrollView scroll, final int scrollY) {
        if (scroll == null || scrollY <= 0) {
            return;
        }
        scroll.post(new Runnable() {
            @Override
            public void run() {
                scroll.scrollTo(0, scrollY);
            }
        });
    }

    private ScrollView currentPageScroll() {
        if (content == null || content.getChildCount() == 0) {
            return null;
        }
        return findFirstScrollView(content.getChildAt(0));
    }

    private ScrollView findFirstScrollView(View view) {
        if (view instanceof ScrollView) {
            return (ScrollView) view;
        }
        if (!(view instanceof ViewGroup)) {
            return null;
        }
        ViewGroup group = (ViewGroup) view;
        for (int i = 0; i < group.getChildCount(); i++) {
            ScrollView found = findFirstScrollView(group.getChildAt(i));
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private void rerenderPreservingScroll(Runnable renderAction) {
        if (renderAction == null) {
            return;
        }
        final int scrollY = currentContentScrollY();
        boolean wasSuppressing = suppressEntryAnimation;
        suppressEntryAnimation = true;
        try {
            renderAction.run();
        } finally {
            suppressEntryAnimation = wasSuppressing;
        }
        restoreScrollPosition(currentPageScroll(), scrollY);
    }

    private void animateIn(final LinearLayout page) {
        if (suppressEntryAnimation) {
            return;
        }
        page.post(new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < page.getChildCount(); i++) {
                    View child = page.getChildAt(i);
                    if (child instanceof Space) {
                        continue;
                    }
                    child.setAlpha(0.97f);
                    child.setTranslationY(dp(6));
                    child.animate()
                            .alpha(1f)
                            .translationY(0f)
                            .setStartDelay(i * 16L)
                            .setDuration(300)
                            .start();
                }
            }
        });
    }

    private void attachPressAnimation(final View view) {
        view.setOnTouchListener(new View.OnTouchListener() {
            @Override
            public boolean onTouch(View v, MotionEvent event) {
                if (!v.isEnabled()) {
                    return false;
                }
                if (event.getAction() == MotionEvent.ACTION_DOWN) {
                    v.animate().scaleX(0.985f).scaleY(0.985f).setDuration(115).start();
                } else if (event.getAction() == MotionEvent.ACTION_UP
                        || event.getAction() == MotionEvent.ACTION_CANCEL) {
                    v.animate().scaleX(1f).scaleY(1f).setDuration(205).start();
                }
                return false;
            }
        });
    }

    private TextView dialogButton(String text, int bg, int color) {
        TextView button = label(text, 15, color, true);
        button.setGravity(Gravity.CENTER);
        button.setBackground(round(bg, dp(18), 0, 0));
        attachPressAnimation(button);
        return button;
    }

    private void showGlassToast(final String message, final int duration) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    showGlassToast(message, duration);
                }
            });
            return;
        }
        if (message == null || message.length() == 0 || root == null) {
            return;
        }
        glassToastHandler.removeCallbacksAndMessages(null);
        if (glassToastView != null && glassToastView.getParent() == root) {
            root.removeView(glassToastView);
        }

        final TextView toast = label(message, 16, nightDecoration() ? Color.rgb(245, 247, 250) : Color.rgb(34, 35, 38), true);
        toast.setGravity(Gravity.CENTER);
        toast.setMaxWidth((int) (getResources().getDisplayMetrics().widthPixels * 0.78f));
        toast.setMinHeight(dp(54));
        toast.setPadding(dp(24), dp(14), dp(24), dp(14));
        toast.setLineSpacing(dp(2), 1.04f);
        toast.setBackground(glassToastBackground());
        toast.setElevation(dp(18));
        toast.setClickable(false);
        glassToastView = toast;

        FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT,
                ViewGroup.LayoutParams.WRAP_CONTENT);
        lp.gravity = Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL;
        lp.bottomMargin = dp(112);
        root.addView(toast, lp);
        toast.setAlpha(0f);
        toast.setScaleX(0.96f);
        toast.setScaleY(0.96f);
        toast.setTranslationY(dp(10));
        toast.animate()
                .alpha(1f)
                .scaleX(1f)
                .scaleY(1f)
                .translationY(0f)
                .setDuration(190)
                .setInterpolator(new android.view.animation.DecelerateInterpolator(1.6f))
                .start();

        long delay = duration == Toast.LENGTH_LONG ? 3200L : 1900L;
        glassToastHandler.postDelayed(new Runnable() {
            @Override
            public void run() {
                hideGlassToast(toast);
            }
        }, delay);
    }

    private Drawable glassToastBackground() {
        int fill = nightDecoration() ? Color.argb(218, 35, 37, 42) : Color.argb(224, 255, 255, 255);
        int top = nightDecoration() ? Color.argb(232, 50, 52, 58) : Color.argb(236, 255, 255, 255);
        int stroke = nightDecoration() ? Color.argb(108, 255, 255, 255) : Color.argb(152, 255, 255, 255);
        GradientDrawable d = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{top, fill});
        d.setCornerRadius(dp(20));
        d.setStroke(dp(1), stroke);
        return d;
    }

    private void hideGlassToast(final View toast) {
        if (toast == null || toast.getParent() == null) {
            return;
        }
        toast.animate()
                .alpha(0f)
                .scaleX(0.96f)
                .scaleY(0.96f)
                .translationY(dp(8))
                .setDuration(180)
                .withEndAction(new Runnable() {
                    @Override
                    public void run() {
                        ViewParent parent = toast.getParent();
                        if (parent instanceof ViewGroup) {
                            ((ViewGroup) parent).removeView(toast);
                        }
                        if (glassToastView == toast) {
                            glassToastView = null;
                        }
                    }
                })
                .start();
    }

    private void showRoundedDialog(AlertDialog dialog, View contentView) {
        activeGlassDialogCount++;
        applyDialogBackgroundBlur();
        dialog.setOnDismissListener(new android.content.DialogInterface.OnDismissListener() {
            @Override
            public void onDismiss(android.content.DialogInterface dismissed) {
                activeGlassDialogCount = Math.max(0, activeGlassDialogCount - 1);
                if (activeGlassDialogCount == 0) {
                    clearDialogBackgroundBlur();
                }
            }
        });
        dialog.show();
        Window dialogWindow = dialog.getWindow();
        if (dialogWindow != null) {
            dialogWindow.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            dialogWindow.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);
            WindowManager.LayoutParams attributes = dialogWindow.getAttributes();
            attributes.dimAmount = nightDecoration() ? 0.10f : 0.07f;
            if (Build.VERSION.SDK_INT >= 31) {
                attributes.setBlurBehindRadius(dp(12));
                dialogWindow.addFlags(WindowManager.LayoutParams.FLAG_BLUR_BEHIND);
            }
            dialogWindow.setAttributes(attributes);
        }
        dialog.setContentView(contentView);
        if (dialogWindow != null) {
            dialogWindow.clearFlags(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
                    | WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM);
            dialogWindow.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE
                    | WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
            dialogWindow.setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.86f),
                    ViewGroup.LayoutParams.WRAP_CONTENT);
        }
    }

    private void applyDialogBackgroundBlur() {
        if (root == null || Build.VERSION.SDK_INT < 31) {
            return;
        }
        root.setRenderEffect(RenderEffect.createBlurEffect(
                dp(6), dp(6), Shader.TileMode.CLAMP));
    }

    private void clearDialogBackgroundBlur() {
        if (root != null && Build.VERSION.SDK_INT >= 31) {
            root.setRenderEffect(null);
        }
    }

    private void hideKeyboard() {
        InputMethodManager imm = (InputMethodManager) getSystemService(INPUT_METHOD_SERVICE);
        View focus = getCurrentFocus();
        if (imm != null && focus != null) {
            imm.hideSoftInputFromWindow(focus.getWindowToken(), 0);
        }
    }

