            item.setGravity(Gravity.CENTER_VERTICAL);
            item.setPadding(dp(14), 0, dp(14), 0);
            item.setBackground(round(i == selectedIndex ? accentSoft : Color.TRANSPARENT, dp(16), 0, 0));
