    private void showBookFontChoiceDialog(String titleText, String[] items, String[] values,
                                          int selectedIndex, final ChoiceHandler handler) {
        final AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(22), dp(20), dp(22), dp(18));
        box.setBackground(round(dialogSurfaceColor(), dp(26), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        TextView title = label(titleText, 22, Color.rgb(28, 28, 30), true);
        title.setPadding(0, 0, 0, dp(10));
        box.addView(title);

        ScrollView scroll = new ScrollView(this);
        disableForceDark(scroll);
        scroll.setVerticalScrollBarEnabled(false);
        LinearLayout list = new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        scroll.addView(list);
        for (int i = 0; i < items.length && i < values.length; i++) {
            final int index = i;
            final String style = values[i];
            final boolean remote = isDownloadableBookFont(style);
            final boolean ready = downloadedBookFontReady(style);
            final View.OnClickListener choose = new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    dialog.dismiss();
                    if (remote && !ready) {
                        downloadBookFont(style, items[index], new Runnable() {
                            @Override
                            public void run() {
                                handler.onChoice(index);
                            }
                        });
                    } else {
                        handler.onChoice(index);
                    }
                }
            };
            LinearLayout row = new LinearLayout(this);
            row.setOrientation(LinearLayout.HORIZONTAL);
            row.setGravity(Gravity.CENTER_VERTICAL);
            row.setPadding(dp(14), 0, dp(14), 0);
            row.setClickable(true);
            row.setBackground(round(i == selectedIndex ? accentSoft : Color.TRANSPARENT, dp(16), 0, 0));
            attachPressAnimation(row);

            LinearLayout textBox = new LinearLayout(this);
            textBox.setOrientation(LinearLayout.VERTICAL);
            textBox.setGravity(Gravity.CENTER_VERTICAL);
            TextView item = label(items[i], 19, Color.rgb(35, 35, 35), false);
            item.setGravity(Gravity.CENTER_VERTICAL);
            applyBookFontPreview(item, style, i == selectedIndex);
            textBox.addView(item);
            if (remote) {
                String statusText = ready ? (i == selectedIndex ? "已下载 · 正在使用" : "已下载") : "云端字体 · 点击下载";
                TextView status = label(statusText, 12, ready ? accent : Color.rgb(128, 132, 140), false);
                status.setPadding(0, dp(2), 0, 0);
                textBox.addView(status);
            }
            row.addView(textBox, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
            if (remote) {
                TextView action = label(ready ? "✓" : "↓", 20, ready ? accent : Color.rgb(112, 118, 128), true);
                action.setGravity(Gravity.CENTER);
                row.addView(action, new LinearLayout.LayoutParams(dp(36), dp(36)));
            }
            row.setOnClickListener(choose);
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(remote ? 68 : 58));
            lp.topMargin = dp(6);
            list.addView(row, lp);
        }
        box.addView(scroll, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(426)));
        showRoundedDialog(dialog, box);
    }

