    private void applyBookFontPreview(TextView view, String style, boolean selected) {
        int weight = selected ? Typeface.BOLD : Typeface.NORMAL;
        view.getPaint().setTextSkewX(0f);
        view.setTextScaleX(1f);
        view.getPaint().setFakeBoldText(false);
        view.setShadowLayer(0f, 0f, 0f, Color.TRANSPARENT);
        if (Build.VERSION.SDK_INT >= 21) {
            view.setLetterSpacing(0f);
        }
        if (isDownloadableBookFont(style)) {
            Typeface typeface = downloadedBookTypeface(style);
            view.setTypeface(typeface == null ? Typeface.create(Typeface.DEFAULT, weight) : Typeface.create(typeface, weight));
            view.setTextScaleX(1.0f);
            view.getPaint().setFakeBoldText(selected);
            view.getPaint().setTextSkewX("yozai".equals(style) ? -0.03f : 0f);
            int shadow = "yozai".equals(style) ? Color.argb(52, 88, 76, 62)
                    : ("xiaolai".equals(style) ? Color.argb(46, 92, 80, 70)
                    : ("marker".equals(style) ? Color.argb(48, 82, 70, 58) : Color.argb(38, 90, 90, 90)));
            view.setShadowLayer(dp(0.45f), 0f, dp(0.35f), shadow);
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(("marker".equals(style) || "zcool".equals(style)) ? 0.008f : 0.004f);
            }
            return;
        }
        if ("slim".equals(style)) {
            view.setTypeface(Typeface.create("sans-serif-condensed", weight));
            view.setTextScaleX(0.72f);
            if (Build.VERSION.SDK_INT >= 21) {
                view.setLetterSpacing(0.1f);
            }
            return;
        }
        view.setTypeface(Typeface.create(Typeface.DEFAULT, weight));
    }

    private void refreshChrome() {
        if (navHost != null) {
            FrameLayout.LayoutParams navLp = (FrameLayout.LayoutParams) navHost.getLayoutParams();
            navLp.height = dp(spaceByLayout(76, 72, 70));
            int navOuterMargin = dp(spaceByLayout(22, 20, 18));
            navLp.leftMargin = navOuterMargin;
            navLp.rightMargin = navOuterMargin;
            navLp.bottomMargin = navOuterMargin;
            navHost.setLayoutParams(navLp);
            navHost.setPadding(dp(7), dp(7), dp(7), dp(7));
            navHost.setBackgroundColor(Color.TRANSPARENT);
            if (navHost instanceof LiquidGlassNavLayout) {
                ((LiquidGlassNavLayout) navHost).refreshGlass();
            }
            navHost.setElevation(0f);
            updateNavIndicator(false);
        }
        if (fab != null) {
            FrameLayout.LayoutParams fabLp = (FrameLayout.LayoutParams) fab.getLayoutParams();
            int size = dp(spaceByLayout(62, 58, 56));
            fabLp.width = size;
            fabLp.height = size;
            fabLp.bottomMargin = dp(photoFabBottomMargin());
            fab.setLayoutParams(fabLp);
        }
    }

    private LinearLayout row(int gravity) {
        LinearLayout row = new LinearLayout(this);
        disableForceDark(row);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(gravity);
        return row;
    }

    private TextView label(String value, int sp, int color, boolean bold) {
        TextView text = new TextView(this);
        disableForceDark(text);
        text.setText(value);
        text.setTextSize(scaled(sp));
        text.setTextColor(themedTextColor(color));
        text.setIncludeFontPadding(true);
        text.setLineSpacing(0, 1.05f);
        text.setTypeface(Typeface.DEFAULT, bold ? Typeface.BOLD : Typeface.NORMAL);
        applyGlobalTextTypeface(text, bold);
        return text;
    }

    private void applyGlobalTextTypeface(TextView view, boolean bold) {
        if (view == null || !globalFontFollowsBookEnabled()) {
            return;
        }
        view.setTypeface(bookDetailTypeface(bold));
    }

    private void applyGlobalTypefaceRecursive(View view, boolean enabled) {
        if (view == null) {
            return;
        }
        if (view instanceof TextView) {
            TextView text = (TextView) view;
            Typeface current = text.getTypeface();
            boolean bold = current != null && current.isBold();
            text.setTypeface(enabled ? bookDetailTypeface(bold)
                    : Typeface.create(Typeface.DEFAULT, bold ? Typeface.BOLD : Typeface.NORMAL));
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                applyGlobalTypefaceRecursive(group.getChildAt(i), enabled);
            }
        }
    }

    private void resetSystemTypefaceRecursive(View view) {
        if (view == null) {
            return;
        }
        if (view instanceof TextView) {
            TextView text = (TextView) view;
            Typeface current = text.getTypeface();
            boolean bold = current != null && current.isBold();
            text.setTypeface(Typeface.create(Typeface.DEFAULT, bold ? Typeface.BOLD : Typeface.NORMAL));
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                resetSystemTypefaceRecursive(group.getChildAt(i));
            }
        }
    }

    private void refreshCurrentSurfaceTypefaces() {
        applyGlobalTypefaceRecursive(content, globalFontFollowsBookEnabled());
        resetSystemTypefaceRecursive(activeStickyHeader);
        resetSystemTypefaceRecursive(navHost);
        if (content != null) {
            content.invalidate();
        }
    }

