        private void drawCheckerCover(Canvas canvas) {
            int variant = coverVariant(7);
            int[] creams = {
                    Color.rgb(255, 244, 222), Color.rgb(237, 248, 224), Color.rgb(230, 242, 255),
                    Color.rgb(255, 232, 239), Color.rgb(244, 235, 255), Color.rgb(255, 246, 203),
                    Color.rgb(228, 248, 242)
            };
            int[] checks = {
                    Color.rgb(237, 126, 119), Color.rgb(100, 174, 112), Color.rgb(91, 157, 218),
                    Color.rgb(224, 120, 157), Color.rgb(147, 112, 196), Color.rgb(225, 174, 64),
                    Color.rgb(70, 169, 149)
            };
            int cream = creams[variant];
            int coral = checks[variant];
            paint.setStyle(Paint.Style.FILL);
            int columns = 3 + variant % 3;
            int rows = 4 + (variant + 1) % 3;
            float cellW = rect.width() / columns;
            float cellH = rect.height() / rows;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < columns; col++) {
                    paint.setColor((row + col) % 2 == 0 ? cream : coral);
                    canvas.drawRect(rect.left + col * cellW, rect.top + row * cellH,
                            Math.min(rect.right, rect.left + (col + 1) * cellW),
                            Math.min(rect.bottom, rect.top + (row + 1) * cellH), paint);
                }
            }
            paint.setColor(blendColor(coral, Color.BLACK, 0.24f));
            canvas.drawRect(rect.left, rect.top, rect.left + dp(21), rect.bottom, paint);
            float labelY = rect.centerY() + dp((variant % 3 - 1) * 18);
            RectF label = new RectF(rect.left + dp(31 + variant % 2 * 5), labelY - dp(24),
                    rect.right - dp(11), labelY + dp(24));
            paint.setColor(adjustAlpha(Color.WHITE, 224));
            canvas.drawRoundRect(label, dp(12), dp(12), paint);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(2));
            paint.setColor(adjustAlpha(blendColor(coral, Color.BLACK, 0.24f), 156));
            canvas.drawRoundRect(label, dp(12), dp(12), paint);
            drawCoverAccent(canvas, variant, label.centerX(), label.centerY(), dp(10));
            drawInnerBorder(canvas, adjustAlpha(Color.WHITE, 110));
        }

        private void drawCatCover(Canvas canvas) {
            int variant = coverVariant(7);
            int[] catBackgrounds = {
                    Color.rgb(229, 220, 255), Color.rgb(218, 239, 255), Color.rgb(255, 225, 235),
                    Color.rgb(222, 246, 226), Color.rgb(255, 239, 205), Color.rgb(216, 229, 250),
                    Color.rgb(241, 220, 244)
            };
            int[] catColors = {
                    Color.rgb(255, 250, 243), Color.rgb(245, 190, 139), Color.rgb(210, 214, 222),
                    Color.rgb(255, 226, 201), Color.rgb(180, 157, 137), Color.rgb(245, 245, 245),
                    Color.rgb(235, 184, 188)
            };
            paint.setShader(new LinearGradient(rect.left, rect.top, rect.right, rect.bottom,
                    catBackgrounds[variant], blendColor(catBackgrounds[variant], palette[1], 0.22f), Shader.TileMode.CLAMP));
            canvas.drawRect(rect, paint);
            paint.setShader(null);
            drawDailyVariantBackdrop(canvas, variant, Color.WHITE, blendColor(catBackgrounds[variant], Color.BLACK, 0.3f));
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(blendColor(catBackgrounds[variant], Color.BLACK, 0.34f));
            canvas.drawRect(rect.left, rect.top, rect.left + dp(22), rect.bottom, paint);
            float cx = rect.centerX() + dp(7 + (variant % 3 - 1) * 13);
            float cy = rect.centerY() + dp((variant % 2 == 0 ? -8 : 9));
            float r = Math.min(rect.width(), rect.height()) * (0.19f + variant % 3 * 0.018f);
            paint.setColor(catColors[variant]);
            shape.reset();
            shape.moveTo(cx - r, cy - r * 0.45f);
            shape.lineTo(cx - r * 0.72f, cy - r * 1.2f);
            shape.lineTo(cx - r * 0.25f, cy - r * 0.82f);
            shape.lineTo(cx + r * 0.28f, cy - r * 0.82f);
            shape.lineTo(cx + r * 0.74f, cy - r * 1.2f);
            shape.lineTo(cx + r, cy - r * 0.42f);
            shape.quadTo(cx + r * 1.08f, cy + r, cx, cy + r);
            shape.quadTo(cx - r * 1.08f, cy + r, cx - r, cy - r * 0.45f);
            shape.close();
            canvas.drawPath(shape, paint);
            paint.setColor(Color.rgb(73, 65, 88));
            if (variant == 1 || variant == 4) {
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(dp(1.7f));
                canvas.drawArc(new RectF(cx - r * 0.5f, cy - r * 0.18f, cx - r * 0.15f, cy + r * 0.08f),
                        10, 160, false, paint);
                canvas.drawArc(new RectF(cx + r * 0.15f, cy - r * 0.18f, cx + r * 0.5f, cy + r * 0.08f),
                        10, 160, false, paint);
                paint.setStyle(Paint.Style.FILL);
            } else {
                canvas.drawCircle(cx - r * 0.34f, cy - r * 0.05f, dp(2.2f), paint);
                canvas.drawCircle(cx + r * 0.34f, cy - r * 0.05f, dp(2.2f), paint);
            }
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(1.5f));
            canvas.drawArc(new RectF(cx - dp(8), cy + dp(1), cx, cy + dp(11)), 10, 80, false, paint);
            canvas.drawArc(new RectF(cx, cy + dp(1), cx + dp(8), cy + dp(11)), 90, 80, false, paint);
            drawCoverAccent(canvas, variant, rect.right - dp(25), rect.top + dp(27), dp(9));
            drawInnerBorder(canvas, adjustAlpha(Color.WHITE, 126));
        }

