        private void drawPastelGeometry(Canvas canvas, int type, float cx, float cy,
                                        float radius, int color) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(color);
            if (type == 4) {
                canvas.drawCircle(cx, cy, radius, paint);
                return;
            }
            shape.reset();
            if (type == 0) {
                for (int i = 0; i < 10; i++) {
                    double angle = -Math.PI / 2d + i * Math.PI / 5d;
                    float r = i % 2 == 0 ? radius : radius * 0.44f;
                    float x = cx + (float) Math.cos(angle) * r;
                    float y = cy + (float) Math.sin(angle) * r;
                    if (i == 0) {
                        shape.moveTo(x, y);
                    } else {
                        shape.lineTo(x, y);
                    }
                }
            } else if (type == 1) {
                shape.moveTo(cx, cy - radius);
                shape.lineTo(cx + radius * 0.92f, cy + radius * 0.76f);
                shape.lineTo(cx - radius * 0.92f, cy + radius * 0.76f);
            } else if (type == 2) {
                shape.addRoundRect(new RectF(cx - radius, cy - radius,
                        cx + radius, cy + radius), radius * 0.18f, radius * 0.18f, Path.Direction.CW);
            } else {
                shape.moveTo(cx, cy - radius);
                shape.lineTo(cx + radius, cy);
                shape.lineTo(cx, cy + radius);
                shape.lineTo(cx - radius, cy);
            }
            shape.close();
            canvas.drawPath(shape, paint);
        }

