        private void drawTritoneCover(Canvas canvas) {
            int variant = coverVariant(5);
            int[][] colors = {
                    {Color.rgb(244, 177, 188), Color.rgb(255, 224, 146), Color.rgb(145, 203, 191)},
                    {Color.rgb(151, 197, 235), Color.rgb(207, 184, 234), Color.rgb(244, 192, 150)},
                    {Color.rgb(184, 222, 191), Color.rgb(244, 208, 222), Color.rgb(238, 220, 151)},
                    {Color.rgb(95, 139, 181), Color.rgb(220, 229, 237), Color.rgb(121, 181, 170)},
                    {Color.rgb(229, 174, 132), Color.rgb(191, 177, 224), Color.rgb(151, 202, 226)}
            };
            paint.setStyle(Paint.Style.FILL);
            float third = rect.width() / 3f;
            for (int i = 0; i < 3; i++) {
                paint.setColor(colors[variant][i]);
                if (variant % 2 == 0) {
                    canvas.drawRect(rect.left + i * third, rect.top,
                            i == 2 ? rect.right : rect.left + (i + 1) * third, rect.bottom, paint);
                } else {
                    float band = rect.height() / 3f;
                    canvas.drawRect(rect.left, rect.top + i * band, rect.right,
                            i == 2 ? rect.bottom : rect.top + (i + 1) * band, paint);
                }
            }
            drawSpine(canvas, 24, 92);
            drawInnerBorder(canvas, adjustAlpha(Color.WHITE, 124));
        }

        private void drawClearCover(Canvas canvas) {
            int variant = coverVariant(7);
            paint.setShader(new LinearGradient(rect.left, rect.top, rect.right, rect.bottom,
                    blendColor(Color.WHITE, palette[2], variant % 3 * 0.04f),
                    blendColor(palette[0], Color.WHITE, 0.78f + variant % 3 * 0.04f), Shader.TileMode.CLAMP));
            canvas.drawRect(rect, paint);
            paint.setShader(null);
            drawDailyVariantBackdrop(canvas, variant, palette[0], palette[3]);

            paint.setStyle(Paint.Style.FILL);
            paint.setColor(adjustAlpha(palette[0], 26));
            canvas.drawCircle(variant % 2 == 0 ? rect.right - dp(28) : rect.left + dp(52),
                    rect.top + dp(25 + variant % 3 * 14), dp(25 + variant % 4 * 5), paint);
            paint.setColor(adjustAlpha(palette[3], 32));
            canvas.drawCircle(variant % 2 == 0 ? rect.left + dp(56) : rect.right - dp(36),
                    rect.bottom - dp(30 + variant % 3 * 10), dp(31 + (variant + 2) % 4 * 5), paint);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(1.4f));
            paint.setColor(adjustAlpha(palette[1], 68));
            float lineLeft = rect.left + dp(38 + variant % 3 * 5);
            for (int i = 0; i < 3 + variant % 3; i++) {
                float y = rect.top + dp(34 + variant % 2 * 8 + i * 25);
                float rightInset = dp(18 + (i + variant) % 3 * 9);
                canvas.drawLine(lineLeft, y, rect.right - rightInset, y, paint);
            }
            drawCoverAccent(canvas, variant, rect.right - dp(25), rect.bottom - dp(25), dp(7));
            drawSpine(canvas, 18, 92);
            drawInnerBorder(canvas, adjustAlpha(Color.WHITE, 178));
        }

        private void drawSpine(Canvas canvas, int darkAlpha, int lightAlpha) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(adjustAlpha(Color.BLACK, darkAlpha));
            canvas.drawRect(rect.left, rect.top, rect.left + dp(20), rect.bottom, paint);
            paint.setColor(adjustAlpha(Color.WHITE, lightAlpha));
            canvas.drawRect(rect.left + dp(20), rect.top, rect.left + dp(22), rect.bottom, paint);
        }

        private void drawInnerBorder(Canvas canvas, int color) {
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(1));
            paint.setColor(color);
            canvas.drawRoundRect(new RectF(rect.left + dp(8), rect.top + dp(8),
                    rect.right - dp(8), rect.bottom - dp(8)), dp(14), dp(14), paint);
        }

        private void drawCoverPattern(Canvas canvas, int mode) {
            drawTriColorPanels(canvas, mode);
            float left = rect.left + dp(31);
            float top = rect.top + dp(20);
            if (mode == Calendar.MONDAY) {
                drawApple(canvas, left + dp(20), top + dp(24), dp(14));
                drawBanana(canvas, left + dp(70), top + dp(31), dp(19));
                drawCitrus(canvas, left + dp(50), top + dp(92), dp(13));
            } else if (mode == Calendar.TUESDAY) {
                drawCarrot(canvas, left + dp(20), top + dp(24), dp(25));
                drawPeas(canvas, left + dp(72), top + dp(36), dp(10));
                drawLeaf(canvas, left + dp(46), top + dp(94), dp(15), Color.rgb(108, 232, 149));
            } else if (mode == Calendar.WEDNESDAY) {
                drawPlate(canvas, left + dp(25), top + dp(31), dp(25), Color.rgb(255, 245, 210));
                drawMeat(canvas, left + dp(72), top + dp(34), dp(20));
                drawNoodles(canvas, left + dp(50), top + dp(94), dp(24));
            } else if (mode == Calendar.THURSDAY) {
                drawRiceBowl(canvas, left + dp(26), top + dp(32), dp(23));
                drawEggPan(canvas, left + dp(76), top + dp(36), dp(21));
                drawShrimp(canvas, left + dp(52), top + dp(96), dp(16));
            } else if (mode == Calendar.FRIDAY) {
                drawCookie(canvas, left + dp(22), top + dp(30), dp(17));
                drawChocolate(canvas, left + dp(72), top + dp(34), dp(21));
                drawCake(canvas, left + dp(50), top + dp(95), dp(24));
            } else if (mode == Calendar.SATURDAY) {
                drawSnackBag(canvas, left + dp(23), top + dp(32), dp(24));
                drawCandy(canvas, left + dp(74), top + dp(34), dp(17));
                drawBurger(canvas, left + dp(50), top + dp(96), dp(25));
            } else {
                drawHotPot(canvas, left + dp(28), top + dp(34), dp(25));
                drawDrink(canvas, left + dp(76), top + dp(34), dp(22));
                drawStrawberry(canvas, left + dp(50), top + dp(96), dp(16));
            }

            drawSmallFoodDots(canvas, mode);
        }

        private void drawTriColorPanels(Canvas canvas, int mode) {
            int panelA = adjustAlpha(palette[2], 82);
            int panelB = adjustAlpha(palette[3], 72);
            paint.setStyle(Paint.Style.FILL);
            if (mode == Calendar.TUESDAY || mode == Calendar.FRIDAY || mode == Calendar.SATURDAY) {
                paint.setColor(panelA);
                shape.reset();
                shape.moveTo(rect.left + dp(22), rect.top);
                shape.lineTo(rect.right, rect.top);
                shape.lineTo(rect.right, rect.top + rect.height() * 0.34f);
                shape.lineTo(rect.left + dp(22), rect.top + rect.height() * 0.58f);
                shape.close();
                canvas.drawPath(shape, paint);
                paint.setColor(panelB);
                shape.reset();
                shape.moveTo(rect.left + dp(22), rect.bottom);
                shape.lineTo(rect.right, rect.bottom);
                shape.lineTo(rect.right, rect.bottom - rect.height() * 0.28f);
                shape.lineTo(rect.left + dp(22), rect.bottom - rect.height() * 0.08f);
                shape.close();
                canvas.drawPath(shape, paint);
            } else {
                paint.setColor(panelA);
                canvas.drawCircle(rect.right - dp(26), rect.top + dp(28), dp(34), paint);
                paint.setColor(panelB);
                canvas.drawCircle(rect.left + dp(40), rect.bottom - dp(30), dp(38), paint);
            }
        }

        private void drawSmallFoodDots(Canvas canvas, int mode) {
            int seed = Math.abs((date + mode).hashCode());
            for (int i = 0; i < 8; i++) {
                float x = rect.left + dp(32) + ((seed + i * 29) % Math.max(1, (int) (rect.width() - dp(56))));
                float y = rect.top + dp(18) + (((seed / 5) + i * 23) % Math.max(1, (int) (rect.height() - dp(36))));
                if (i % 3 == 0) {
                    drawSpark(canvas, x, y, dp(4), palette[2]);
                } else {
                    paint.setStyle(Paint.Style.FILL);
                    paint.setColor(adjustAlpha(i % 2 == 0 ? palette[2] : palette[3], 112));
                    canvas.drawCircle(x, y, dp(2 + i % 2), paint);
                }
            }
        }

        private void drawApple(Canvas canvas, float x, float y, float size) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 86, 91));
            canvas.drawCircle(x - size * 0.32f, y, size * 0.58f, paint);
            canvas.drawCircle(x + size * 0.32f, y, size * 0.58f, paint);
            paint.setColor(Color.rgb(92, 184, 82));
            drawLeaf(canvas, x + size * 0.35f, y - size * 0.86f, size * 0.35f, Color.rgb(92, 184, 82));
            paint.setColor(adjustAlpha(Color.WHITE, 90));
            canvas.drawCircle(x - size * 0.35f, y - size * 0.16f, size * 0.13f, paint);
        }

        private void drawBanana(Canvas canvas, float x, float y, float size) {
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(7));
            paint.setStrokeCap(Paint.Cap.ROUND);
            paint.setColor(Color.rgb(255, 222, 82));
            shape.reset();
            shape.moveTo(x - size, y - size * 0.22f);
            shape.quadTo(x, y + size * 0.88f, x + size, y - size * 0.28f);
            canvas.drawPath(shape, paint);
            paint.setStrokeWidth(dp(2));
            paint.setColor(adjustAlpha(Color.rgb(151, 111, 47), 130));
            canvas.drawPoint(x - size, y - size * 0.22f, paint);
            canvas.drawPoint(x + size, y - size * 0.28f, paint);
        }

        private void drawCitrus(Canvas canvas, float x, float y, float size) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 186, 57));
            canvas.drawCircle(x, y, size, paint);
            paint.setStyle(Paint.Style.STROKE);
            paint.setStrokeWidth(dp(1));
            paint.setColor(adjustAlpha(Color.WHITE, 116));
            for (int i = 0; i < 6; i++) {
                double a = Math.PI * 2 * i / 6;
                canvas.drawLine(x, y, x + (float) Math.cos(a) * size * 0.78f,
                        y + (float) Math.sin(a) * size * 0.78f, paint);
            }
        }

        private void drawCarrot(Canvas canvas, float x, float y, float size) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(Color.rgb(255, 131, 54));
            shape.reset();
            shape.moveTo(x - size * 0.32f, y - size * 0.35f);
            shape.lineTo(x + size * 0.52f, y - size * 0.05f);
            shape.lineTo(x - size * 0.38f, y + size * 0.82f);
            shape.close();
            canvas.drawPath(shape, paint);
            drawLeaf(canvas, x - size * 0.38f, y - size * 0.48f, size * 0.28f, Color.rgb(82, 203, 103));
            drawLeaf(canvas, x - size * 0.12f, y - size * 0.52f, size * 0.25f, Color.rgb(92, 220, 121));
        }

