    private class WrapFlowLayout extends ViewGroup {
        private int itemGap = dp(8);
        private int lineGap = dp(8);

        WrapFlowLayout(Context context) {
            super(context);
        }

        void setItemGap(int gap) {
            itemGap = Math.max(0, gap);
        }

        void setLineGap(int gap) {
            lineGap = Math.max(0, gap);
        }

        @Override
        protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
            int widthSize = View.MeasureSpec.getSize(widthMeasureSpec);
            int maxWidth = Math.max(0, widthSize - getPaddingLeft() - getPaddingRight());
            int x = 0;
            int y = getPaddingTop();
            int lineHeight = 0;
            for (int i = 0; i < getChildCount(); i++) {
                View child = getChildAt(i);
                if (child.getVisibility() == GONE) {
                    continue;
                }
                measureChildWithMargins(child, widthMeasureSpec, 0, heightMeasureSpec, 0);
                MarginLayoutParams lp = (MarginLayoutParams) child.getLayoutParams();
                int childW = child.getMeasuredWidth() + lp.leftMargin + lp.rightMargin;
                int childH = child.getMeasuredHeight() + lp.topMargin + lp.bottomMargin;
                if (x > 0 && x + childW > maxWidth) {
                    x = 0;
                    y += lineHeight + lineGap;
                    lineHeight = 0;
                }
                x += childW + (x > 0 ? itemGap : 0);
                lineHeight = Math.max(lineHeight, childH);
            }
            y += lineHeight + getPaddingBottom();
            setMeasuredDimension(resolveSize(widthSize, widthMeasureSpec), resolveSize(y, heightMeasureSpec));
        }

        @Override
        protected void onLayout(boolean changed, int l, int t, int r, int b) {
            int maxWidth = Math.max(0, r - l - getPaddingLeft() - getPaddingRight());
            int x = getPaddingLeft();
            int y = getPaddingTop();
            int lineHeight = 0;
            for (int i = 0; i < getChildCount(); i++) {
                View child = getChildAt(i);
                if (child.getVisibility() == GONE) {
                    continue;
                }
                MarginLayoutParams lp = (MarginLayoutParams) child.getLayoutParams();
                int childW = child.getMeasuredWidth();
                int childH = child.getMeasuredHeight();
                int totalW = childW + lp.leftMargin + lp.rightMargin;
                int totalH = childH + lp.topMargin + lp.bottomMargin;
                if (x > getPaddingLeft() && x - getPaddingLeft() + totalW > maxWidth) {
                    x = getPaddingLeft();
                    y += lineHeight + lineGap;
                    lineHeight = 0;
                }
                int left = x + lp.leftMargin;
                int top = y + lp.topMargin;
                child.layout(left, top, left + childW, top + childH);
                x += totalW + itemGap;
                lineHeight = Math.max(lineHeight, totalH);
            }
        }

        @Override
        protected LayoutParams generateDefaultLayoutParams() {
            return new MarginLayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT);
        }

        @Override
        protected LayoutParams generateLayoutParams(LayoutParams p) {
            return new MarginLayoutParams(p);
        }

        @Override
        public LayoutParams generateLayoutParams(android.util.AttributeSet attrs) {
            return new MarginLayoutParams(getContext(), attrs);
        }

        @Override
        protected boolean checkLayoutParams(LayoutParams p) {
            return p instanceof MarginLayoutParams;
        }
    }

    private class NotebookMedia {
        String fileName;
        boolean sticker;

        NotebookMedia(String fileName, boolean sticker) {
            this.fileName = fileName;
            this.sticker = sticker;
        }
    }

    private class PhotoAction {
        String date;
        String mealKey;
        String fileName;
        String arrayKey;
        String title;
        View closeButton;
        View rotateButton;
        View itemView;
        List<String> stackNames;
        List<View> stackChildViews;
        boolean[] stackExpandedState;
        boolean editing;
        boolean rotating;
        float baseRotation;
        float baseTranslationX;
        float baseTranslationY;
        float baseElevation;

        PhotoAction(String date, String mealKey, String fileName, String arrayKey, String title, View closeButton) {
            this(date, mealKey, fileName, arrayKey, title, closeButton, null);
        }

        PhotoAction(String date, String mealKey, String fileName, String arrayKey, String title,
                    View closeButton, View rotateButton) {
            this.date = date;
            this.mealKey = mealKey;
            this.fileName = fileName;
            this.arrayKey = arrayKey;
            this.title = title;
            this.closeButton = closeButton;
            this.rotateButton = rotateButton;
        }

        void enterEdit(View item) {
            enterEdit(item, true);
        }

        void enterEdit(View item, boolean feedback) {
            editing = true;
            baseRotation = item == null ? 0f : item.getRotation();
            baseTranslationX = item == null ? 0f : item.getTranslationX();
            baseTranslationY = item == null ? 0f : item.getTranslationY();
            baseElevation = item == null ? 0f : item.getElevation();
            if (closeButton != null) {
                closeButton.setVisibility(View.VISIBLE);
                closeButton.bringToFront();
            }
            if (rotateButton != null) {
                rotateButton.setVisibility(View.VISIBLE);
                rotateButton.bringToFront();
            }
            if (feedback) {
                playMediaEditFeedback();
            }
            shakeMediaItem(item, 0, baseRotation);
        }

        void exitEdit() {
            editing = false;
            if (closeButton != null) {
                closeButton.setVisibility(View.GONE);
            }
            if (rotateButton != null) {
                rotateButton.setVisibility(View.GONE);
            }
        }

        boolean canMoveTo(PhotoAction other) {
            return other != null
                    && date.equals(other.date)
                    && mealKey.equals(other.mealKey)
                    && arrayKey.equals(other.arrayKey)
                    && !fileName.equals(other.fileName);
        }

        boolean isStacked() {
            JSONObject meal = optObj(ensureDay(date), mealKey);
            return isMediaStacked(meal, arrayKey, fileName);
        }

        boolean usesExpandedChildren() {
            return stackExpandedState != null
                    && stackExpandedState.length > 0
                    && stackExpandedState[0]
                    && stackChildViews != null
                    && !stackChildViews.isEmpty();
        }

        boolean stackWith(PhotoAction other) {
            if (canMoveTo(other)) {
                return stackMealMedia(date, mealKey, arrayKey, fileName, other.fileName);
            }
            return false;
        }

        boolean reorderTo(PhotoAction other, boolean insertAfter) {
            if (canMoveTo(other)) {
                return reorderMealMedia(date, mealKey, arrayKey, fileName, other.fileName, insertAfter);
            }
            return false;
        }

        boolean unstack() {
            return unstackMealMedia(date, mealKey, arrayKey, fileName);
        }

        boolean unstackGroup() {
            return unstackMediaGroup(date, mealKey, arrayKey, stackNames);
        }
    }

    private class EmojiAdapter extends BaseAdapter {
        @Override
        public int getCount() {
            return EMOJIS.length;
        }

        @Override
        public Object getItem(int position) {
            return EMOJIS[position];
        }

        @Override
        public long getItemId(int position) {
            return position;
        }

        @Override
        public View getView(int position, View convertView, ViewGroup parent) {
            TextView text = label(EMOJIS[position], 28, Color.rgb(25, 25, 25), false);
            text.setGravity(Gravity.CENTER);
            text.setPadding(0, dp(8), 0, dp(8));
            return text;
        }
    }

