    private static class CloudResult {
        boolean ok;
        JSONObject user;
        String message = "";

        static CloudResult fail(String message) {
            CloudResult result = new CloudResult();
            result.ok = false;
            result.message = message == null ? "" : message;
            return result;
        }
    }

